function badgeNameToEmblemSlug(badgeName) {
  return String(badgeName || "First Aid")
    .trim()
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function updateConstructionBadgeEmblem(badgeName) {
  const cleanName = badgeName || state.currentBadge || "First Aid";
  const slug = badgeNameToEmblemSlug(cleanName);
  const emblemUrl = `/assets/badge_emblems/${slug}.png?v=20261016c`;
  const overlayImg = document.getElementById("construction-badge-emblem-overlay");
  const workorderImg = document.getElementById("construction-workorder-emblem");
  const workorderTitle = document.getElementById("construction-workorder-title");
  const stageHeading = document.getElementById("construction-stage-heading");
  if (overlayImg) {
    overlayImg.src = emblemUrl;
    overlayImg.alt = `${cleanName} Merit Badge Emblem`;
  }
  if (workorderImg) {
    workorderImg.src = emblemUrl;
    workorderImg.alt = `${cleanName} Merit Badge Emblem`;
  }
  if (workorderTitle) {
    workorderTitle.textContent = `${cleanName} Merit Badge`;
  }
  if (stageHeading) {
    stageHeading.textContent = state.constructionManualPreview
      ? `Scout Slide Construction Showcase — ${cleanName} Merit Badge`
      : `Building ${cleanName} Merit Badge Slide Deck...`;
  }
}

const CONSTRUCTION_CONCEPT_ORDER = ["iso_heavy", "camp_pioneer", "clay_workshop"];
const CONSTRUCTION_PRELOADED_IMAGES = new Map();

function preloadConstructionAnimationFrames() {
  for (const conceptKey of CONSTRUCTION_CONCEPT_ORDER) {
    const concept = CONSTRUCTION_ANIM_CONCEPTS[conceptKey];
    if (!concept || !Array.isArray(concept.frames)) continue;
    for (const frame of concept.frames) {
      if (!frame.src || CONSTRUCTION_PRELOADED_IMAGES.has(frame.src)) continue;
      const preImg = new Image();
      preImg.decoding = "async";
      preImg.loading = "eager";
      preImg.src = frame.src;
      if (typeof preImg.decode === "function") {
        preImg.decode().catch(() => {});
      }
      CONSTRUCTION_PRELOADED_IMAGES.set(frame.src, preImg);
    }
  }
}

// Kick off proactive frame preloading immediately upon script evaluation
preloadConstructionAnimationFrames();

function syncConstructionConceptButtons(activeConcept) {
  document.querySelectorAll(".m3-construction-concept-btn").forEach((b) => {
    b.classList.toggle("active", b.getAttribute("data-concept") === activeConcept);
  });
}

function renderConstructionFrame(frameIdx, autoCycleConcept = true) {
  let currentConceptKey = state.constructionConcept || "iso_heavy";
  let conceptObj = CONSTRUCTION_ANIM_CONCEPTS[currentConceptKey] || CONSTRUCTION_ANIM_CONCEPTS.iso_heavy;
  let frames = conceptObj.frames;
  let safeIdx = frameIdx;

  if (autoCycleConcept && (frameIdx >= frames.length || frameIdx < 0)) {
    const curConceptIdx = Math.max(0, CONSTRUCTION_CONCEPT_ORDER.indexOf(currentConceptKey));
    if (frameIdx >= frames.length) {
      const nextConceptIdx = (curConceptIdx + 1) % CONSTRUCTION_CONCEPT_ORDER.length;
      currentConceptKey = CONSTRUCTION_CONCEPT_ORDER[nextConceptIdx];
      state.constructionConcept = currentConceptKey;
      conceptObj = CONSTRUCTION_ANIM_CONCEPTS[currentConceptKey];
      frames = conceptObj.frames;
      safeIdx = 0;
      syncConstructionConceptButtons(currentConceptKey);
    } else if (frameIdx < 0) {
      const prevConceptIdx = (curConceptIdx - 1 + CONSTRUCTION_CONCEPT_ORDER.length) % CONSTRUCTION_CONCEPT_ORDER.length;
      currentConceptKey = CONSTRUCTION_CONCEPT_ORDER[prevConceptIdx];
      state.constructionConcept = currentConceptKey;
      conceptObj = CONSTRUCTION_ANIM_CONCEPTS[currentConceptKey];
      frames = conceptObj.frames;
      safeIdx = frames.length - 1;
      syncConstructionConceptButtons(currentConceptKey);
    }
  } else {
    safeIdx = ((frameIdx % frames.length) + frames.length) % frames.length;
  }

  state.constructionFrameIdx = safeIdx;
  const frame = frames[safeIdx];

  const imgEl = document.getElementById("construction-frame-img");
  const slotEl = document.getElementById("construction-emblem-slot");
  const overlayImgEl = document.getElementById("construction-badge-emblem-overlay");
  const fgCableEl = document.getElementById("construction-foreground-cable-overlay");
  const titleEl = document.getElementById("construction-step-title");
  const descEl = document.getElementById("construction-step-desc");
  const counterEl = document.getElementById("construction-frame-counter");
  const dotsEl = document.getElementById("construction-frame-dots");

  const applyFrameAndEmblem = () => {
    if (imgEl && imgEl.getAttribute("src") !== frame.src) {
      imgEl.src = frame.src;
    }
    if (slotEl && frame.emblemSlot) {
      slotEl.style.left = frame.emblemSlot.left;
      slotEl.style.top = frame.emblemSlot.top;
      slotEl.style.width = frame.emblemSlot.width;
      if (overlayImgEl) {
        overlayImgEl.style.transform = frame.emblemSlot.imgTransform || "none";
        overlayImgEl.style.filter = frame.emblemSlot.imgFilter || "";
      }
    }
    if (fgCableEl) {
      const isHelicopterHoistFrame =
        currentConceptKey === "iso_heavy" &&
        (safeIdx === 3 || String(frame.src || "").includes("iso_heavy_4_helicopter_emblem"));
      fgCableEl.classList.toggle("hidden", !isHelicopterHoistFrame);
    }
    imgEl?.classList.remove("fade-step");
  };

  let preloaded = CONSTRUCTION_PRELOADED_IMAGES.get(frame.src);
  if (!preloaded) {
    preloaded = new Image();
    preloaded.src = frame.src;
    CONSTRUCTION_PRELOADED_IMAGES.set(frame.src, preloaded);
  }

  if (imgEl && imgEl.getAttribute("src") !== frame.src) {
    if (preloaded.complete && preloaded.naturalWidth > 0) {
      applyFrameAndEmblem();
    } else {
      preloaded.addEventListener("load", applyFrameAndEmblem, { once: true });
      preloaded.addEventListener("error", applyFrameAndEmblem, { once: true });
    }
  } else {
    applyFrameAndEmblem();
  }

  if (titleEl) titleEl.textContent = frame.title;
  if (descEl) descEl.textContent = frame.desc;
  if (counterEl) {
    const animNum = CONSTRUCTION_CONCEPT_ORDER.indexOf(currentConceptKey) + 1;
    counterEl.textContent = `Animation ${animNum}/${CONSTRUCTION_CONCEPT_ORDER.length} • Frame ${safeIdx + 1}/${frames.length} (Auto-Cycle)`;
  }

  if (dotsEl) {
    dotsEl.innerHTML = "";
    frames.forEach((_f, idx) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `m3-construction-dot${idx === safeIdx ? " active" : ""}`;
      btn.textContent = String(idx + 1);
      btn.title = `Jump to Frame ${idx + 1}`;
      btn.addEventListener("click", () => {
        renderConstructionFrame(idx, false);
      });
      dotsEl.appendChild(btn);
    });
  }
}

function startConstructionAnimationTimer() {
  if (state.constructionTimerId) {
    clearInterval(state.constructionTimerId);
    state.constructionTimerId = null;
  }
  if (!state.constructionPlaying) return;
  state.constructionTimerId = setInterval(() => {
    const stageEl = document.getElementById("slide-construction-stage");
    if (!stageEl || stageEl.classList.contains("hidden")) return;
    renderConstructionFrame(state.constructionFrameIdx + 1);
  }, 2100);
}

function showConstructionAnimationStage(badgeName, isManualPreview = false) {
  state.constructionManualPreview = Boolean(isManualPreview);
  updateConstructionBadgeEmblem(badgeName || state.currentBadge);
  const animStage = document.getElementById("slide-construction-stage");
  const closeBtn = document.getElementById("btn-close-construction-anim");
  const statusPill = document.getElementById("construction-status-pill");
  const toolbarEl = document.getElementById("slide-stage-toolbar");
  const reqJumpEl = document.getElementById("req-quick-jump-bar");
  const slideStageEl = document.getElementById("widescreen-slide-stage");
  const understageDrawerEl = document.getElementById("understage-drawer");
  const codesignEl = document.getElementById("slide-codesign-bar");
  const notesCardEl = document.getElementById("slide-speaker-notes-card");
  const filmstripToolbarEl = document.getElementById("filmstrip-toolbar");

  animStage?.classList.remove("hidden");
  if (closeBtn) {
    closeBtn.classList.toggle("hidden", !isManualPreview && !state.currentResult);
  }
  if (statusPill) {
    statusPill.textContent = isManualPreview ? "🎬 INTERACTIVE ANIMATION SHOWCASE" : "🏗️ SCOUT SLIDE CREW AT WORK";
  }
  toolbarEl?.classList.add("hidden");
  reqJumpEl?.classList.add("hidden");
  slideStageEl?.classList.add("hidden");
  understageDrawerEl?.classList.add("hidden");
  codesignEl?.classList.add("hidden");
  notesCardEl?.classList.add("hidden");
  filmstripToolbarEl?.classList.add("hidden");

  renderConstructionFrame(state.constructionFrameIdx);
  startConstructionAnimationTimer();
}

function hideConstructionAnimationStage() {
  state.constructionManualPreview = false;
  const animStage = document.getElementById("slide-construction-stage");
  const toolbarEl = document.getElementById("slide-stage-toolbar");
  const reqJumpEl = document.getElementById("req-quick-jump-bar");
  const slideStageEl = document.getElementById("widescreen-slide-stage");
  const understageDrawerEl = document.getElementById("understage-drawer");
  const notesCardEl = document.getElementById("slide-speaker-notes-card");
  const filmstripToolbarEl = document.getElementById("filmstrip-toolbar");

  animStage?.classList.add("hidden");
  toolbarEl?.classList.remove("hidden");
  reqJumpEl?.classList.remove("hidden");
  slideStageEl?.classList.remove("hidden");
  understageDrawerEl?.classList.remove("hidden");
  notesCardEl?.classList.remove("hidden");
  filmstripToolbarEl?.classList.remove("hidden");
  syncUnderstageDrawerVisibility(state.activeSlideIdx);
  if (state.constructionTimerId) {
    clearInterval(state.constructionTimerId);
    state.constructionTimerId = null;
  }
}

function syncUnderstageDrawerVisibility(slideIdx = state.activeSlideIdx) {
  const activeTab = state.activeUnderstageTab || "notes";
  const notesCard = document.getElementById("slide-speaker-notes-card");
  const codesignCard = document.getElementById("slide-codesign-bar");
  const quickeditCard = document.getElementById("slide-quick-edit-card");
  const traceCard = document.getElementById("trace-telemetry-card");

  document.querySelectorAll("[data-understage-tab]").forEach((btn) => {
    const t = btn.getAttribute("data-understage-tab");
    const isAct = t === activeTab;
    btn.classList.toggle("active", isAct);
    btn.setAttribute("aria-selected", isAct ? "true" : "false");
  });

  notesCard?.classList.toggle("hidden", activeTab !== "notes");
  codesignCard?.classList.toggle("hidden", activeTab !== "codesign");
  quickeditCard?.classList.toggle("hidden", activeTab !== "quickedit");
  traceCard?.classList.toggle("hidden", activeTab !== "trace");
  if (activeTab === "trace" && typeof renderWorkflowTraceAndFinopsCard === "function" && state.currentResult) {
    renderWorkflowTraceAndFinopsCard(state.currentResult);
  }
}

let _workbenchToastTimer = null;
function showToast(message, tone = "info") {
  const toastEl = document.getElementById("workbench-toast-notification");
  if (!toastEl) return;
  toastEl.textContent = String(message || "");
  toastEl.classList.remove("hidden", "is-warning", "is-error", "is-visible");
  if (tone === "warning") toastEl.classList.add("is-warning");
  if (tone === "error") toastEl.classList.add("is-error");
  void toastEl.offsetWidth;
  toastEl.classList.add("is-visible");
  if (_workbenchToastTimer) clearTimeout(_workbenchToastTimer);
  _workbenchToastTimer = setTimeout(() => {
    toastEl.classList.remove("is-visible");
    setTimeout(() => toastEl.classList.add("hidden"), 220);
  }, 3600);
}
window.showToast = showToast;

function checkTopBarProfileSpace() {
  const chip = document.getElementById("top-counselor-profile-chip");
  const topBar =
    document.getElementById("top-app-bar") ||
    document.querySelector(".m3-top-bar") ||
    document.querySelector(".m3-top-app-bar");
  if (!chip || !topBar) return;
  chip.classList.remove("is-compact-name-only");
  if (topBar.scrollWidth > topBar.clientWidth + 4 || window.innerWidth < 1260) {
    chip.classList.add("is-compact-name-only");
  }
}

function syncCounselorProfileSummary() {
  const cName = (document.getElementById("input-counselor-name")?.value || "Scoutmaster Bob").trim();
  const tName = (document.getElementById("input-troop-name")?.value || "Troop 123, My Council").trim();
  const summaryText = tName ? `${cName} • ${tName}` : cName;
  const sidebarSumEl = document.getElementById("sidebar-profile-summary-text");
  const topChipEl = document.getElementById("top-counselor-chip-text");
  const topChipNameEl = document.getElementById("top-counselor-chip-name");
  const topChipAffilEl = document.getElementById("top-counselor-chip-affil");
  const topProfileChip = document.getElementById("top-counselor-profile-chip");
  if (sidebarSumEl) sidebarSumEl.textContent = summaryText;
  if (topChipNameEl && topChipAffilEl) {
    topChipNameEl.textContent = cName;
    topChipAffilEl.textContent = tName ? ` • ${tName}` : "";
  } else if (topChipEl) {
    topChipEl.textContent = summaryText;
  }
  if (topProfileChip) {
    topProfileChip.title = `${summaryText} — Click to edit Counselor & Troop Profile`;
  }
  requestAnimationFrame(checkTopBarProfileSpace);
}
window.addEventListener("resize", checkTopBarProfileSpace);

function formatSlideThemeLabel(tierCode) {
  const upper = String(tierCode || "BEAUTIFIED").toUpperCase();
  if (upper === "STANDARD" || upper === "CRISP_WHITE" || upper === "CRISP WHITE") return "Crisp White";
  if (upper === "STUDIO" || upper === "DARK_SLATE" || upper === "DARK SLATE") return "Dark Slate";
  return "Warm Cream";
}

function markDeckConfigDirty() {
  state.deckConfigDirty = true;
  const dirtyBanner = document.getElementById("deck-dirty-banner");
  const genBtn = document.getElementById("btn-generate-deck");
  dirtyBanner?.classList.remove("hidden");
  if (genBtn && !genBtn.disabled) {
    genBtn.classList.add("m3-btn-dirty-pulse");
    genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">🔄</span> Update Slide Deck &amp; Workbook';
  }
  // Live-update Visual Polish & Asset Mode preview in sidebar before running
  const tierVal = document.getElementById("beautification-select")?.value || "BEAUTIFIED";
  const depthVal = document.getElementById("depth-select")?.value || "Deep Dive / Camp School Deck";
  const isDeep = depthVal.toLowerCase().includes("deep");
  const finopsUsdEl = document.getElementById("finops-cost-usd");
  const finopsMetaEl = document.getElementById("finops-cost-meta");
  if (finopsUsdEl) {
    finopsUsdEl.innerHTML =
      tierVal === "STANDARD"
        ? `<strong>Visual Assets:</strong> Pamphlet Figures Only (Lightweight)`
        : `<strong>Visual Assets:</strong> 100% Pre-Cached (8-Bit PNG)`;
  }
  if (finopsMetaEl) {
    finopsMetaEl.textContent = `${formatSlideThemeLabel(tierVal)} • ${isDeep ? "Deep Dive" : "Standard"}`;
  }
}

function clearDeckConfigDirty() {
  state.deckConfigDirty = false;
  const dirtyBanner = document.getElementById("deck-dirty-banner");
  const genBtn = document.getElementById("btn-generate-deck");
  dirtyBanner?.classList.add("hidden");
  genBtn?.classList.remove("m3-btn-dirty-pulse");
}

function bindConstructionAnimationControls() {
  document.querySelectorAll(".m3-construction-concept-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const concept = btn.getAttribute("data-concept") || "iso_heavy";
      state.constructionConcept = concept;
      state.constructionFrameIdx = 0;
      document.querySelectorAll(".m3-construction-concept-btn").forEach((b) => {
        b.classList.toggle("active", b.getAttribute("data-concept") === concept);
      });
      renderConstructionFrame(0);
      startConstructionAnimationTimer();
    });
  });

  document.getElementById("btn-construction-prev")?.addEventListener("click", () => {
    renderConstructionFrame(state.constructionFrameIdx - 1);
  });

  document.getElementById("btn-construction-next")?.addEventListener("click", () => {
    renderConstructionFrame(state.constructionFrameIdx + 1);
  });

  const playPauseBtn = document.getElementById("btn-construction-playpause");
  playPauseBtn?.addEventListener("click", () => {
    state.constructionPlaying = !state.constructionPlaying;
    playPauseBtn.textContent = state.constructionPlaying ? "⏸" : "▶";
    if (state.constructionPlaying) {
      startConstructionAnimationTimer();
    } else if (state.constructionTimerId) {
      clearInterval(state.constructionTimerId);
      state.constructionTimerId = null;
    }
  });

  document.getElementById("btn-toggle-construction-anim")?.addEventListener("click", () => {
    showConstructionAnimationStage(state.currentBadge, true);
  });

  document.getElementById("btn-close-construction-anim")?.addEventListener("click", () => {
    if (state.currentResult) {
      hideConstructionAnimationStage();
      renderActiveSlide(state.activeSlideIdx);
    }
  });

  renderConstructionFrame(0);
  startConstructionAnimationTimer();
}

window.isAnyModalOpen = function() {
  const modals = document.querySelectorAll(".m3-modal-backdrop");
  for (const m of modals) {
    if (m.classList.contains("open") || !m.classList.contains("hidden")) {
      return true;
    }
  }
  return false;
};

window.closeTopmostModal = function() {
  const orderedModalIds = [
    "delete-workspace-confirm-modal",
    "edit-template-meta-modal",
    "image-zoom-lightbox-modal",
    "image-studio-modal",
    "patch-gallery-modal",
    "template-studio-modal",
    "saved-workspaces-modal",
    "mcp-hub-modal",
    "docs-viewer-modal",
    "gslides-export-modal",
    "ai-polish-finops-modal",
    "keyboard-shortcuts-modal",
    "admin-pin-modal",
    "admin-unlock-modal",
    "insert-custom-slide-modal"
  ];
  for (const id of orderedModalIds) {
    const m = document.getElementById(id);
    if (m && (m.classList.contains("open") || !m.classList.contains("hidden"))) {
      const closeBtn = m.querySelector(".m3-btn-close, .close-btn, [id^='btn-close']");
      if (closeBtn) {
        closeBtn.click();
      } else {
        m.classList.remove("open");
        m.classList.add("hidden");
      }
      return;
    }
  }
};

document.addEventListener("click", (ev) => {
  if (ev.target && ev.target.classList && ev.target.classList.contains("m3-modal-backdrop")) {
    if (state.activeDemoTour && !state.activeDemoTour.completed) {
      return;
    }
    if (window.closeTopmostModal) window.closeTopmostModal();
  }
});

document.addEventListener("DOMContentLoaded", async () => {
  bindNavigationTabs();
  bindConstructionAnimationControls();
  await loadCachedCounselorProfile();
  syncCounselorProfileSummary();
  bindFilterAndSlideControls();
  bindImageStudioModal();
  bindEnhancedWorkbenchAndAdminFeatures();
  await loadBadgesCatalog();
  await executeStreamingWorkflow("First Aid");
});

async function loadCachedCounselorProfile() {
  let prof = null;
  try {
    const raw = window.localStorage.getItem(COUNSELOR_STORAGE_KEY);
    if (raw) {
      prof = JSON.parse(raw);
    }
  } catch (_e) {
    // ignore storage read error
  }
  try {
    const serverProf = await fetch("/api/counselor-profile").then((r) => r.json());
    const unwrapped = serverProf?.profile || serverProf;
    if (unwrapped && (serverProf.cached_locally || unwrapped.counselor_name || unwrapped.troop_affiliation)) {
      prof = { ...(prof || {}), ...unwrapped };
    }
  } catch (_e) {
    // ignore offline
  }
  if (!prof) return;
  let fixedTypo = false;
  ["counselor_name", "troop_affiliation", "location_or_zip"].forEach((k) => {
    if (typeof prof[k] === "string" && /Middelton/i.test(prof[k])) {
      prof[k] = prof[k].replace(/Middelton/gi, "Middleton");
      fixedTypo = true;
    }
  });
  state.counselorProfile = prof;
  if (fixedTypo) {
    try {
      window.localStorage.setItem(COUNSELOR_STORAGE_KEY, JSON.stringify(prof));
    } catch (_e) {}
  }
  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el && typeof val === "string") el.value = val.replace(/Middelton/gi, "Middleton");
  };
  setVal("input-counselor-name", prof.counselor_name || "Scoutmaster Bob");
  setVal("input-troop-name", prof.troop_affiliation || "Troop 123, My Council");
  setVal("input-troop", prof.troop_affiliation || "Troop 123, My Council");
  setVal("input-counselor-location", prof.location_or_zip || "");
  setVal("input-counselor-email", prof.email_address || "counselor@troop123.org");
  setVal("input-counselor-phone", prof.phone_number || "(000) 555-1234");
  if (prof.custom_troop_logo_path) {
    state.customLogoPath = prof.custom_troop_logo_path;
    const fname = String(prof.custom_troop_logo_path).split("/").pop() || "Custom Logo";
    syncTroopLogoUi(fname);
  } else {
    syncTroopLogoUi("");
  }
  syncCounselorProfileSummary();
}

function syncTroopLogoUi(filenameLabel = "") {
  const logoStatus = document.getElementById("troop-logo-status");
  const clearBtn = document.getElementById("btn-clear-troop-logo");
  const hasLogo = Boolean(state.customLogoPath || state.customLogoUrl || filenameLabel);
  if (clearBtn) {
    clearBtn.classList.toggle("hidden", !hasLogo);
  }
  if (logoStatus) {
    if (hasLogo) {
      const label = filenameLabel || String(state.customLogoPath || "Custom Troop Logo").split("/").pop();
      logoStatus.style.display = "flex";
      logoStatus.textContent = `✓ Uploaded: ${label}`;
    } else {
      logoStatus.style.display = "none";
      logoStatus.textContent = "";
    }
  }
}

async function clearCustomTroopLogo(showNotification = true) {
  const logoInput = document.getElementById("input-troop-logo");
  if (logoInput) {
    logoInput.value = "";
  }
  state.customLogoPath = null;
  state.customLogoUrl = null;
  if (state.currentResult) {
    state.currentResult.custom_troop_logo_url = null;
    state.currentResult.custom_troop_logo_path = null;
  }
  syncTroopLogoUi("");
  await saveCachedCounselorProfile();
  if (state.currentResult) {
    renderActiveSlide(state.activeSlideIdx);
  }
  if (showNotification && typeof showToast === "function") {
    showToast("🗑️ Removed custom troop logo.");
  }
}

async function saveCachedCounselorProfile() {
  ["input-counselor-name", "input-troop-name", "input-troop", "input-counselor-location"].forEach((id) => {
    const el = document.getElementById(id);
    if (el && typeof el.value === "string" && /Middelton/i.test(el.value)) {
      el.value = el.value.replace(/Middelton/gi, "Middleton");
    }
  });
  syncCounselorProfileSummary();
  const payload = {
    counselor_name: (document.getElementById("input-counselor-name")?.value || "Scoutmaster Bob").replace(/Middelton/gi, "Middleton"),
    troop_affiliation: (document.getElementById("input-troop-name")?.value || "Troop 123, My Council").replace(/Middelton/gi, "Middleton"),
    location_or_zip: (document.getElementById("input-counselor-location")?.value || "").replace(/Middelton/gi, "Middleton"),
    email_address: document.getElementById("input-counselor-email")?.value || "",
    phone_number: document.getElementById("input-counselor-phone")?.value || "",
    custom_troop_logo_path: state.customLogoPath || null,
  };
  state.counselorProfile = payload;
  try {
    window.localStorage.setItem(COUNSELOR_STORAGE_KEY, JSON.stringify(payload));
  } catch (_e) {
    // ignore storage write error
  }
  try {
    await fetch("/api/counselor-profile", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
  } catch (_e) {
    // ignore network error
  }
}

async function resetCachedCounselorProfile() {
  try {
    window.localStorage.removeItem(COUNSELOR_STORAGE_KEY);
  } catch (_e) {
    // ignore
  }
  try {
    await fetch("/api/counselor-profile", { method: "DELETE" });
  } catch (_e) {
    // ignore
  }
  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = val;
  };
  setVal("input-counselor-name", "Scoutmaster Bob");
  setVal("input-troop-name", "Troop 123, My Council");
  setVal("input-counselor-location", "");
  setVal("input-counselor-email", "counselor@troop123.org");
  setVal("input-counselor-phone", "(000) 555-1234");
  state.customLogoPath = null;
  state.customLogoUrl = null;
  if (state.currentResult) {
    state.currentResult.custom_troop_logo_url = null;
    state.currentResult.custom_troop_logo_path = null;
  }
  const logoInput = document.getElementById("input-troop-logo");
  if (logoInput) logoInput.value = "";
  syncTroopLogoUi("");
  syncCounselorProfileSummary();
  if (state.currentResult) {
    renderActiveSlide(state.activeSlideIdx);
    renderStudioKitAndParentLetter(state.currentResult);
  }
}

function switchMainTab(targetPanelId) {
  const tabBtns = document.querySelectorAll(".m3-tab-btn[data-panel]");
  const panels = ["panel-storyboard", "panel-triage", "panel-workbook", "panel-studiokit", "panel-admin"];
  tabBtns.forEach((b) => {
    const isAct = b.getAttribute("data-panel") === targetPanelId;
    b.classList.toggle("active", isAct);
    b.setAttribute("aria-selected", isAct ? "true" : "false");
  });
  panels.forEach((pId) => {
    const el = document.getElementById(pId);
    if (el) {
      el.classList.toggle("hidden", pId !== targetPanelId);
    }
  });
  if (targetPanelId === "panel-admin") {
    loadAdminConsoleData();
  }
}

function bindNavigationTabs() {
  const tabBtns = document.querySelectorAll(".m3-tab-btn[data-panel]");
  tabBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      const target = btn.getAttribute("data-panel");
      if (target) switchMainTab(target);
    });
  });

  // Under-Stage 3-Tab Drawer (Teaching Notes | Customize Slide | Quick Edit)
  document.querySelectorAll("[data-understage-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const tabKey = btn.getAttribute("data-understage-tab") || "notes";
      state.activeUnderstageTab = tabKey;
      syncUnderstageDrawerVisibility(state.activeSlideIdx);
    });
  });
}

function bindFilterAndSlideControls() {
  const searchInput = document.getElementById("filter-search-input");
  const catSelect = document.getElementById("filter-category-select");
  const eagleSelect = document.getElementById("filter-eagle-select");

  if (searchInput) {
    searchInput._userHasInteracted = false;
    const markUserInteracted = () => {
      searchInput._userHasInteracted = true;
      searchInput.removeAttribute("readonly");
    };
    searchInput.addEventListener("keydown", markUserInteracted);
    searchInput.addEventListener("paste", markUserInteracted);
    searchInput.addEventListener("drop", markUserInteracted);
    searchInput.addEventListener("input", () => {
      const valTrim = (searchInput.value || "").trim();
      if (!searchInput._userHasInteracted && (valTrim === "Local" || valTrim === "admin-superuser")) {
        searchInput.value = "";
      }
      applyBadgeFilters(false);
    });
  }
  catSelect?.addEventListener("change", () => applyBadgeFilters(false));
  eagleSelect?.addEventListener("change", () => applyBadgeFilters(false));

  // Collapsible Left Setup Sidebar toggle (updates label between "Hide Setup" and "Show Setup")
  const sidebarToggleBtn = document.getElementById("btn-toggle-sidebar");
  const sidebarToggleLabel = document.getElementById("label-toggle-sidebar");
  const sidebarToggleIcon = document.getElementById("icon-toggle-sidebar");
  const workbenchGrid = document.getElementById("main-workbench-grid");
  const syncSidebarToggleUi = (isCollapsed) => {
    if (sidebarToggleLabel) {
      sidebarToggleLabel.textContent = isCollapsed ? "Show Setup" : "Hide Setup";
    }
    if (sidebarToggleIcon) {
      sidebarToggleIcon.textContent = isCollapsed ? "⇥" : "⇤";
    }
    if (sidebarToggleBtn) {
      sidebarToggleBtn.title = isCollapsed
        ? "Show Setup Sidebar"
        : "Hide Setup Sidebar to Maximize Slide Stage";
    }
  };
  sidebarToggleBtn?.addEventListener("click", () => {
    if (!workbenchGrid) return;
    const isCollapsed = workbenchGrid.classList.toggle("sidebar-collapsed");
    syncSidebarToggleUi(isCollapsed);
    requestAnimationFrame(() => fitActiveSlideToStage());
  });

  // Collapsible Storyboard Filmstrip Outline toggle
  const filmstripToggleBtn = document.getElementById("btn-toggle-filmstrip");
  const storyboardLayout = document.getElementById("panel-storyboard");
  filmstripToggleBtn?.addEventListener("click", () => {
    if (!storyboardLayout) return;
    const isCollapsed = storyboardLayout.classList.toggle("filmstrip-collapsed");
    filmstripToggleBtn.textContent = isCollapsed ? "▶ Outline" : "◀ Outline";
    requestAnimationFrame(() => fitActiveSlideToStage());
  });

  // Top-bar Counselor Profile Chip opens the sidebar Counselor Profile Accordion
  const topProfileChip = document.getElementById("top-counselor-profile-chip");
  const profileAccordion = document.getElementById("counselor-profile-accordion");
  const profileChevron = document.getElementById("profile-accordion-chevron");
  topProfileChip?.addEventListener("click", () => {
    workbenchGrid?.classList.remove("sidebar-collapsed");
    syncSidebarToggleUi(false);
    if (profileAccordion) {
      profileAccordion.open = true;
      profileAccordion.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  });
  profileAccordion?.addEventListener("toggle", () => {
    if (profileChevron) {
      profileChevron.textContent = profileAccordion.open ? "Close ▴" : "Edit ▾";
    }
  });

  // Collapsible Progress Trace Details toggle
  const traceHeaderToggle = document.getElementById("trace-card-header-toggle");
  const traceToggleBtn = document.getElementById("btn-toggle-trace-details");
  const traceListEl = document.getElementById("agent-trace-list");
  traceHeaderToggle?.addEventListener("click", () => {
    if (!traceListEl) return;
    const isHidden = traceListEl.classList.toggle("hidden");
    if (traceToggleBtn) {
      traceToggleBtn.textContent = isHidden ? "Details ▾" : "Hide ▴";
    }
  });

  // Filmstrip keyword search filter
  const filmstripSearchInput = document.getElementById("filmstrip-search-input");
  filmstripSearchInput?.addEventListener("input", () => {
    state.filmstripQuery = (filmstripSearchInput.value || "").trim().toLowerCase();
    const slides = state.currentResult?.storyboard?.slides || [];
    renderFilmstrip(slides);
  });

  // Live-update Active Slide, Parent Letter, Local Troop Grounding & Cache whenever counselor contact inputs change
  ["input-counselor-name", "input-troop-name", "input-counselor-location", "input-counselor-email", "input-counselor-phone"].forEach((id) => {
    document.getElementById(id)?.addEventListener("input", () => {
      saveCachedCounselorProfile();
      if (state.currentResult) {
        renderActiveSlide(state.activeSlideIdx);
        renderStudioKitAndParentLetter(state.currentResult);
      }
    });
  });

  document.getElementById("btn-reset-counselor-cache")?.addEventListener("click", async () => {
    await resetCachedCounselorProfile();
  });

  document.getElementById("input-counselor-location")?.addEventListener("change", async () => {
    await saveCachedCounselorProfile();
    markDeckConfigDirty();
  });

  // Upload Optional Troop Custom Logo and live-render on Slide 1
  const logoInput = document.getElementById("input-troop-logo");
  const clearLogoBtn = document.getElementById("btn-clear-troop-logo");
  clearLogoBtn?.addEventListener("click", async () => {
    await clearCustomTroopLogo(true);
  });
  logoInput?.addEventListener("change", (e) => {
    const file = e.target.files?.[0];
    if (!file) {
      clearCustomTroopLogo(false);
      return;
    }
    const reader = new FileReader();
    reader.onload = async () => {
      const dataUrl = String(reader.result || "");
      state.customLogoUrl = dataUrl;
      syncTroopLogoUi(file.name);
      if (state.activeSlideIdx === -1 && state.currentResult) {
        renderActiveSlide(-1);
      }
      try {
        const resp = await fetch("/api/upload-logo", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ filename: file.name, data_url: dataUrl }),
        }).then((r) => r.json());
        if (resp.status === "SUCCESS") {
          state.customLogoPath = resp.logo_path;
          state.customLogoUrl = resp.logo_url || dataUrl;
          await saveCachedCounselorProfile();
          syncTroopLogoUi(resp.filename || file.name);
          if (state.activeSlideIdx === -1 && state.currentResult) {
            renderActiveSlide(-1);
          }
        }
      } catch (_err) {
        // Keep dataUrl preview active even if offline
      }
    };
    reader.readAsDataURL(file);
  });

  document.getElementById("btn-generate-deck")?.addEventListener("click", async () => {
    const badge = document.getElementById("badge-select")?.value || state.currentBadge;
    if (badge) {
      clearDeckConfigDirty();
      await executeStreamingWorkflow(badge, { isExplicitBuild: true });
    }
  });

  // Prevent accidental full-deck regeneration on dropdown changes; mark dirty & update FinOps preview
  ["depth-select", "beautification-select", "audience-select", "deep-research-checkbox"].forEach((id) => {
    document.getElementById(id)?.addEventListener("change", () => {
      markDeckConfigDirty();
      if (id === "beautification-select" && state.currentResult) {
        const newTier = document.getElementById("beautification-select")?.value || "BEAUTIFIED";
        state.currentResult.beautification_tier = newTier;
        const slides = state.currentResult.storyboard?.slides || [];
        slides.forEach((s) => {
          s.beautification_tier = newTier;
        });
        const beauLabelMap = {
          STANDARD: "Crisp White",
          BEAUTIFIED: "Warm Cream",
          STUDIO: "Dark Slate",
        };
        const resBeauEl = document.getElementById("res-beautification");
        if (resBeauEl) resBeauEl.textContent = beauLabelMap[newTier] || newTier;
        renderFilmstrip(slides);
        if (state.activeSlideIdx >= 0) {
          renderActiveSlide(state.activeSlideIdx);
        }
        if (typeof applyDeckStyleToActiveDeck === "function") {
          applyDeckStyleToActiveDeck(false);
        }
      }
    });
  });

  // 20-State Slide Edit Undo/Redo Stack (Deliverable 6)
  state.slideUndoStack = state.slideUndoStack || [];
  state.slideRedoStack = state.slideRedoStack || [];

  const syncStageUndoRedoButtonsUi = () => {
    const undoBtn = document.getElementById("btn-stage-undo");
    const redoBtn = document.getElementById("btn-stage-redo");
    if (undoBtn) {
      undoBtn.disabled = !Array.isArray(state.slideUndoStack) || state.slideUndoStack.length === 0;
      undoBtn.title = `Undo last slide edit (${(state.slideUndoStack || []).length} step${(state.slideUndoStack || []).length === 1 ? "" : "s"} available • Ctrl+Z)`;
    }
    if (redoBtn) {
      redoBtn.disabled = !Array.isArray(state.slideRedoStack) || state.slideRedoStack.length === 0;
      redoBtn.title = `Redo slide edit (${(state.slideRedoStack || []).length} step${(state.slideRedoStack || []).length === 1 ? "" : "s"} available • Ctrl+Y)`;
    }
  };
  window.syncStageUndoRedoButtonsUi = syncStageUndoRedoButtonsUi;

  const cloneSlidesSnapshot = (slidesArr) => {
    try {
      if (typeof structuredClone === "function") {
        return structuredClone(slidesArr || []);
      }
    } catch (_e) {}
    return JSON.parse(JSON.stringify(slidesArr || []));
  };

  const pushSlideUndoState = (label = "Slide Edit") => {
    const slides = state.currentResult?.storyboard?.slides;
    if (!Array.isArray(slides)) return;
    state.slideUndoStack = state.slideUndoStack || [];
    state.slideRedoStack = [];
    state.slideUndoStack.push({
      label,
      activeSlideIdx: state.activeSlideIdx,
      slides: cloneSlidesSnapshot(slides),
    });
    if (state.slideUndoStack.length > 20) {
      state.slideUndoStack.shift();
    }
    syncStageUndoRedoButtonsUi();
  };
  window.pushSlideUndoState = pushSlideUndoState;

  const performSlideUndo = () => {
    const slides = state.currentResult?.storyboard?.slides;
    if (!Array.isArray(slides) || !Array.isArray(state.slideUndoStack) || state.slideUndoStack.length === 0) {
      return;
    }
    const prevEntry = state.slideUndoStack.pop();
    state.slideRedoStack = state.slideRedoStack || [];
    state.slideRedoStack.push({
      label: prevEntry.label || "Slide Edit",
      activeSlideIdx: state.activeSlideIdx,
      slides: cloneSlidesSnapshot(slides),
    });
    if (state.slideRedoStack.length > 20) {
      state.slideRedoStack.shift();
    }
    state.currentResult.storyboard.slides = cloneSlidesSnapshot(prevEntry.slides);
    state.activeSlideIdx = Math.min(
      Math.max(-1, prevEntry.activeSlideIdx ?? state.activeSlideIdx),
      state.currentResult.storyboard.slides.length - 1
    );
    syncStageUndoRedoButtonsUi();
    renderFilmstrip(state.currentResult.storyboard.slides);
    renderActiveSlide(state.activeSlideIdx);
    if (typeof scheduleDebouncedDeckPptxSync === "function") {
      scheduleDebouncedDeckPptxSync(800);
    }
    showToast(`↩️ Undid: ${prevEntry.label || "Slide Edit"}`, "info");
  };
  window.performSlideUndo = performSlideUndo;

  const performSlideRedo = () => {
    const slides = state.currentResult?.storyboard?.slides;
    if (!Array.isArray(slides) || !Array.isArray(state.slideRedoStack) || state.slideRedoStack.length === 0) {
      return;
    }
    const nextEntry = state.slideRedoStack.pop();
    state.slideUndoStack = state.slideUndoStack || [];
    state.slideUndoStack.push({
      label: nextEntry.label || "Slide Edit",
      activeSlideIdx: state.activeSlideIdx,
      slides: cloneSlidesSnapshot(slides),
    });
    if (state.slideUndoStack.length > 20) {
      state.slideUndoStack.shift();
    }
    state.currentResult.storyboard.slides = cloneSlidesSnapshot(nextEntry.slides);
    state.activeSlideIdx = Math.min(
      Math.max(-1, nextEntry.activeSlideIdx ?? state.activeSlideIdx),
      state.currentResult.storyboard.slides.length - 1
    );
    syncStageUndoRedoButtonsUi();
    renderFilmstrip(state.currentResult.storyboard.slides);
    renderActiveSlide(state.activeSlideIdx);
    if (typeof scheduleDebouncedDeckPptxSync === "function") {
      scheduleDebouncedDeckPptxSync(800);
    }
    showToast(`↪️ Redid: ${nextEntry.label || "Slide Edit"}`, "info");
  };
  window.performSlideRedo = performSlideRedo;

  document.getElementById("btn-stage-undo")?.addEventListener("click", () => performSlideUndo());
  document.getElementById("btn-stage-redo")?.addEventListener("click", () => performSlideRedo());

  // Direct On-Stage Inline contenteditable Click-to-Edit (Deliverable 5 / Fix 1)
  state.stageInlineEditActive = false;
  const getStageInlineEditableNodes = () => {
    const titleEl = document.getElementById("stage-slide-title");
    const capEl = document.getElementById("stage-diagram-caption");
    const reqVerbEl = document.getElementById("stage-req-verbatim");
    const reqStripBox = document.getElementById("stage-req-strip-box");
    const miscEl = document.getElementById("stage-misconception-text");
    const miscBar = document.getElementById("stage-misconception-bar");
    const safetyEl = document.getElementById("stage-safety-text");
    const safetyBar = document.getElementById("stage-safety-bar");
    const leftZone =
      document.getElementById("stage-left-cards") || document.getElementById("stage-left-zone");
    const cardEls = leftZone
      ? Array.from(
          leftZone.querySelectorAll(
            ".stage-content-card, .m3-slide-card-item:not(.m3-quiz-reveal-card)"
          )
        )
      : [];
    const subCardEls = leftZone
      ? Array.from(
          leftZone.querySelectorAll(
            ".stage-card-heading, .stage-card-body, .m3-slide-card-anchor:not(.m3-quiz-reveal-card *), .m3-slide-card-text:not(.m3-quiz-reveal-card *), .m3-clean-point-lead, .m3-clean-point-body"
          )
        )
      : [];
    const coverEls = leftZone
      ? Array.from(
          leftZone.querySelectorAll(
            "#stage-cover-title, #cover-single-option-subhead, #stage-cover-subtitle, #stage-cover-counselor-name, #stage-cover-troop-name, #stage-cover-location, #stage-cover-email, #stage-cover-phone"
          )
        )
      : [];
    const reqVisible =
      reqVerbEl && reqStripBox && !reqStripBox.classList.contains("hidden") && reqStripBox.style.display !== "none";
    const miscVisible =
      miscEl && miscBar && !miscBar.classList.contains("hidden") && miscBar.style.display !== "none";
    const safetyVisible =
      safetyEl && safetyBar && !safetyBar.classList.contains("hidden") && safetyBar.style.display !== "none";
    const capVisible = capEl && capEl.offsetParent !== null;
    const isCoverSlide = state.activeSlideIdx === -1;
    const allEditable = [
      !isCoverSlide ? titleEl : null,
      reqVisible ? reqVerbEl : null,
      ...coverEls,
      ...cardEls,
      ...subCardEls,
      capVisible ? capEl : null,
      miscVisible ? miscEl : null,
      safetyVisible ? safetyEl : null,
    ].filter(Boolean);
    return {
      titleEl,
      capEl,
      reqVerbEl,
      reqVisible,
      miscEl,
      miscVisible,
      safetyEl,
      safetyVisible,
      leftZone,
      coverEls,
      cardEls,
      subCardEls,
      allEditable,
    };
  };

  const setStageInlineEditMode = (enable, focusTarget = null) => {
    if (!state.currentResult) {
      enable = false;
    }
    state.stageInlineEditActive = Boolean(enable);
    const barEl = document.getElementById("stage-inline-edit-bar");
    const toggleBtn = document.getElementById("btn-stage-inline-edit");
    const hintEl = document.getElementById("stage-inline-edit-hint");
    barEl?.classList.toggle("hidden", !state.stageInlineEditActive);
    toggleBtn?.classList.toggle("active", state.stageInlineEditActive);
    if (toggleBtn) {
      toggleBtn.textContent = state.stageInlineEditActive ? "✓ Done Editing" : "✏️ Edit Text";
      toggleBtn.title =
        "Edit Title, Body Cards, Requirement Text & Caption directly on the slide (Press Esc or click Done Editing to finish)";
    }
    if (hintEl) {
      hintEl.textContent =
        state.activeSlideIdx === -1
          ? "✏️ Edit Cover Title, Subtitle & Counselor Info directly on Slide 1 (Press Esc or Done Editing to finish)"
          : "✏️ Edit Title, Body Cards, Requirement Text, Safety & Caption on the slide (Press Esc or Done Editing to finish)";
    }

    const { titleEl, coverEls, cardEls, allEditable } = getStageInlineEditableNodes();
    const cleanupNodes = [
      document.getElementById("stage-slide-title"),
      document.getElementById("stage-diagram-caption"),
      document.getElementById("stage-req-verbatim"),
      document.getElementById("stage-misconception-text"),
      document.getElementById("stage-safety-text"),
      ...(coverEls || []),
      ...allEditable,
    ].filter(Boolean);

    cleanupNodes.forEach((el) => {
      if (state.stageInlineEditActive && allEditable.includes(el)) {
        el.setAttribute("contenteditable", "true");
        el.setAttribute("spellcheck", "true");
        el.classList.add("m3-stage-inline-editable");
        el.style.outline = "1.5px dashed rgba(37, 99, 235, 0.65)";
        el.style.cursor = "text";
      } else {
        el.removeAttribute("contenteditable");
        el.classList.remove("m3-stage-inline-editable");
        el.style.outline = "";
        el.style.cursor = "";
      }
    });

    if (state.stageInlineEditActive) {
      const target = focusTarget || (state.activeSlideIdx === -1 ? coverEls[0] : titleEl) || cardEls[0];
      if (target && typeof target.focus === "function") {
        target.focus();
      }
    }
  };
  window.setStageInlineEditMode = setStageInlineEditMode;

  const commitStageInlineEdits = () => {
    if (!state.currentResult) {
      setStageInlineEditMode(false);
      return;
    }
    if (state.activeSlideIdx === -1) {
      const res = state.currentResult;
      res.counselor_info = res.counselor_info || {};
      const covTitleEl = document.getElementById("stage-cover-title");
      const covOptEl = document.getElementById("cover-single-option-subhead");
      const covSubEl = document.getElementById("stage-cover-subtitle");
      const covCounselorEl = document.getElementById("stage-cover-counselor-name");
      const covTroopEl = document.getElementById("stage-cover-troop-name");
      const covLocEl = document.getElementById("stage-cover-location");
      const covEmailEl = document.getElementById("stage-cover-email");
      const covPhoneEl = document.getElementById("stage-cover-phone");

      if (covTitleEl) {
        const v = (covTitleEl.innerText || covTitleEl.textContent || "").trim();
        if (v) res._customCoverTitle = v;
      }
      if (covOptEl) {
        const v = (covOptEl.innerText || covOptEl.textContent || "").trim();
        if (v) res._customCoverOptionSubhead = v;
      }
      if (covSubEl) {
        const v = (covSubEl.innerText || covSubEl.textContent || "").trim();
        if (v) res._customCoverSubtitle = v;
      }
      if (covCounselorEl) {
        const v = (covCounselorEl.innerText || covCounselorEl.textContent || "")
          .replace(/^Counselor\s*:\s*/i, "")
          .trim();
        if (v) {
          res.counselor_info.counselor_name = v;
          const inEl = document.getElementById("input-counselor-name");
          if (inEl) inEl.value = v;
        }
      }
      if (covTroopEl) {
        const v = (covTroopEl.innerText || covTroopEl.textContent || "")
          .replace(/^Unit\s*\/\s*Council\s*:\s*/i, "")
          .trim();
        if (v) {
          res.counselor_info.troop_affiliation = v;
          const inEl = document.getElementById("input-troop-name");
          if (inEl) inEl.value = v;
        }
      }
      if (covLocEl) {
        const v = (covLocEl.innerText || covLocEl.textContent || "")
          .replace(/^Location\s*:\s*/i, "")
          .trim();
        if (v) {
          res.counselor_info.location_or_zip = v;
          const inEl = document.getElementById("input-counselor-location");
          if (inEl) inEl.value = v;
        }
      }
      if (covEmailEl) {
        const v = (covEmailEl.innerText || covEmailEl.textContent || "")
          .replace(/^Email\s*:\s*/i, "")
          .trim();
        if (v) {
          res.counselor_info.email_address = v;
          const inEl = document.getElementById("input-counselor-email");
          if (inEl) inEl.value = v;
        }
      }
      if (covPhoneEl) {
        const v = (covPhoneEl.innerText || covPhoneEl.textContent || "")
          .replace(/^Phone\s*:\s*/i, "")
          .trim();
        if (v) {
          res.counselor_info.phone_number = v;
          const inEl = document.getElementById("input-counselor-phone");
          if (inEl) inEl.value = v;
        }
      }
      setStageInlineEditMode(false);
      renderActiveSlide(-1);
      return;
    }
    const slides = state.currentResult.storyboard?.slides || [];
    const slide = slides[state.activeSlideIdx];
    const {
      titleEl,
      capEl,
      reqVerbEl,
      reqVisible,
      miscEl,
      miscVisible,
      safetyEl,
      safetyVisible,
      cardEls,
    } = getStageInlineEditableNodes();

    const qeTitle = document.getElementById("quickedit-slide-title");
    const qeCaption = document.getElementById("quickedit-slide-caption");
    const qeBullets = document.getElementById("quickedit-slide-bullets");

    if (titleEl) {
      const cleanTitle = (titleEl.innerText || titleEl.textContent || "").trim();
      if (cleanTitle) {
        if (qeTitle) qeTitle.value = cleanTitle;
        if (slide) slide.title = cleanTitle;
      }
    }
    if (capEl && capEl.offsetParent !== null) {
      const cleanCap = (capEl.innerText || capEl.textContent || "").trim();
      if (qeCaption) qeCaption.value = cleanCap;
      if (slide) {
        slide.visual_caption = cleanCap;
        slide.image_caption = cleanCap;
        if (slide.visual && typeof slide.visual === "object") {
          slide.visual.caption = cleanCap;
        }
      }
    }
    if (reqVisible && reqVerbEl && slide) {
      const rawVerb = (reqVerbEl.innerText || reqVerbEl.textContent || "")
        .replace(/^(?:Official\s+Req(?:uirement)?\s+[^:]+|Curriculum\s*&\s*Local\s+Context)\s*:\s*/i, "")
        .trim();
      if (rawVerb) {
        slide.verbatim_text = rawVerb;
        slide.verbatim_requirement_text = rawVerb;
        if ("requirement_verbatim" in slide) {
          slide.requirement_verbatim = rawVerb;
        }
      }
    }
    if (miscVisible && miscEl && slide) {
      const rawMisc = (miscEl.innerText || miscEl.textContent || "").trim();
      if (rawMisc) {
        if (slide.misconception_callout && typeof slide.misconception_callout === "object") {
          slide.misconception_callout.text = rawMisc;
        } else {
          slide.misconception_callout = rawMisc;
        }
        const arrowParts = rawMisc.split(/\s*(?:→|->)\s*/);
        if (arrowParts.length >= 2) {
          const mTxt = arrowParts[0].replace(/^Myth\s*:\s*/i, "").trim();
          const fTxt = arrowParts.slice(1).join(" → ").replace(/^(?:Pamphlet\s+)?Fact\s*:\s*/i, "").trim();
          slide.misconception_pair = {
            ...(slide.misconception_pair || {}),
            misconception: mTxt,
            myth: mTxt,
            fact: fTxt,
            fact_correction: fTxt,
          };
        }
      }
    }
    if (safetyVisible && safetyEl && slide) {
      const rawSafety = (safetyEl.innerText || safetyEl.textContent || "")
        .replace(/^Guide\s+to\s+Safe\s+Scouting\s*:\s*/i, "")
        .trim();
      if (rawSafety) {
        slide.safety_warning = rawSafety;
        if (slide.safety_callout && typeof slide.safety_callout === "object") {
          slide.safety_callout.text = rawSafety;
        } else {
          slide.safety_callout = rawSafety;
        }
      }
    }
    if (cardEls.length > 0) {
      const extractedBullets = cardEls
        .map((cEl) => {
          const anchorNode = cEl.querySelector(
            ".stage-card-heading, .m3-slide-card-anchor, .m3-clean-point-lead"
          );
          const bodyNode = cEl.querySelector(
            ".stage-card-body, .m3-slide-card-text, .m3-clean-point-body"
          );
          if (anchorNode && bodyNode) {
            const aTxt = (anchorNode.innerText || anchorNode.textContent || "")
              .replace(/^(?:⚠️\s*SAFETY|STEP\s*\d+(?:\s*➔)?|0\d+|\[\✓\]|[▸★◆❝])\s*/i, "")
              .replace(/:$/, "")
              .trim();
            const bTxt = (bodyNode.innerText || bodyNode.textContent || "").trim();
            return aTxt && bTxt ? `${aTxt}: ${bTxt}` : aTxt || bTxt;
          }
          return (cEl.innerText || cEl.textContent || "")
            .replace(/^(?:⚠️\s*SAFETY|STEP\s*\d+(?:\s*➔)?|0\d+|\[\✓\]|[▸★◆❝])\s*/i, "")
            .replace(/\s+/g, " ")
            .trim();
        })
        .filter(Boolean);
      if (extractedBullets.length > 0) {
        if (qeBullets) qeBullets.value = extractedBullets.join("\n");
        if (slide) {
          slide.bullet_points = extractedBullets;
          slide.full_bullet_points = extractedBullets.slice();
        }
      }
    }
    setStageInlineEditMode(false);
    document.getElementById("btn-save-quickedit")?.click();
  };
  window.commitStageInlineEdits = commitStageInlineEdits;

  document.getElementById("btn-stage-inline-edit")?.addEventListener("click", () => {
    if (state.stageInlineEditActive) {
      if (document.activeElement && typeof document.activeElement.blur === "function") {
        document.activeElement.blur();
      }
      commitStageInlineEdits();
      showToast("✓ Stage text edits saved", "info");
    } else {
      setStageInlineEditMode(true);
    }
  });
  document.getElementById("btn-stage-inline-save")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (document.activeElement && typeof document.activeElement.blur === "function") {
      document.activeElement.blur();
    }
    commitStageInlineEdits();
    showToast("✓ Stage text edits saved", "info");
  });
  document.getElementById("btn-stage-inline-cancel")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    setStageInlineEditMode(false);
    if (state.currentResult && state.activeSlideIdx >= -1) {
      renderActiveSlide(state.activeSlideIdx);
    }
  });
  document.getElementById("stage-diagram-caption")?.addEventListener("click", (ev) => {
    if (state.stageInlineEditActive) {
      ev.stopPropagation();
    }
  });
  document.getElementById("stage-diagram-caption")?.addEventListener("dblclick", (ev) => {
    ev.stopPropagation();
    if (state.activeSlideIdx >= 0 && !state.stageInlineEditActive) {
      setStageInlineEditMode(true, ev.currentTarget);
    }
  });
  document.getElementById("widescreen-slide-stage")?.addEventListener("dblclick", (ev) => {
    const hitTarget = ev.target?.closest(
      "#stage-cover-title, #cover-single-option-subhead, #stage-cover-subtitle, #stage-cover-counselor-name, #stage-cover-troop-name, #stage-cover-location, #stage-cover-email, #stage-cover-phone, #stage-slide-title, #stage-left-cards, .stage-content-card, .m3-slide-card-item:not(.m3-quiz-reveal-card), #stage-req-verbatim, #stage-diagram-caption, #stage-misconception-text, #stage-safety-text"
    );
    if (hitTarget && !state.stageInlineEditActive) {
      ev.stopPropagation();
      const focusNode =
        ev.target?.closest(
          ".stage-card-heading, .stage-card-body, .m3-slide-card-anchor, .m3-slide-card-text, .m3-clean-point-lead, .m3-clean-point-body"
        ) ||
        (hitTarget.id === "stage-left-cards"
          ? hitTarget.querySelector(".stage-content-card, .m3-slide-card-item")
          : hitTarget);
      setStageInlineEditMode(true, focusNode || hitTarget);
    }
  });

  // Fix 7: Progress Indicator Modal with Fast Badge-Building Animation & Moving Timer Bar for Long Downloads
  const DOWNLOAD_BADGE_CYCLE_SLUGS = [
    "first_aid",
    "camping",
    "environmental_science",
    "citizenship_in_the_nation",
    "emergency_preparedness",
    "space_exploration",
    "kayaking",
    "archery",
  ];
  const DOWNLOAD_BADGE_FALLBACK_ICONS = ["⚜️", "🏕️", "🧭", "⛑️", "🦅", "🚀", "🛶", "🏹"];
  let _downloadProgressTimerId = null;
  let _downloadProgressPhaseTimerId = null;
  let _downloadProgressOpenedAt = 0;

  const showDownloadProgressModal = ({
    title = "Building Printable Scouting Packet...",
    subtitle = "Assembling official BSA requirements, vector tables & print-ready pages",
    steps = [
      "1/4 Hydrating official BSA requirements & diagrams...",
      "2/4 Laying out fillable tables & checklists...",
      "3/4 Rendering print-ready vector PDF pages...",
      "4/4 Finalizing download stream...",
    ],
  } = {}) => {
    const modal = document.getElementById("download-progress-modal");
    if (!modal) return;
    if (_downloadProgressTimerId) clearInterval(_downloadProgressTimerId);
    if (_downloadProgressPhaseTimerId) clearInterval(_downloadProgressPhaseTimerId);

    const titleEl = document.getElementById("download-progress-modal-title");
    const subEl = document.getElementById("download-progress-modal-subtitle");
    const stepEl = document.getElementById("download-progress-step-label");
    const timerEl = document.getElementById("download-progress-timer-pill");
    const fillEl = document.getElementById("download-progress-bar-fill");
    const trackEl = document.getElementById("download-progress-bar-track");
    const emblemImg = document.getElementById("download-progress-emblem-img");
    const emblemIcon = document.getElementById("download-progress-emblem-icon");
    const dotsWrap = document.getElementById("download-progress-phase-dots");

    if (titleEl) titleEl.textContent = title;
    if (subEl) subEl.textContent = subtitle;
    const validSteps =
      Array.isArray(steps) && steps.length > 0
        ? steps
        : [
            "1/4 Hydrating official BSA requirements & diagrams...",
            "2/4 Laying out fillable tables & checklists...",
            "3/4 Rendering print-ready vector PDF pages...",
            "4/4 Finalizing download stream...",
          ];
    if (stepEl) stepEl.textContent = validSteps[0];
    if (timerEl) timerEl.textContent = "Elapsed: 0.0s";
    if (fillEl) fillEl.style.width = "10%";
    if (trackEl) trackEl.setAttribute("aria-valuenow", "10");

    const activeBadgeName =
      state.currentResult?.badge_name || document.getElementById("badge-select")?.value || "First Aid";
    const primarySlug =
      typeof badgeNameToEmblemSlug === "function" ? badgeNameToEmblemSlug(activeBadgeName) : "first_aid";
    const cycleSlugs = [
      primarySlug,
      ...DOWNLOAD_BADGE_CYCLE_SLUGS.filter((s) => s !== primarySlug),
    ];

    let phaseIdx = 0;
    const updatePhaseVisuals = (idx) => {
      const slug = cycleSlugs[idx % cycleSlugs.length] || "first_aid";
      if (emblemImg) {
        emblemImg.style.display = "block";
        emblemImg.src = `/assets/badge_emblems/${slug}.png`;
      }
      if (emblemIcon) {
        emblemIcon.textContent = DOWNLOAD_BADGE_FALLBACK_ICONS[idx % DOWNLOAD_BADGE_FALLBACK_ICONS.length];
      }
      const stepIdx = Math.min(validSteps.length - 1, idx % validSteps.length);
      if (stepEl) stepEl.textContent = validSteps[stepIdx];
      if (dotsWrap) {
        const dots = dotsWrap.querySelectorAll(".m3-download-phase-dot");
        dots.forEach((d, dIdx) => d.classList.toggle("is-active", dIdx === idx % dots.length));
      }
    };
    updatePhaseVisuals(0);

    _downloadProgressOpenedAt = performance.now();
    modal.classList.remove("hidden");
    modal.classList.add("open");

    // Live 0.1s elapsed timer & smooth asymptotic 0% -> 92% progress bar
    _downloadProgressTimerId = setInterval(() => {
      const elapsedSec = Math.max(0, (performance.now() - _downloadProgressOpenedAt) / 1000);
      if (timerEl) {
        timerEl.textContent = `Elapsed: ${elapsedSec.toFixed(1)}s`;
      }
      const pct = Math.min(92, Math.round(12 + 80 * (1 - Math.exp(-elapsedSec / 2.2))));
      if (fillEl) fillEl.style.width = `${pct}%`;
      if (trackEl) trackEl.setAttribute("aria-valuenow", String(pct));
    }, 100);

    // Fast 750ms badge-building phase cycler
    _downloadProgressPhaseTimerId = setInterval(() => {
      phaseIdx += 1;
      updatePhaseVisuals(phaseIdx);
    }, 750);
  };
  window.showDownloadProgressModal = showDownloadProgressModal;

  const hideDownloadProgressModal = async () => {
    const modal = document.getElementById("download-progress-modal");
    if (_downloadProgressTimerId) {
      clearInterval(_downloadProgressTimerId);
      _downloadProgressTimerId = null;
    }
    if (_downloadProgressPhaseTimerId) {
      clearInterval(_downloadProgressPhaseTimerId);
      _downloadProgressPhaseTimerId = null;
    }
    if (!modal || modal.classList.contains("hidden")) return;

    const fillEl = document.getElementById("download-progress-bar-fill");
    const trackEl = document.getElementById("download-progress-bar-track");
    const stepEl = document.getElementById("download-progress-step-label");
    if (fillEl) fillEl.style.width = "100%";
    if (trackEl) trackEl.setAttribute("aria-valuenow", "100");
    if (stepEl) stepEl.textContent = "✓ Complete — Starting browser download...";

    const elapsedMs = performance.now() - (_downloadProgressOpenedAt || 0);
    const minDisplayMs = 420;
    const waitMs = elapsedMs < minDisplayMs ? minDisplayMs - elapsedMs : 160;
    await new Promise((r) => setTimeout(r, waitMs));
    modal.classList.remove("open");
    modal.classList.add("hidden");
  };
  window.hideDownloadProgressModal = hideDownloadProgressModal;

  const downloadUrlWithProgressModal = async (urlPath, options = {}) => {
    if (!urlPath || urlPath === "#") return;
    const lowerUrl = String(urlPath).toLowerCase();
    const isPptx = lowerUrl.includes(".pptx") || options.kind === "pptx";
    const isWorkbook = lowerUrl.includes("fillable-workbook") || options.kind === "workbook";
    const isBlueCard = lowerUrl.includes("bluecard") || options.kind === "bluecards";
    const badgeName =
      state.currentResult?.badge_name || document.getElementById("badge-select")?.value || "First Aid";

    const modalConfig = isPptx
      ? {
          title: `Exporting ${badgeName} PowerPoint (.PPTX)...`,
          subtitle: "Packaging 16:9 widescreen slides, speaker notes & embedded figures",
          steps: [
            "1/4 Verifying 16:9 slide layouts & theme tokens...",
            "2/4 Embedding official pamphlet figures & captions...",
            "3/4 Formatting 5-part counselor speaker notes...",
            "4/4 Finalizing .PPTX download stream...",
          ],
        }
      : isWorkbook
      ? {
          title: `Building ${badgeName} Fillable Scout Workbook (.PDF)...`,
          subtitle: "Generating interactive AcroForm fields, tables & requirement checklists",
          steps: [
            "1/4 Hydrating official BSA requirements & diagrams...",
            "2/4 Laying out fillable tables & checklists...",
            "3/4 Rendering print-ready vector PDF pages...",
            "4/4 Finalizing download stream...",
          ],
        }
      : isBlueCard
      ? {
          title: `Generating ${badgeName} 3-Panel Blue Cards (.PDF)...`,
          subtitle: "Formatting official #34124 advancement records & scout sign-off matrix",
          steps: [
            "1/4 Loading unit advancement roster & troop metadata...",
            "2/4 Mapping completed requirement initials...",
            "3/4 Rendering 3-panel perforated Blue Card layout...",
            "4/4 Finalizing download stream...",
          ],
        }
      : {
          title: options.title || `Building ${badgeName} Printable Handout (.PDF)...`,
          subtitle: options.subtitle || "Rendering print-ready vector PDF handout for your class",
          steps: options.steps || [
            "1/4 Hydrating official BSA requirements & diagrams...",
            "2/4 Formatting counselor & patrol layout tables...",
            "3/4 Rendering print-ready vector PDF pages...",
            "4/4 Finalizing download stream...",
          ],
        };

    showDownloadProgressModal(modalConfig);
    try {
      const resp = await fetch(urlPath);
      if (!resp.ok) {
        throw new Error(`HTTP ${resp.status}`);
      }
      const blob = await resp.blob();
      let filename = options.filename || "";
      const disp = resp.headers.get("Content-Disposition") || "";
      const fnMatch = disp.match(/filename\*?=(?:UTF-8'')?["']?([^"';\n]+)["']?/i);
      if (fnMatch && fnMatch[1]) {
        filename = decodeURIComponent(fnMatch[1].trim());
      }
      if (!filename) {
        const cleanPath = String(urlPath).split("?")[0];
        const base = cleanPath.split("/").pop() || "download";
        const safeBadge = String(badgeName)
          .trim()
          .replace(/[^A-Za-z0-9]+/g, "_");
        filename = base.includes(".") ? `${safeBadge}_${base}` : `${safeBadge}_${base}.pdf`;
      }
      const objUrl = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = objUrl;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(objUrl), 5000);
    } catch (_err) {
      const a = document.createElement("a");
      a.href = urlPath;
      a.setAttribute("download", options.filename || "");
      document.body.appendChild(a);
      a.click();
      a.remove();
    } finally {
      await hideDownloadProgressModal();
    }
  };
  window.downloadUrlWithProgressModal = downloadUrlWithProgressModal;

  // 1-Click Complete Class Packet (.ZIP) Download (Deliverable 4)
  const downloadCompleteClassPacketZip = async (triggerBtn = null) => {
    const res = state.currentResult || {};
    const badgeName = res.badge_name || document.getElementById("badge-select")?.value || "First Aid";
    const optTrack =
      res.option_track || document.getElementById("option-track-select")?.value || "ALL";
    const schedCfg =
      typeof window.getActiveScheduleConfig === "function" ? window.getActiveScheduleConfig() : {};
    const roster =
      typeof loadBadgeBlueCardRoster === "function" ? loadBadgeBlueCardRoster(badgeName) : { scouts: [] };

    const origText = triggerBtn ? triggerBtn.innerHTML : "";
    if (triggerBtn) {
      triggerBtn.disabled = true;
      triggerBtn.textContent = "⏳ Packaging 9-File Class Packet (.ZIP)...";
    }
    showToast(`📦 Packaging Complete ${badgeName} Class Packet (.ZIP)...`, "info");
    showDownloadProgressModal({
      title: `Packaging Complete ${badgeName} Class Packet (.ZIP)...`,
      subtitle: "Bundling .PPTX slide deck, Fillable Scout Workbook PDF, Blue Cards & Counselor StudioKit",
      steps: [
        "1/4 Hydrating official BSA requirements & 16:9 slide deck (.PPTX)...",
        "2/4 Laying out Fillable Scout Workbook & Counselor Guide PDFs...",
        "3/4 Rendering 3x5 Cue Cards, Field QR Checklist & Blue Cards...",
        "4/4 Compressing 9-file Complete Class Packet (.ZIP) stream...",
      ],
    });

    try {
      const resp = await fetch("/api/v1/export/class-packet.zip", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: badgeName,
          option_track: optTrack,
          template_id: state.activeTemplateId || res.template_id || "bsa_scouting_america",
          beautification_tier:
            res.beautification_tier || document.getElementById("beautification-select")?.value || "BEAUTIFIED",
          output_path: res.output_path || "",
          pptx_download_url: res.pptx_download_url || "",
          workbook_markdown: res.workbook_markdown || "",
          counselor_guide_markdown: res.counselor_guide_markdown || "",
          storyboard_slides: res.storyboard?.slides || [],
          requirements: res.research_artifact?.requirements || [],
          counselor_info: res.counselor_info || {
            counselor_name: document.getElementById("input-counselor-name")?.value || "Merit Badge Counselor",
            troop_affiliation: document.getElementById("input-troop-name")?.value || "Scouts BSA Unit",
            email_address: document.getElementById("input-counselor-email")?.value || "",
            phone_number: document.getElementById("input-counselor-phone")?.value || "",
          },
          session_dates: schedCfg.sessionPillLabels || [],
          patrol_size: parseInt(document.getElementById("gear-patrol-size-select")?.value || "8", 10) || 8,
          station_minutes: parseInt(document.getElementById("rotator-minutes-select")?.value || "15", 10) || 15,
          scouts_roster: roster.scouts || [],
        }),
      });
      if (!resp.ok) {
        throw new Error(`HTTP ${resp.status}`);
      }
      const blob = await resp.blob();
      const safeSlug = String(badgeName)
        .trim()
        .replace(/[^A-Za-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
      const filename = `Scouts_BSA_${safeSlug}_Complete_Class_Packet.zip`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
      showToast(`✅ Downloaded ${filename} (9 files ready for class)!`, "info");
    } catch (err) {
      showToast(`⚠️ Could not build Class Packet .ZIP: ${err.message}`, "warning");
    } finally {
      await hideDownloadProgressModal();
      if (triggerBtn) {
        triggerBtn.disabled = false;
        triggerBtn.innerHTML = origText;
      }
    }
  };
  window.downloadCompleteClassPacketZip = downloadCompleteClassPacketZip;

  document.querySelectorAll('[data-action="download-class-packet-zip"]').forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      document.getElementById("deck-export-mode-menu")?.classList.add("hidden");
      document.getElementById("top-export-dropdown-menu")?.classList.add("hidden");
      downloadCompleteClassPacketZip(ev.currentTarget);
    });
  });

  // Quick-Edit Slide Text & Notes Save Handler (rebuilds .pptx on disk)
  document.getElementById("btn-save-quickedit")?.addEventListener("click", async () => {
    if (!state.currentResult || state.activeSlideIdx < 0) return;
    const slides = state.currentResult.storyboard?.slides || [];
    const slide = slides[state.activeSlideIdx];
    if (!slide) return;

    pushSlideUndoState(`Edit Slide ${state.activeSlideIdx + 2} Text`);

    const newTitle = (document.getElementById("quickedit-slide-title")?.value || "").trim();
    const newCaption = (document.getElementById("quickedit-slide-caption")?.value || "").trim();
    const rawBullets = (document.getElementById("quickedit-slide-bullets")?.value || "")
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean);
    const newNotes = (document.getElementById("quickedit-slide-notes")?.value || "").trim();

    if (newTitle) slide.title = newTitle;
    if (newCaption) slide.visual_caption = newCaption;
    if (rawBullets.length > 0) {
      slide.bullet_points = rawBullets;
      slide.full_bullet_points = rawBullets.slice();
    }
    slide.presenter_notes = newNotes;

    const saveBtn = document.getElementById("btn-save-quickedit");
    const statusEl = document.getElementById("quickedit-status-msg") || document.getElementById("quickedit-save-status");
    try {
      if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.textContent = "⏳ Saving & Rebuilding .pptx...";
      }
      const resp = await fetch("/api/slide/regenerate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: state.currentResult.badge_name,
          slide_index: state.activeSlideIdx,
          new_archetype: slide.archetype || "SPLIT_VISUAL_EXPLAINER",
          new_visual_theme: slide.visual_theme || "NUMBERED_STEP_CARDS",
          new_accent_palette: slide.accent_palette_key || "NAVY_GOLD",
          visual_source_mode: "keep_current",
          slide_data: slide,
          storyboard_slides: slides,
          counselor_info: state.currentResult.counselor_info || {},
          output_path: state.currentResult.output_path || "",
        }),
      }).then((r) => r.json());

      if (resp.pptx_download_url) {
        state.currentResult.pptx_download_url = resp.pptx_download_url;
        const pptxBtn = document.getElementById("btn-download-pptx");
        if (pptxBtn) pptxBtn.href = `${resp.pptx_download_url}?v=${Date.now()}`;
      }
      renderFilmstrip(slides);
      renderActiveSlide(state.activeSlideIdx);
      if (typeof window.autoSaveActiveWorkspaceDebounced === "function") {
        window.autoSaveActiveWorkspaceDebounced({ promoteIfUnsaved: true });
      }
      if (statusEl) {
        statusEl.textContent = "✅ Saved & Updated .pptx on Disk!";
        setTimeout(() => {
          statusEl.textContent = "";
        }, 3500);
      }
    } finally {
      if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.textContent = "💾 Save Slide Edits & Rebuild .PPTX";
      }
    }
  });

  const stageWrapper = document.getElementById("slide-stage-wrapper");
  const fsHud = document.getElementById("fullscreen-hud-bar");

  const setPresentationFullscreenMode = async (enable) => {
    if (!stageWrapper) return;
    hideConstructionAnimationStage();
    document.getElementById("widescreen-slide-stage")?.classList.remove("hidden");
    stageWrapper.classList.toggle("is-presenting-fullscreen", enable);
    fsHud?.classList.toggle("hidden", !enable);
    const fsBtn = document.getElementById("btn-present-fullscreen");
    if (fsBtn) {
      fsBtn.textContent = enable ? "✕ Exit Fullscreen" : "🖥️ Present";
    }
    // Use the deterministic full-viewport CSS theatre overlay (.is-presenting-fullscreen)
    // and exit native OS fullscreen if active so macOS Spaces never hijack Presenter View into a separate fullscreen space
    if (!enable) {
      try {
        if (document.fullscreenElement && document.exitFullscreen) {
          await document.exitFullscreen();
        }
      } catch (_e) {}
    }
    fitActiveSlideToStage();
    setTimeout(() => fitActiveSlideToStage(), 40);
  };

  document.getElementById("btn-present-fullscreen")?.addEventListener("click", async () => {
    const isNowActive = !stageWrapper?.classList.contains("is-presenting-fullscreen");
    await setPresentationFullscreenMode(isNowActive);
  });

  document.addEventListener("fullscreenchange", () => {
    if (!document.fullscreenElement && stageWrapper?.classList.contains("is-presenting-fullscreen")) {
      const openingPopupRecently =
        (presenterPopupWin && !presenterPopupWin.closed) ||
        Date.now() - (state._openingSecondMonitorPopupAt || 0) < 2500;
      if (openingPopupRecently) {
        // Keep CSS .is-presenting-fullscreen theatre mode active when 2nd Monitor popup opens
        return;
      }
      stageWrapper.classList.remove("is-presenting-fullscreen");
      fsHud?.classList.add("hidden");
      const fsBtn = document.getElementById("btn-present-fullscreen");
      if (fsBtn) fsBtn.textContent = "🖥️ Present";
    }
  });

  document.getElementById("btn-fs-prev")?.addEventListener("click", () => {
    document.getElementById("btn-prev-slide")?.click();
  });
  document.getElementById("btn-fs-next")?.addEventListener("click", () => {
    document.getElementById("btn-next-slide")?.click();
  });
  document.getElementById("btn-fs-exit")?.addEventListener("click", async () => {
    await setPresentationFullscreenMode(false);
  });

  // Keyboard Arrow Navigation (Left / Right / F for Fullscreen / Escape to exit)
  document.addEventListener("keydown", (ev) => {
    if (state.stageInlineEditActive) {
      if (ev.key === "Escape") {
        ev.preventDefault();
        ev.stopPropagation();
        if (document.activeElement && typeof document.activeElement.blur === "function") {
          document.activeElement.blur();
        }
        commitStageInlineEdits();
        showToast("✓ Stage text edits saved", "info");
        return;
      }
      if (ev.key === "Enter" && (ev.ctrlKey || ev.metaKey)) {
        ev.preventDefault();
        ev.stopPropagation();
        if (document.activeElement && typeof document.activeElement.blur === "function") {
          document.activeElement.blur();
        }
        commitStageInlineEdits();
        showToast("✓ Stage text edits saved", "info");
        return;
      }
    }
    if (window.isAnyModalOpen && window.isAnyModalOpen()) {
      if (ev.key === "Escape") {
        ev.preventDefault();
        if (window.closeTopmostModal) window.closeTopmostModal();
      }
      return;
    }
    if (ev.key === "Escape" && state.activeDemoTour && typeof stopInteractiveDemoTour === "function") {
      ev.preventDefault();
      stopInteractiveDemoTour();
      return;
    }
    const tag = (ev.target?.tagName || "").toUpperCase();
    if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || ev.target?.isContentEditable) {
      return;
    }
    const storyboardPanel = document.getElementById("panel-storyboard");
    if (storyboardPanel && storyboardPanel.classList.contains("hidden")) return;

    if (ev.key === "ArrowLeft") {
      ev.preventDefault();
      document.getElementById("btn-prev-slide")?.click();
    } else if (ev.key === "ArrowRight") {
      ev.preventDefault();
      document.getElementById("btn-next-slide")?.click();
    } else if (ev.key === "Escape" && stageWrapper?.classList.contains("is-presenting-fullscreen")) {
      ev.preventDefault();
      setPresentationFullscreenMode(false);
    } else if ((ev.key === "f" || ev.key === "F") && !ev.ctrlKey && !ev.metaKey && !ev.altKey) {
      ev.preventDefault();
      document.getElementById("btn-present-fullscreen")?.click();
    }
  });

  // F3, F4, F5, F6 Action Buttons (Copy, Email, Gmail, Print, Schedule Selector, Gear Multiplier, Blue Card)
  bindCounselorToolkitActions();

  const applyCoDesignSelection = async () => {
    if (!state.currentResult || state.activeSlideIdx < 0) return;
    const slides = state.currentResult.storyboard?.slides || [];
    const slide = slides[state.activeSlideIdx];
    if (!slide) return;

    if (slide.diagram_url && !slide.original_diagram_url) {
      slide.original_diagram_url = slide.diagram_url;
    }
    if (slide.diagram_path && !slide.original_diagram_path) {
      slide.original_diagram_path = slide.diagram_path;
    }
    if (slide.visual_caption && !slide.original_visual_caption) {
      slide.original_visual_caption = slide.visual_caption;
    }
    if (slide.visual_source_label && !slide.original_visual_source_label) {
      slide.original_visual_source_label = slide.visual_source_label;
    }

    const newArch = document.getElementById("codesign-archetype-select")?.value || slide.archetype || "SPLIT_VISUAL_EXPLAINER";
    const newTheme = document.getElementById("codesign-theme-select")?.value || slide.visual_theme || "NUMBERED_STEP_CARDS";
    const newPalette = document.getElementById("codesign-palette-select")?.value || slide.accent_palette_key || "NAVY_GOLD";
    const newContainerOverride = document.getElementById("codesign-container-style-select")?.value || slide.container_style_override || "AUTO_DECK";
    const rawSourceVal = document.getElementById("codesign-source-select")?.value || "keep_current";
    let visSourceMode = rawSourceVal;
    if (newArch === "CONCEPT_TEXT_SLIDE") {
      visSourceMode = "none";
    } else if (rawSourceVal === "none" && slide.archetype === "CONCEPT_TEXT_SLIDE") {
      // User switched from Full Text back to a visual layout (e.g., Split Visual or Big Visual): restore image automatically
      visSourceMode = "restore_original";
      const srcSelEl = document.getElementById("codesign-source-select");
      if (srcSelEl) srcSelEl.value = "keep_current";
    } else if (rawSourceVal !== "none" && !slide.diagram_url && (slide.original_diagram_url || slide.original_diagram_path)) {
      visSourceMode = "restore_original";
    }

    if (typeof window.pushSlideUndoState === "function") {
      window.pushSlideUndoState(`Co-Design Slide ${state.activeSlideIdx + 2}`);
    }

    // 1. Optimistic immediate (<5ms) update on the live stage so rapid clicks (Split Visual -> Full Text -> Split Visual -> Big Visual) never lag or block
    slide.archetype = visSourceMode === "none" ? "CONCEPT_TEXT_SLIDE" : newArch;
    const explicitThemeChange = Boolean(state._codesignThemeExplicitlyChanged);
    state._codesignThemeExplicitlyChanged = false;
    if (explicitThemeChange) {
      slide._customThemeOverride = true;
      slide.visual_theme = newTheme;
    } else if (slide._customThemeOverride) {
      slide.visual_theme = newTheme;
    }
    const effectiveThemeForRegen = slide._customThemeOverride
      ? slide.visual_theme || newTheme
      : slide._baseVisualTheme || slide.visual_theme || "NUMBERED_STEP_CARDS";
    slide.accent_palette_key = newPalette;
    slide._customPaletteOverride = Boolean(newPalette && newPalette !== "MATCH_TEMPLATE");
    slide.container_style_override = newContainerOverride;
    slide.beautification_tier =
      state.currentResult.beautification_tier ||
      document.getElementById("beautification-select")?.value ||
      "BEAUTIFIED";

    if (visSourceMode === "none") {
      slide.diagram_url = null;
      slide.diagram_path = null;
      slide.ai_hero_image_path = null;
      slide.visual_source_label = "None (Full-Width Text Layout)";
      slide.callout_badge_text = "";
      if (slide.full_bullet_points) {
        slide.bullet_points = slide.full_bullet_points.slice();
      }
    } else if (visSourceMode === "restore_original" || (!slide.diagram_url && visSourceMode !== "ai_hero")) {
      const fallbackChoice = (typeof getSlideSpecificImageChoices === "function" ? getSlideSpecificImageChoices(slide) : [])[0];
      slide.diagram_url = slide.original_diagram_url || fallbackChoice?.image_url || slide.diagram_url || null;
      slide.diagram_path = slide.original_diagram_path || fallbackChoice?.image_path || slide.diagram_path || null;
      slide.ai_hero_image_path = null;
      slide.visual_caption = slide.original_visual_caption || slide.visual_caption || slide.title;
      slide.visual_source_label = slide.original_visual_source_label || slide.visual_source_label || "Official BSA Pamphlet / Wikimedia Figure";
      slide.callout_badge_text = "";
    }

    renderFilmstrip(slides);
    renderActiveSlide(state.activeSlideIdx);

    if (state.activeDemoTour && !state.activeDemoTour.completed) {
      if (typeof syncActiveSlideToPresenterPopout === "function") {
        syncActiveSlideToPresenterPopout();
      }
      return;
    }

    state._codesignReqSeq = (state._codesignReqSeq || 0) + 1;
    const reqSeq = state._codesignReqSeq;
    const applyBtn = document.getElementById("btn-apply-codesign");

    try {
      if (applyBtn) {
        applyBtn.textContent = "⏳ Applying...";
      }
      const resp = await fetch("/api/slide/regenerate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: state.currentResult.badge_name,
          slide_index: state.activeSlideIdx,
          new_archetype: newArch,
          new_visual_theme: effectiveThemeForRegen,
          new_accent_palette: newPalette,
          container_style_override: newContainerOverride,
          visual_source_mode: visSourceMode,
          slide_data: slide,
          storyboard_slides: slides,
          counselor_info: state.currentResult.counselor_info || {},
          output_path: state.currentResult.output_path || "",
          template_id: state.activeTemplateId || "bsa_scouting_america",
          deck_style: typeof getCurrentDeckStyleConfig === "function" ? getCurrentDeckStyleConfig() : undefined,
        }),
      }).then((r) => r.json());

      // Ignore out-of-order responses if the user clicked another layout/style while this request was in flight
      if (reqSeq !== state._codesignReqSeq) return;

      slide.archetype = visSourceMode === "none" ? "CONCEPT_TEXT_SLIDE" : (newArch || resp.new_archetype || "SPLIT_VISUAL_EXPLAINER");
      if (slide._customThemeOverride) {
        slide.visual_theme = newTheme;
      }
      slide.accent_palette_key = newPalette;
      slide.container_style_override = newContainerOverride;
      slide.beautification_tier =
        state.currentResult.beautification_tier ||
        document.getElementById("beautification-select")?.value ||
        "BEAUTIFIED";

      if (visSourceMode === "none") {
        slide.diagram_url = null;
        slide.diagram_path = null;
        slide.ai_hero_image_path = null;
        slide.visual_source_label = "None (Full-Width Text Layout)";
        slide.callout_badge_text = "";
        if (slide.full_bullet_points) {
          slide.bullet_points = slide.full_bullet_points.slice();
        }
      } else if (visSourceMode === "restore_original") {
        const fallbackChoice = (typeof getSlideSpecificImageChoices === "function" ? getSlideSpecificImageChoices(slide) : [])[0];
        slide.diagram_url = resp.diagram_url || slide.original_diagram_url || fallbackChoice?.image_url || null;
        slide.diagram_path = resp.diagram_path || slide.original_diagram_path || fallbackChoice?.image_path || null;
        slide.ai_hero_image_path = null;
        slide.visual_caption = resp.visual_caption || slide.original_visual_caption || slide.title;
        slide.visual_source_label = resp.visual_source_label || slide.original_visual_source_label || "Official BSA Pamphlet / Wikimedia Figure";
        slide.callout_badge_text = "";
      } else {
        if (resp.diagram_url) {
          slide.diagram_url = `${resp.diagram_url}${resp.diagram_url.includes("?") ? "&" : "?"}t=${Date.now()}`;
        } else if (!slide.diagram_url && slide.original_diagram_url) {
          slide.diagram_url = slide.original_diagram_url;
        }
        if (resp.diagram_path) {
          slide.diagram_path = resp.diagram_path;
        } else if (!slide.diagram_path && slide.original_diagram_path) {
          slide.diagram_path = slide.original_diagram_path;
        }
        if (visSourceMode === "ai_hero") {
          slide.ai_hero_image_path = resp.diagram_path || resp.diagram_url || "ai_hero";
          slide.visual_source_label = "EDGE Skill Concept Map (SlideBeautifierAgent)";
          slide.callout_badge_text = "";
        } else {
          slide.ai_hero_image_path = null;
          slide.visual_source_label = resp.visual_source_label || slide.visual_source_label || "Official BSA Pamphlet / Wikimedia Figure";
          slide.callout_badge_text = "";
        }
      }

      if (resp.updated_presenter_notes) {
        slide.presenter_notes = resp.updated_presenter_notes;
      }

      if (resp.pptx_download_url) {
        state.currentResult.pptx_download_url = resp.pptx_download_url;
        const pptxBtn = document.getElementById("btn-download-pptx");
        if (pptxBtn) pptxBtn.href = `${resp.pptx_download_url}?v=${Date.now()}`;
      }
      renderFilmstrip(slides);
      renderActiveSlide(state.activeSlideIdx);
      if (typeof window.autoSaveActiveWorkspaceDebounced === "function") {
        window.autoSaveActiveWorkspaceDebounced({ promoteIfUnsaved: true });
      }
    } finally {
      if (applyBtn && reqSeq === state._codesignReqSeq) {
        applyBtn.disabled = false;
        applyBtn.textContent = "✨ Apply to Slide";
      }
    }
  };
  document.getElementById("btn-apply-codesign")?.addEventListener("click", applyCoDesignSelection);

  // Plan 6 Option C Layer 2: 1-Click AI Polish Script & Copy Script buttons
  document.getElementById("btn-copy-slide-notes")?.addEventListener("click", (ev) => {
    const btn = ev.currentTarget;
    const slides = state.currentResult?.storyboard?.slides || [];
    const activeNotes =
      state.activeSlideIdx === -1
        ? document.getElementById("stage-presenter-notes")?.innerText || ""
        : slides[state.activeSlideIdx]?.presenter_notes || "";
    copyTextWithFeedback(btn, activeNotes, "✅ Script Copied!");
  });

  function syncNotesPolishProvenancePill({
    isPolished = false,
    polishSource = "",
    cacheHit = false,
    fallbackReason = "",
    batchSuffix = "",
  } = {}) {
    const statusPill = document.getElementById("notes-polish-status-pill");
    const restoreBtn = document.getElementById("btn-restore-default-notes");
    if (restoreBtn) {
      restoreBtn.classList.toggle("hidden", !isPolished);
    }
    if (!statusPill) return;
    statusPill.classList.remove("is-gemini-flash", "is-studio-narrative");
    if (!isPolished) {
      statusPill.textContent = "⚡ Procedural Script • Stage Cues";
      statusPill.title = "Default Layer 1 procedural first-person script with stage cues ($0.00)";
      return;
    }
    const isGemini =
      polishSource === "GEMINI_FLASH" ||
      polishSource === "GEMINI_2_5_FLASH" ||
      polishSource === "gemini-flash";
    if (isGemini) {
      statusPill.classList.add("is-gemini-flash");
      const cacheTag = cacheHit ? " (Cached)" : "";
      statusPill.textContent = `🤖 AI Polished • Gemini Flash${cacheTag}${batchSuffix}`;
      statusPill.title = "Polished by live Gemini Flash LLM and saved to SQLite cache";
    } else {
      statusPill.classList.add("is-studio-narrative");
      statusPill.textContent = `✨ Studio Narrative Polish • Offline Fallback${batchSuffix}`;
      statusPill.title = fallbackReason
        ? `Used Studio Narrative Fallback (${fallbackReason})`
        : "Polished with archetype-aware Studio Narrative Synthesizer (offline mode)";
    }
  }
  window.syncNotesPolishProvenancePill = syncNotesPolishProvenancePill;

  document.getElementById("btn-restore-default-notes")?.addEventListener("click", () => {
    if (!state.currentResult) return;
    const slides = state.currentResult.storyboard?.slides || [];
    const isCover = state.activeSlideIdx === -1;
    if (isCover) {
      delete state.currentResult._polishedCoverNotes;
      delete state.currentResult._coverPolishSource;
      delete state.currentResult._coverPolishFallbackReason;
    } else {
      const slide = slides[state.activeSlideIdx];
      if (!slide) return;
      if (slide._originalProceduralNotes) {
        slide.presenter_notes = slide._originalProceduralNotes;
      }
      slide._isPolishedNotes = false;
      delete slide._polishSource;
      delete slide._polishFallbackReason;
    }
    renderActiveSlide(state.activeSlideIdx);
  });

  const executePolishSingleSlide = async (forceRefreshOverride = null) => {
    const btn = document.getElementById("btn-ai-polish-notes");
    if (!btn || !state.currentResult) return;
    const slides = state.currentResult.storyboard?.slides || [];
    const isCover = state.activeSlideIdx === -1;
    if (!isCover && (state.activeSlideIdx < 0 || !slides[state.activeSlideIdx])) return;
    const slide = isCover
      ? {
          title: `${state.currentResult.badge_name || "First Aid"} Merit Badge - Cover Slide`,
          req_number: "Cover",
          archetype: "TITLE_COVER_HERO",
          presenter_notes: document.getElementById("stage-presenter-notes")?.innerText || "",
        }
      : slides[state.activeSlideIdx];
    const alreadyPolished = isCover
      ? Boolean(state.currentResult._polishedCoverNotes)
      : Boolean(slide._isPolishedNotes);
    const shouldForceRefresh =
      typeof forceRefreshOverride === "boolean" ? forceRefreshOverride : alreadyPolished;
    if (!isCover && !slide._originalProceduralNotes && slide.presenter_notes) {
      slide._originalProceduralNotes = slide.presenter_notes;
    }
    const nextSeed = shouldForceRefresh
      ? ((isCover ? state.currentResult._coverPolishSeed : slide._polishVariationSeed) || 0) + 1
      : 0;
    if (isCover) {
      state.currentResult._coverPolishSeed = nextSeed;
    } else {
      slide._polishVariationSeed = nextSeed;
    }
    const statusPill = document.getElementById("notes-polish-status-pill");
    const origText = btn.textContent;
    btn.disabled = true;
    btn.textContent = "⏳ Polishing Slide...";
    if (statusPill) {
      statusPill.textContent = "⏳ Calling Gemini Flash to polish slide script...";
    }
    try {
      const resp = await fetch("/api/v1/slide/polish-notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: state.currentResult.badge_name || "First Aid",
          slide_index: state.activeSlideIdx,
          slide_data: slide,
          audience_level:
            document.getElementById("audience-select")?.value ||
            slide.audience_level ||
            "All Scouts (Ages 11-17)",
          storyboard_slides: slides,
          counselor_info: state.currentResult.counselor_info || {},
          output_path: state.currentResult.output_path || "",
          force_refresh: shouldForceRefresh,
          variation_seed: nextSeed,
        }),
      });
      if (resp.ok) {
        const data = await resp.json();
        const src =
          data.polish_source ||
          (data.polish_engine === "gemini-flash" ? "GEMINI_FLASH" : "PROCEDURAL_STUDIO_POLISH");
        if (data.presenter_notes) {
          if (isCover) {
            state.currentResult._polishedCoverNotes = data.presenter_notes;
            state.currentResult._coverPolishSource = src;
            state.currentResult._coverPolishCacheHit = Boolean(data.cache_hit);
            state.currentResult._coverPolishFallbackReason = data.fallback_reason || "";
          } else {
            slide.presenter_notes = data.presenter_notes;
            slide._isPolishedNotes = true;
            slide._polishSource = src;
            slide._polishCacheHit = Boolean(data.cache_hit);
            slide._polishFallbackReason = data.fallback_reason || "";
          }
        }
        if (data.pptx_download_url) {
          state.currentResult.pptx_download_url = data.pptx_download_url;
          const pptxBtn = document.getElementById("btn-download-pptx");
          if (pptxBtn && state.preferredExportMode !== "gslides") {
            pptxBtn.href = `${data.pptx_download_url}?v=${Date.now()}`;
          }
        }
        renderActiveSlide(state.activeSlideIdx);
        if (typeof window.autoSaveActiveWorkspaceDebounced === "function") {
          window.autoSaveActiveWorkspaceDebounced({ promoteIfUnsaved: true });
        }
      }
    } catch (err) {
      console.warn("Could not polish slide notes:", err);
    } finally {
      btn.disabled = false;
      btn.textContent = origText;
    }
  };

  const executePolishEntireDeck = async (forceRefreshOverride = false) => {
    const btn = document.getElementById("btn-ai-polish-deck");
    if (!btn || !state.currentResult) return;
    const slides = state.currentResult.storyboard?.slides || [];
    if (!slides.length) return;
    const totalSlides = slides.length;
    const badgeName = state.currentResult.badge_name || "First Aid";
    const audienceLevel = document.getElementById("audience-select")?.value || "All Scouts (Ages 11-17)";
    const statusPill = document.getElementById("notes-polish-status-pill");
    const origText = btn.textContent;
    const shouldForceRefresh = Boolean(forceRefreshOverride);
    const t0 = performance.now();
    let completedCount = 0;
    let geminiCount = 0;
    let cacheHits = 0;
    let lastFallbackReason = "";

    const updateBatchCounterUi = (doneCount) => {
      const counterTag = `[${doneCount}/${totalSlides}]`;
      btn.textContent = `⏳ Polishing ${totalSlides} Slides ${counterTag}...`;
      if (statusPill) {
        statusPill.className = "m3-notes-provenance-pill";
        statusPill.textContent = `⏳ Batch-polishing all ${totalSlides} slides across deck ${counterTag}...`;
      }
    };

    btn.disabled = true;
    updateBatchCounterUi(0);

    try {
      const activeIdx = state.activeSlideIdx;
      const orderedIndices = [];
      if (activeIdx >= 0 && activeIdx < totalSlides) {
        orderedIndices.push(activeIdx);
      }
      for (let i = 0; i < totalSlides; i++) {
        if (i !== activeIdx) orderedIndices.push(i);
      }

      const coverPromise = fetch("/api/v1/slide/polish-notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: badgeName,
          slide_index: -1,
          slide_data: {
            title: `${badgeName} Merit Badge - Cover Slide`,
            req_number: "Cover",
            archetype: "TITLE_COVER_HERO",
          },
          audience_level: audienceLevel,
          storyboard_slides: [],
          force_refresh: shouldForceRefresh,
          variation_seed: shouldForceRefresh ? 1 : 0,
        }),
      })
        .then((r) => (r.ok ? r.json() : null))
        .then((cData) => {
          if (cData && cData.presenter_notes) {
            const cSrc =
              cData.polish_source ||
              (cData.polish_engine === "gemini-flash" ? "GEMINI_FLASH" : "PROCEDURAL_STUDIO_POLISH");
            state.currentResult._polishedCoverNotes = cData.presenter_notes;
            state.currentResult._coverPolishSource = cSrc;
            state.currentResult._coverPolishFallbackReason = cData.fallback_reason || "";
            if (state.activeSlideIdx === -1) {
              renderActiveSlide(-1);
              updateBatchCounterUi(completedCount);
            }
          }
        })
        .catch(() => {});

      let cursor = 0;
      const CONCURRENCY = 6;
      const runWorker = async () => {
        while (cursor < orderedIndices.length) {
          const idx = orderedIndices[cursor++];
          const sObj = slides[idx];
          if (!sObj) continue;
          if (!sObj._originalProceduralNotes && sObj.presenter_notes) {
            sObj._originalProceduralNotes = sObj.presenter_notes;
          }
          try {
            const sResp = await fetch("/api/v1/slide/polish-notes", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                badge_name: badgeName,
                slide_index: idx,
                slide_data: sObj,
                audience_level: audienceLevel,
                storyboard_slides: [],
                force_refresh: shouldForceRefresh,
                variation_seed: shouldForceRefresh ? (idx % 5) + 1 : 0,
              }),
            });
            if (sResp.ok) {
              const sData = await sResp.json();
              const src =
                sData.polish_source ||
                (sData.polish_engine === "gemini-flash" ? "GEMINI_FLASH" : "PROCEDURAL_STUDIO_POLISH");
              if (sData.presenter_notes) {
                sObj.presenter_notes = sData.presenter_notes;
                sObj._isPolishedNotes = true;
                sObj._polishSource = src;
                sObj._polishCacheHit = Boolean(sData.cache_hit);
                sObj._polishFallbackReason = sData.fallback_reason || "";
              }
              if (src === "GEMINI_FLASH") {
                geminiCount++;
              } else if (sData.fallback_reason && !lastFallbackReason) {
                lastFallbackReason = sData.fallback_reason;
              }
              if (sData.cache_hit) cacheHits++;
            }
          } catch (slideErr) {
            console.warn(`Could not polish slide ${idx}:`, slideErr);
          } finally {
            completedCount++;
            if (idx === state.activeSlideIdx) {
              renderActiveSlide(state.activeSlideIdx);
            }
            updateBatchCounterUi(completedCount);
          }
        }
      };

      const workers = Array.from({ length: Math.min(CONCURRENCY, orderedIndices.length) }, () => runWorker());
      await Promise.all([coverPromise, ...workers]);

      const batchResp = await fetch("/api/v1/slide/polish-notes-batch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: badgeName,
          storyboard_slides: slides,
          audience_level: audienceLevel,
          counselor_info: state.currentResult.counselor_info || {},
          output_path: state.currentResult.output_path || "",
          force_refresh: false,
        }),
      });
      if (batchResp.ok) {
        const batchData = await batchResp.json();
        if (batchData.pptx_download_url) {
          state.currentResult.pptx_download_url = batchData.pptx_download_url;
          const pptxBtn = document.getElementById("btn-download-pptx");
          if (pptxBtn && state.preferredExportMode !== "gslides") {
            pptxBtn.href = `${batchData.pptx_download_url}?v=${Date.now()}`;
          }
        }
      }

      const finalSource = geminiCount > 0 ? "GEMINI_FLASH" : "PROCEDURAL_STUDIO_POLISH";
      const elapsedMs = Math.round(performance.now() - t0);
      renderActiveSlide(state.activeSlideIdx);
      if (typeof window.autoSaveActiveWorkspaceDebounced === "function") {
        window.autoSaveActiveWorkspaceDebounced({ promoteIfUnsaved: true });
      }
      syncNotesPolishProvenancePill({
        isPolished: true,
        polishSource: finalSource,
        cacheHit: cacheHits > 0,
        fallbackReason: finalSource === "GEMINI_FLASH" ? "" : lastFallbackReason,
        batchSuffix: ` • All ${totalSlides} Slides (${elapsedMs}ms)`,
      });
    } catch (err) {
      console.warn("Could not batch-polish deck speaker notes:", err);
    } finally {
      btn.disabled = false;
      btn.textContent = origText;
    }
  };

  const openAiPolishFinopsGateModal = async (requestedMode = "single") => {
    const modal = document.getElementById("ai-polish-finops-modal");
    if (!modal || !state.currentResult) return;
    const slides = state.currentResult.storyboard?.slides || [];
    const totalSlides = slides.length + 1;
    const isCover = state.activeSlideIdx === -1;
    const activeSlide = isCover
      ? { title: `${state.currentResult.badge_name || "First Aid"} Merit Badge - Cover Slide`, req_number: "Cover" }
      : slides[Math.max(0, state.activeSlideIdx)] || {};

    const singleCard = document.getElementById("finops-card-single-slide");
    const deckCard = document.getElementById("finops-card-entire-deck");
    const singleBadge = document.getElementById("finops-single-cache-badge");
    const singleCostEl = document.getElementById("finops-single-cost-value");
    const singleMetaEl = document.getElementById("finops-single-token-meta");
    const deckCountBadge = document.getElementById("finops-deck-slide-count-badge");
    const deckOptionKicker = document.getElementById("finops-deck-option-kicker");
    const deckCostEl = document.getElementById("finops-deck-cost-value");
    const deckMetaEl = document.getElementById("finops-deck-token-meta");
    const leadCountEl = document.getElementById("finops-lead-slide-count");
    const leadBadgeEl = document.getElementById("finops-lead-badge-name");
    const forceChk = document.getElementById("chk-finops-force-repolish");
    const btnSingle = document.getElementById("btn-confirm-polish-single-slide");
    const btnDeck = document.getElementById("btn-confirm-polish-entire-deck");

    if (singleCard) {
      singleCard.style.borderColor = requestedMode === "single" ? "#4F46E5" : "#C7D2FE";
      singleCard.style.boxShadow =
        requestedMode === "single" ? "0 0 0 3px rgba(79, 70, 229, 0.16)" : "none";
    }
    if (deckCard) {
      deckCard.style.borderColor = requestedMode === "deck" ? "#D97706" : "#FCD34D";
      deckCard.style.boxShadow =
        requestedMode === "deck" ? "0 0 0 3px rgba(217, 119, 6, 0.18)" : "none";
    }

    let estimate = {
      single_slide_cached: false,
      single_slide_input_tokens: 450,
      single_slide_output_tokens: 280,
      single_slide_cost_usd: 0.000835,
      total_slides: totalSlides,
      cached_slides_count: 0,
      uncached_slides_count: totalSlides,
      deck_uncached_cost_usd: Number((totalSlides * 0.000835).toFixed(4)),
      deck_full_repolish_cost_usd: Number((totalSlides * 0.000835).toFixed(4)),
    };

    const renderEstimateUi = () => {
      const force = Boolean(forceChk?.checked);
      const slideNumLabel = isCover ? "Cover Slide" : `Slide #${state.activeSlideIdx + 2}`;
      const singleCached = estimate.single_slide_cached && !force;
      const singleUsd = singleCached ? 0 : estimate.single_slide_cost_usd || 0.000835;
      if (leadBadgeEl) {
        leadBadgeEl.textContent = `${state.currentResult.badge_name || "First Aid"} Merit Badge`;
      }
      if (singleBadge) {
        singleBadge.textContent = singleCached ? `${slideNumLabel} • Cached ($0)` : slideNumLabel;
      }
      if (singleCostEl) {
        singleCostEl.innerHTML = singleCached
          ? `$0.0000 <span style="font-size:0.78rem; font-weight:700; color:#15803D;">(Cached in SQLite • ~$0.0008 if re-polished)</span>`
          : `~$${singleUsd.toFixed(4)} <span style="font-size:0.78rem; font-weight:700; color:#475569;">(&lt; $0.001 / slide)</span>`;
      }
      if (singleMetaEl) {
        singleMetaEl.innerHTML = `~${estimate.single_slide_input_tokens} input tokens + ~${estimate.single_slide_output_tokens} output tokens<br/>Latency: ~1.5 seconds • Cached in SQLite (${singleCached ? "Already cached: $0.00" : "$0.00 on repeat"})`;
      }

      const nTotal = estimate.total_slides || totalSlides;
      const nCached = estimate.cached_slides_count || 0;
      const nUncached = force ? nTotal : estimate.uncached_slides_count ?? nTotal;
      const deckUsd = force
        ? estimate.deck_full_repolish_cost_usd || nTotal * 0.000835
        : estimate.deck_uncached_cost_usd ?? nUncached * 0.000835;

      if (leadCountEl) {
        leadCountEl.textContent = `${nTotal}-slide`;
      }
      if (deckOptionKicker) {
        deckOptionKicker.textContent = `OPTION 2 • ENTIRE ${nTotal}-SLIDE DECK`;
      }
      if (deckCountBadge) {
        deckCountBadge.textContent =
          nCached > 0 && !force
            ? `${nTotal} Slides (${nCached} Cached)`
            : `${nTotal} Slides`;
      }
      if (deckCostEl) {
        deckCostEl.innerHTML = `~$${Number(deckUsd).toFixed(4)} <span style="font-size:0.78rem; font-weight:700; color:#92400E;">(${nTotal} slides × $0.0008)</span>`;
      }
      if (deckMetaEl) {
        deckMetaEl.innerHTML =
          nCached > 0 && !force
            ? `~${(nUncached * 450).toLocaleString()} input + ~${(nUncached * 280).toLocaleString()} output tokens (${nCached} already cached at $0.00)<br/>Parallel 6x worker pool • Live <code>[1/${nTotal}]</code> progress counter`
            : `~${(nTotal * 450).toLocaleString()} input tokens + ~${(nTotal * 280).toLocaleString()} output tokens<br/>Parallel 6x worker pool • Live <code>[1/${nTotal}]</code> progress counter`;
      }
      if (btnSingle) {
        btnSingle.textContent = `✨ Polish This Slide (~$${singleUsd > 0 ? singleUsd.toFixed(4) : "0.0008"})`;
      }
      if (btnDeck) {
        btnDeck.textContent = `✨ Polish All ${nTotal} Slides (~$${Number(deckUsd).toFixed(4)})`;
      }
    };

    renderEstimateUi();
    modal.classList.remove("hidden");
    modal.classList.add("open");

    try {
      const resp = await fetch("/api/v1/slide/estimate-polish-cost", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          badge_name: state.currentResult.badge_name || "First Aid",
          slide_index: state.activeSlideIdx,
          slide_data: activeSlide,
          storyboard_slides: slides,
          audience_level:
            document.getElementById("audience-select")?.value || "All Scouts (Ages 11-17)",
        }),
      });
      if (resp.ok) {
        const serverEst = await resp.json();
        estimate = { ...estimate, ...serverEst };
        renderEstimateUi();
      }
    } catch (_e) {}

    if (forceChk) {
      forceChk.onchange = () => renderEstimateUi();
    }
  };

  document.getElementById("btn-close-ai-polish-finops")?.addEventListener("click", () => {
    const m = document.getElementById("ai-polish-finops-modal");
    m?.classList.remove("open");
    m?.classList.add("hidden");
  });
  document.getElementById("btn-cancel-ai-polish-finops")?.addEventListener("click", () => {
    const m = document.getElementById("ai-polish-finops-modal");
    m?.classList.remove("open");
    m?.classList.add("hidden");
  });
  document.getElementById("btn-confirm-polish-single-slide")?.addEventListener("click", async () => {
    const m = document.getElementById("ai-polish-finops-modal");
    const force = Boolean(document.getElementById("chk-finops-force-repolish")?.checked);
    const dontAsk = Boolean(document.getElementById("chk-finops-dont-ask-session")?.checked);
    if (dontAsk) {
      try {
        window.sessionStorage.setItem("bsa_ai_polish_finops_ack_v1", "1");
      } catch (_e) {}
    }
    m?.classList.remove("open");
    m?.classList.add("hidden");
    await executePolishSingleSlide(force ? true : null);
  });
  document.getElementById("btn-confirm-polish-entire-deck")?.addEventListener("click", async () => {
    const m = document.getElementById("ai-polish-finops-modal");
    const force = Boolean(document.getElementById("chk-finops-force-repolish")?.checked);
    const dontAsk = Boolean(document.getElementById("chk-finops-dont-ask-session")?.checked);
    if (dontAsk) {
      try {
        window.sessionStorage.setItem("bsa_ai_polish_finops_ack_v1", "1");
      } catch (_e) {}
    }
    m?.classList.remove("open");
    m?.classList.add("hidden");
    await executePolishEntireDeck(force);
  });

  document.getElementById("btn-ai-polish-notes")?.addEventListener("click", async () => {
    if (!state.currentResult) return;
    let acked = false;
    try {
      acked = window.sessionStorage.getItem("bsa_ai_polish_finops_ack_v1") === "1";
    } catch (_e) {}
    if (!acked) {
      await openAiPolishFinopsGateModal("single");
      return;
    }
    await executePolishSingleSlide(null);
  });

  document.getElementById("btn-ai-polish-deck")?.addEventListener("click", async () => {
    if (!state.currentResult) return;
    let acked = false;
    try {
      acked = window.sessionStorage.getItem("bsa_ai_polish_finops_ack_v1") === "1";
    } catch (_e) {}
    if (!acked) {
      await openAiPolishFinopsGateModal("deck");
      return;
    }
    await executePolishEntireDeck(false);
  });

  // Quick-Switch Slide Image button
  document.getElementById("btn-quick-switch-image")?.addEventListener("click", async () => {
    const sel = document.getElementById("codesign-quick-image-select");
    if (!sel || !state.combinedSlideImages.length) return;
    const idx = parseInt(sel.value, 10);
    if (isNaN(idx) || idx < 0 || idx >= state.combinedSlideImages.length) return;
    await applyCatalogImageToActiveSlide(state.combinedSlideImages[idx]);
  });

  document.querySelectorAll(".m3-badge-pill").forEach((pill) => {
    pill.addEventListener("click", async () => {
      const badge = pill.getAttribute("data-badge");
      if (!badge) return;
      if (!state.filteredBadges.some((b) => b.badge_name === badge)) {
        if (searchInput) searchInput.value = "";
        if (catSelect) catSelect.value = "ALL";
        if (eagleSelect) eagleSelect.value = "ALL";
        applyBadgeFilters(false);
      }
      document.querySelectorAll(".m3-badge-pill").forEach((p) => p.classList.remove("active"));
      pill.classList.add("active");
      const select = document.getElementById("badge-select");
      if (select) {
        select.value = badge;
      }
      await executeStreamingWorkflow(badge);
    });
  });

  document.getElementById("badge-select")?.addEventListener("change", async (e) => {
    const badge = e.target.value;
    if (!badge) return;
    document.querySelectorAll(".m3-badge-pill").forEach((p) => {
      p.classList.toggle("active", p.getAttribute("data-badge") === badge);
    });
    const badgeEntry = (state.badges || []).find(
      (b) => String(b.badge_name || "").toLowerCase() === String(badge).toLowerCase()
    );
    const tracks = Array.isArray(badgeEntry?.option_tracks) ? badgeEntry.option_tracks : [];
    const isMultiOpt = Boolean(badgeEntry?.has_option_tracks || tracks.length >= 2);
    if (isMultiOpt) {
      if (typeof window.abortActiveWorkflowStream === "function") {
        window.abortActiveWorkflowStream();
      }
      state.currentBadge = badge;
      if (typeof window.syncActiveBadgeOptionTrackSelector === "function") {
        window.syncActiveBadgeOptionTrackSelector(badge, "PROMPT");
      }
      const wrapEl = document.getElementById("option-track-field-wrap");
      if (wrapEl) {
        wrapEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
        wrapEl.style.transition = "box-shadow 0.25s ease, transform 0.25s ease";
        wrapEl.style.boxShadow = "0 0 0 3px rgba(37, 99, 235, 0.35)";
        setTimeout(() => {
          wrapEl.style.boxShadow = "";
        }, 1400);
      }
      return;
    }
    if (typeof window.syncActiveBadgeOptionTrackSelector === "function") {
      window.syncActiveBadgeOptionTrackSelector(badge, "ALL");
    }
    await executeStreamingWorkflow(badge, { optionTrack: "ALL" });
  });

  document.getElementById("option-track-select")?.addEventListener("change", async (e) => {
    const rawVal = e.target.value || "ALL";
    if (rawVal === "PROMPT") return;
    const optVal = rawVal;
    const badge = document.getElementById("badge-select")?.value || state.currentBadge || "First Aid";
    if (!badge) return;
    if (typeof window.syncActiveBadgeOptionTrackSelector === "function") {
      window.syncActiveBadgeOptionTrackSelector(badge, optVal);
    }
    await executeStreamingWorkflow(badge, { optionTrack: optVal, isExplicitBuild: true });
  });

  document.getElementById("btn-prev-slide")?.addEventListener("click", () => {
    const slides = state.currentResult?.storyboard?.slides || [];
    if (state.activeSlideIdx > -1) {
      state.activeSlideIdx -= 1;
      renderFilmstrip(slides);
      renderActiveSlide(state.activeSlideIdx);
      scrollActiveFilmstripThumbIntoView(true);
    }
  });

  document.getElementById("btn-next-slide")?.addEventListener("click", () => {
    const slides = state.currentResult?.storyboard?.slides || [];
    if (state.activeSlideIdx < slides.length - 1) {
      state.activeSlideIdx += 1;
      renderFilmstrip(slides);
      renderActiveSlide(state.activeSlideIdx);
      scrollActiveFilmstripThumbIntoView(true);
    }
  });

  document.getElementById("btn-download-agenda-md")?.addEventListener("click", () => {
    const badge = state.currentResult?.badge_name || document.getElementById("badge-select")?.value || "First Aid";
    const fmt = document.getElementById("studiokit-schedule-select")?.value || "3 Troop Meetings (45 min each)";
    const counselor = document.getElementById("input-counselor-name")?.value || "Eric Clayberg";
    const troop = document.getElementById("input-troop-name")?.value || "Troop 19, Northeast Massachusetts Council";
    const url = `/api/v1/studiokit/agenda.pdf?badge_name=${encodeURIComponent(badge)}&schedule_format=${encodeURIComponent(
      fmt
    )}&counselor_name=${encodeURIComponent(counselor)}&troop_name=${encodeURIComponent(troop)}`;
    const a = document.createElement("a");
    a.href = url;
    a.download = `${badge.replace(/\s+/g, "_")}_session_agenda.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  });

  document.getElementById("btn-download-letter-md")?.addEventListener("click", () => {
    const badge = state.currentResult?.badge_name || document.getElementById("badge-select")?.value || "First Aid";
    const stageBtn = document.querySelector("#letter-stage-pill-group .m3-quick-mode-btn.active");
    const stage = stageBtn?.getAttribute("data-letter-stage") || "stage_1_welcome_cpp";
    const counselor = document.getElementById("input-counselor-name")?.value || "Eric Clayberg";
    const troop = document.getElementById("input-troop-name")?.value || "Troop 19, Northeast Massachusetts Council";
    const email = document.getElementById("input-counselor-email")?.value || "counselor@troop19.org";
    const url = `/api/v1/studiokit/parent-letter.pdf?badge_name=${encodeURIComponent(badge)}&stage=${encodeURIComponent(
      stage
    )}&counselor_name=${encodeURIComponent(counselor)}&troop_name=${encodeURIComponent(
      troop
    )}&counselor_email=${encodeURIComponent(email)}`;
    const a = document.createElement("a");
    a.href = url;
    a.download = `${badge.replace(/\s+/g, "_")}_parent_prerequisite_letter.pdf`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  });
}

function triggerMarkdownDownload(filename, content) {
  const blob = new Blob([content], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

async function loadBadgesCatalog() {
  const data = await fetch("/api/badges").then((r) => r.json());
  state.badges = data.badges || [];
  state.categories = data.categories || [];

  const totalCount = state.badges.length;
  const eagleCount = state.badges.filter((b) => b.is_eagle_required).length;
  const electiveCount = totalCount - eagleCount;

  const searchInput = document.getElementById("filter-search-input");
  if (searchInput) {
    if (!searchInput._userHasInteracted && (searchInput.value === "Local" || searchInput.value === "admin-superuser")) {
      searchInput.value = "";
    }
    if (totalCount > 0) {
      searchInput.placeholder = `Search all ${totalCount} badges (e.g., Weather, First Aid, Kayaking)...`;
    }
  }

  const multiOptCount = (state.badges || []).filter(
    (b) => b.has_option_tracks || (Array.isArray(b.option_tracks) && b.option_tracks.length >= 2)
  ).length || 18;
  const testLabCount = (state.badges || []).filter((b) => Boolean(b.is_test_lab_pilot)).length || 5;

  const eagleSelect = document.getElementById("filter-eagle-select");
  if (eagleSelect && totalCount > 0) {
    const prevEagleVal = eagleSelect.value || "ALL";
    const favCount = (state.favoriteBadges || []).length;
    eagleSelect.innerHTML = `
      <option value="ALL">All Badges (${totalCount})</option>
      <option value="FAVORITES">Favorites (${favCount})</option>
      <option value="EAGLE">Eagle-Required (${eagleCount})</option>
      <option value="ELECTIVE">Electives (${electiveCount})</option>
      <option value="MULTI_OPTION">Multi-Option Badges (${multiOptCount})</option>
      <option value="TEST_LAB">🧪 Test Lab Pilot (${testLabCount})</option>
    `;
    eagleSelect.value = prevEagleVal;
  }

  const catSelect = document.getElementById("filter-category-select");
  if (catSelect) {
    const prevCatVal = catSelect.value || "ALL";
    catSelect.innerHTML = `
      <option value="ALL">All Categories</option>
    `;
    state.categories.forEach((cat) => {
      const opt = document.createElement("option");
      opt.value = cat;
      opt.textContent = cat;
      catSelect.appendChild(opt);
    });
    if (Array.from(catSelect.options).some((o) => o.value === prevCatVal)) {
      catSelect.value = prevCatVal;
    }
  }

  applyBadgeFilters(true);
  populateAdminBadgeSelector();
}

function applyBadgeFilters(initialLoad = false) {
  const query = (document.getElementById("filter-search-input")?.value || "").trim().toLowerCase();
  const category = document.getElementById("filter-category-select")?.value || "ALL";
  const eagleMode = document.getElementById("filter-eagle-select")?.value || "ALL";

  const favSet = new Set((state.favoriteBadges || []).map((x) => String(x).toLowerCase()));
  state.filteredBadges = state.badges.filter((b) => {
    const isMultiOpt = Boolean(b.has_option_tracks || (Array.isArray(b.option_tracks) && b.option_tracks.length >= 2));
    const isTestLab = Boolean(b.is_test_lab_pilot);
    if (query && !b.badge_name.toLowerCase().includes(query) && !(b.category || "").toLowerCase().includes(query)) {
      return false;
    }
    if (category === "MULTI_OPTION") {
      if (!isMultiOpt) return false;
    } else if (category === "TEST_LAB") {
      if (!isTestLab) return false;
    } else if (category !== "ALL" && b.category !== category) {
      return false;
    }
    if (eagleMode === "FAVORITES" && !favSet.has(b.badge_name.toLowerCase())) {
      return false;
    }
    if (eagleMode === "EAGLE" && !b.is_eagle_required) {
      return false;
    }
    if (eagleMode === "ELECTIVE" && b.is_eagle_required) {
      return false;
    }
    if (eagleMode === "MULTI_OPTION" && !isMultiOpt) {
      return false;
    }
    if (eagleMode === "TEST_LAB" && !isTestLab) {
      return false;
    }
    return true;
  });

  const countChip = document.getElementById("badge-filter-count-chip");
  if (countChip) {
    countChip.innerHTML = `<span id="gallery-filtered-count-badge">${state.filteredBadges.length}</span> of ${state.badges.length} Badges`;
  }

  const select = document.getElementById("badge-select");
  if (!select) return;
  const prevValue = initialLoad ? "First Aid" : select.value || state.currentBadge;
  select.innerHTML = "";

  if (state.filteredBadges.length === 0) {
    const emptyOpt = document.createElement("option");
    emptyOpt.value = "";
    emptyOpt.textContent = "No matching Merit Badges — adjust filters";
    select.appendChild(emptyOpt);
    return;
  }

  state.filteredBadges.forEach((b) => {
    const opt = document.createElement("option");
    opt.value = b.badge_name;
    const isFav = favSet.has(b.badge_name.toLowerCase());
    const statusSuffix = b.is_discontinued
      ? " [🚫 Discontinued]"
      : b.is_test_lab_pilot
      ? " [🧪 Test Lab]"
      : "";
    opt.textContent = `${isFav ? "⭐ " : ""}${b.is_eagle_required ? "★ " : ""}${b.badge_name}${statusSuffix} (${b.category})`;
    select.appendChild(opt);
  });

  if (state.filteredBadges.some((b) => b.badge_name === prevValue)) {
    select.value = prevValue;
  } else {
    select.value = state.filteredBadges[0].badge_name;
  }
  if (typeof window.syncActiveBadgeStarButton === "function") {
    window.syncActiveBadgeStarButton();
  }
}

function friendlyStepLabel(agentName) {
  const map = {
    PamphletResearchAgent: "1. Pamphlet & Requirements Research",
    DeepResearchEnrichmentAgent: "2. Grounded Web & Local Troop Research",
    SlideContentPlannerAgent: "3. Slide Deck Outline & Teaching Plan",
    FastMCPConfirmationGate: "4. Curriculum Verification",
    SlideBeautifierAgent: "5. AI Slide Beautification & Visual Blueprint",
    PowerPointBuilderAgent: "6. PowerPoint, Workbook & StudioKit Builder",
    BSABrandAndSafetyReviewAgent: "7. Final Slide & FinOps Quality Check",
  };
  return map[agentName] || agentName;
}

function inferBrowserLocationHint() {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
    const tzMap = {
      "America/New_York": "Boston, MA",
      "America/Detroit": "Detroit, MI",
      "America/Chicago": "Chicago, IL",
      "America/Denver": "Denver, CO",
      "America/Phoenix": "Phoenix, AZ",
      "America/Los_Angeles": "San Francisco, CA",
      "America/Anchorage": "Anchorage, AK",
      "Pacific/Honolulu": "Honolulu, HI",
    };
    return tzMap[tz] || "";
  } catch (_e) {
    return "";
  }
}

window.abortActiveWorkflowStream = function abortActiveWorkflowStream() {
  state._workflowRunId = (state._workflowRunId || 0) + 1;
  if (state._activeWorkflowEventSource) {
    try {
      state._activeWorkflowEventSource.close();
    } catch (_e) {}
    state._activeWorkflowEventSource = null;
  }
  if (state._activeWorkflowAbortController) {
    try {
      state._activeWorkflowAbortController.abort();
    } catch (_e) {}
    state._activeWorkflowAbortController = null;
  }
  const genBtn = document.getElementById("btn-generate-deck");
  if (genBtn) {
    genBtn.disabled = false;
    genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">✨</span> Generate Slide Deck &amp; Workbook';
  }
  if (state.currentResult && state.currentResult.storyboard) {
    const progressFill = document.getElementById("trace-progress-fill");
    const progressLabel = document.getElementById("trace-progress-label");
    const traceList = document.getElementById("agent-trace-list");
    const traceToggleBtn = document.getElementById("btn-toggle-trace-details");
    const filmstripEl = document.getElementById("slide-filmstrip-list");
    if (progressFill) progressFill.style.width = "100%";
    if (progressLabel) progressLabel.textContent = "Complete";
    traceList?.classList.add("hidden");
    if (traceToggleBtn) traceToggleBtn.textContent = "Details ▾";
    filmstripEl?.classList.remove("hidden");
    if (typeof hideConstructionAnimationStage === "function") {
      hideConstructionAnimationStage();
    }
  }
};

async function executeStreamingWorkflow(badgeName, options = {}) {
  if (typeof window.abortActiveWorkflowStream === "function") {
    window.abortActiveWorkflowStream();
  }
  state.currentBadge = badgeName;
  state._promoteDeckOnHydrate = Boolean(options && options.isExplicitBuild);
  clearDeckConfigDirty();
  state.revealedQuizSlides = new Set();
  state.checkedGearItems = new Set();
  state.patrolScoreboardVisible = false;
  document.getElementById("stage-patrol-scoreboard")?.classList.add("hidden");
  document.getElementById("btn-toggle-patrol-scoreboard")?.classList.remove("active");
  const depthMode = document.getElementById("depth-select")?.value || "Deep Dive / Camp School Deck";
  const beautificationTier = document.getElementById("beautification-select")?.value || "BEAUTIFIED";
  const audienceLevel = document.getElementById("audience-select")?.value || "All Scouts (Ages 11–17)";
  const enableDeepResearch = document.getElementById("deep-research-checkbox")?.checked ?? true;
  const counselorName = document.getElementById("input-counselor-name")?.value || "Scoutmaster Bob";
  const troopName = document.getElementById("input-troop-name")?.value || "Troop 123, My Council";
  const rawLocationInput = (document.getElementById("input-counselor-location")?.value || "").trim();
  const locationOrZip =
    rawLocationInput ||
    (troopName === "Troop 123, My Council" ? inferBrowserLocationHint() : "");
  const email = document.getElementById("input-counselor-email")?.value ?? "counselor@troop123.org";
  const phone = document.getElementById("input-counselor-phone")?.value ?? "(000) 555-1234";
  const customLogoPath = state.customLogoPath || "";

  const progressFill = document.getElementById("trace-progress-fill");
  const progressLabel = document.getElementById("trace-progress-label");
  const traceList = document.getElementById("agent-trace-list");
  const traceToggleBtn = document.getElementById("btn-toggle-trace-details");
  const genBtn = document.getElementById("btn-generate-deck");
  const filmstripEl = document.getElementById("slide-filmstrip-list");

  // Hide the slide list while new slides are being generated so Research & Generation Progress occupies the top of the column
  if (filmstripEl) {
    filmstripEl.classList.add("hidden");
  }
  traceList?.classList.remove("hidden");
  if (traceToggleBtn) traceToggleBtn.textContent = "Hide ▴";
  showConstructionAnimationStage(badgeName, false);

  if (genBtn) {
    genBtn.disabled = true;
    genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">⏳</span> Generating Deck &amp; Workbook...';
  }

  if (progressFill) progressFill.style.width = "10%";
  if (progressLabel) progressLabel.textContent = "10%";
  if (traceList) {
    traceList.innerHTML = `
      <div class="m3-trace-item">
        <div class="m3-trace-top"><span>Starting Generation</span><span class="m3-trace-meta">In Progress</span></div>
        <div class="m3-trace-desc">Researching official ${escapeHtml(badgeName)} Merit Badge requirements and applying ${escapeHtml(formatSlideThemeLabel(beautificationTier))} theme...</div>
      </div>
    `;
  }

  const activeTemplateId =
    state.activeTemplateId ||
    document.getElementById("template-select")?.value ||
    "bsa_scouting_america";
  const activeDeckStyle =
    typeof getCurrentDeckStyleConfig === "function"
      ? getCurrentDeckStyleConfig()
      : {
          layout_style: "AUTO_TEMPLATE",
          text_container_style: "AUTO",
          image_frame_style: "AUTO",
          header_chrome_style: "AUTO",
          typography_scale: "COMFORTABLE",
          safety_banner_mode: "ACUTE_HAZARDS_ONLY",
        };
  if (typeof window.syncActiveBadgeOptionTrackSelector === "function" && (badgeName !== state._lastOptionTrackBadge || options?.optionTrack)) {
    window.syncActiveBadgeOptionTrackSelector(badgeName, options?.optionTrack || "ALL");
  }
  const rawOptionTrack =
    options?.optionTrack ||
    document.getElementById("option-track-select")?.value ||
    "ALL";
  const optionTrack = rawOptionTrack === "PROMPT" ? "ALL" : rawOptionTrack;
  const paramsObj = {
    badge_name: badgeName,
    depth_mode: depthMode,
    beautification_tier: beautificationTier,
    audience_level: audienceLevel,
    enable_deep_research: String(enableDeepResearch),
    counselor_name: counselorName,
    troop_affiliation: troopName,
    location_or_zip: locationOrZip,
    email_address: email,
    phone_number: phone,
    template_id: activeTemplateId,
    option_track: optionTrack,
    layout_style: activeDeckStyle.layout_style,
    text_container_style: activeDeckStyle.text_container_style,
    image_frame_style: activeDeckStyle.image_frame_style,
    header_chrome_style: activeDeckStyle.header_chrome_style,
    typography_scale: activeDeckStyle.typography_scale,
    safety_banner_mode: activeDeckStyle.safety_banner_mode,
  };
  if (customLogoPath) {
    paramsObj.custom_troop_logo_path = customLogoPath;
  }
  const params = new URLSearchParams(paramsObj);

  const runId = (state._workflowRunId || 0) + 1;
  state._workflowRunId = runId;
  const abortCtrl = new AbortController();
  state._activeWorkflowAbortController = abortCtrl;

  return new Promise((resolve) => {
    const es = new EventSource(`/api/workflow/stream?${params.toString()}`);
    state._activeWorkflowEventSource = es;

    es.onmessage = (evt) => {
      if (state._workflowRunId !== runId || abortCtrl.signal.aborted) {
        es.close();
        resolve(null);
        return;
      }
      const payload = JSON.parse(evt.data);
      const pct = payload.progress_pct || 50;
      if (progressFill) progressFill.style.width = `${pct}%`;
      if (progressLabel) progressLabel.textContent = pct >= 100 ? "Complete" : `${pct}%`;

      if (payload.event === "workflow_complete" && payload.result) {
        es.close();
        if (state._activeWorkflowEventSource === es) {
          state._activeWorkflowEventSource = null;
        }
        if (state._activeWorkflowAbortController === abortCtrl) {
          state._activeWorkflowAbortController = null;
        }
        if (state._workflowRunId === runId && genBtn) {
          genBtn.disabled = false;
          genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">✨</span> Generate Slide Deck &amp; Workbook';
        }
        hydrateWorkbench(payload.result);
        resolve(payload.result);
      } else if (payload.event === "workflow_error" || payload.event === "workflow_aborted") {
        es.close();
        if (state._activeWorkflowEventSource === es) {
          state._activeWorkflowEventSource = null;
        }
        if (state._activeWorkflowAbortController === abortCtrl) {
          state._activeWorkflowAbortController = null;
        }
        if (state._workflowRunId === runId && genBtn) {
          genBtn.disabled = false;
          genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">✨</span> Generate Slide Deck &amp; Workbook';
        }
        resolve(null);
      } else if (payload.agent && traceList) {
        const kickerEl = document.getElementById("construction-workorder-kicker");
        if (kickerEl) {
          kickerEl.textContent = `${friendlyStepLabel(payload.agent).toUpperCase()} (${pct}%)`;
        }
        const item = document.createElement("div");
        item.className = "m3-trace-item";
        item.innerHTML = `
          <div class="m3-trace-top">
            <span>${escapeHtml(friendlyStepLabel(payload.agent))}</span>
            <span class="m3-trace-meta">Done</span>
          </div>
          <div class="m3-trace-desc">${escapeHtml(payload.message || "")}</div>
        `;
        traceList.appendChild(item);
      }
    };

    es.onerror = async () => {
      es.close();
      if (state._activeWorkflowEventSource === es) {
        state._activeWorkflowEventSource = null;
      }
      if (state._workflowRunId !== runId || abortCtrl.signal.aborted) {
        resolve(null);
        return;
      }
      try {
        const res = await fetch("/api/workflow/run", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: abortCtrl.signal,
          body: JSON.stringify({
            badge_name: badgeName,
            depth_mode: depthMode,
            beautification_tier: beautificationTier,
            audience_level: audienceLevel,
            enable_deep_research: enableDeepResearch,
            counselor_name: counselorName,
            troop_affiliation: troopName,
            location_or_zip: locationOrZip,
            email_address: email,
            phone_number: phone,
            custom_troop_logo_path: customLogoPath || null,
            template_id: activeTemplateId,
            option_track: optionTrack,
            deck_style: activeDeckStyle,
          }),
        }).then((r) => r.json());
        if (state._workflowRunId !== runId || abortCtrl.signal.aborted) {
          resolve(null);
          return;
        }
        hydrateWorkbench(res);
        resolve(res);
      } catch (_err) {
        resolve(null);
      } finally {
        if (state._workflowRunId === runId && genBtn) {
          genBtn.disabled = false;
          genBtn.innerHTML = '<span class="m3-inline-icon" aria-hidden="true">✨</span> Generate Slide Deck &amp; Workbook';
        }
      }
    };
  });
}

function hydrateWorkbench(rawResult, options = {}) {
  const result = rawResult?.result && rawResult.result.storyboard ? rawResult.result : rawResult;
  if (!result || result.status === "ERROR" || !result.badge_name || !result.storyboard) return;
  if (!options.fromTourCache) {
    state._cachedBadgeResultsByKey = state._cachedBadgeResultsByKey || {};
    const cacheTrackKey = String(
      result.option_track ||
        result.research_artifact?.selected_option_track ||
        "ALL"
    ).toUpperCase();
    try {
      const snapshot = JSON.parse(JSON.stringify(result));
      state._cachedBadgeResultsByKey[`${result.badge_name}::${cacheTrackKey}`] = snapshot;
      if (cacheTrackKey === "ALL" || !result.option_track) {
        state._cachedBadgeResultsByKey[`${result.badge_name}::ALL`] = snapshot;
      }
    } catch (_err) {
      state._cachedBadgeResultsByKey[`${result.badge_name}::${cacheTrackKey}`] = result;
    }
  }
  state.currentResult = result;
  state.activeSlideIdx = -1;
  clearDeckConfigDirty();
  if (!state.activeDemoTour || state.activeDemoTour.scenarioId !== "demo-6-presenter-and-quiz") {
    state.patrolScoreboardVisible = false;
    document.getElementById("stage-patrol-scoreboard")?.classList.add("hidden");
    document.getElementById("btn-toggle-patrol-scoreboard")?.classList.remove("active");
  }
  if (result.deep_research_enrichment?.resolved_location && typeof window.syncDynamicTour1LocationText === "function") {
    window.syncDynamicTour1LocationText(result.deep_research_enrichment.resolved_location);
  }

  const slides = result.storyboard?.slides || [];
  if (result.template_id && !state.activeTemplateId) {
    state.activeTemplateId = result.template_id;
  }
  const hydrateProf = typeof getActiveTemplateProfile === "function" ? getActiveTemplateProfile() : null;
  if (hydrateProf) {
    state.activeTemplateProfile = hydrateProf;
  }
  const matchPaletteOnHydrate = document.getElementById("template-match-palette-checkbox")?.checked !== false;
  slides.forEach((s, idx) => {
    if (!s._uid) {
      s._uid = `sl_${idx}_${s.req_number || ""}_${(s.title || "").slice(0, 24)}`;
    }
    if (hydrateProf && hydrateProf.template_id !== "default_workbench") {
      s.template_id = hydrateProf.template_id;
      if (matchPaletteOnHydrate && !s._customPaletteOverride) {
        s.accent_palette_key = "MATCH_TEMPLATE";
        s.brand_palette = "MATCH_TEMPLATE";
      }
    }
  });
  if (state._deckCustomizeDebounceTimer) {
    clearTimeout(state._deckCustomizeDebounceTimer);
    state._deckCustomizeDebounceTimer = null;
  }
  state._lastSyncedStoryboardSignature = computeStoryboardDeckSignature(slides);
  const reqs = result.research_artifact?.requirements || [];
  const finops = result.finops_cost_estimate || {};
  const resolvedLoc = result.deep_research_enrichment?.resolved_location || {};

  // Update Location inference hint so counselor sees the resolved region & NOAA office
  const locHintEl = document.getElementById("location-infer-hint");
  if (locHintEl && resolvedLoc.region_label) {
    locHintEl.innerHTML = `Resolved Local Context: <strong>${escapeHtml(resolvedLoc.region_label)}</strong> &bull; ${escapeHtml(resolvedLoc.nws_office || "NOAA NWS")}`;
  }

  // Update Visual Polish & Pre-Cached Assets Pill in Sidebar
  const finopsUsdEl = document.getElementById("finops-cost-usd");
  const finopsMetaEl = document.getElementById("finops-cost-meta");
  const tierNow = finops.beautification_tier || result.beautification_tier || "BEAUTIFIED";
  if (finopsUsdEl) {
    finopsUsdEl.innerHTML =
      tierNow === "STANDARD"
        ? `<strong>Visual Assets:</strong> Pamphlet Figures Only (Lightweight)`
        : `<strong>Visual Assets:</strong> 100% Pre-Cached (8-Bit PNG)`;
  }
  if (finopsMetaEl) {
    finopsMetaEl.textContent = `${formatSlideThemeLabel(tierNow)} • Instant Load`;
  }

  // 1. Update Hero Banner, Patch Image & Resource Links
  document.getElementById("hero-badge-title").textContent = `${result.badge_name} Merit Badge`;
  const categoryLabel = result.category ? ` • ${result.category.toUpperCase()}` : "";
  document.getElementById("hero-eagle-kicker").innerHTML = result.is_eagle_required
    ? `<span class="m3-inline-icon" aria-hidden="true">★</span><span>EAGLE-REQUIRED MERIT BADGE${escapeHtml(categoryLabel)}</span>`
    : `<span class="m3-inline-icon" aria-hidden="true">✓</span><span>SCOUTS BSA ELECTIVE MERIT BADGE${escapeHtml(categoryLabel)}</span>`;

  const activeTier = result.beautification_tier || document.getElementById("beautification-select")?.value || "BEAUTIFIED";
  const activeThemeLabel = formatSlideThemeLabel(activeTier);
  const activeAudience = result.audience_level || document.getElementById("audience-select")?.value || "All Scouts (Ages 11–17)";
  const rawDepthMode =
    result.depth_mode ||
    result.storyboard?.depth_mode ||
    result.finops_cost_estimate?.depth_mode ||
    document.getElementById("depth-select")?.value ||
    "Deep Dive / Camp School Deck";
  const rawDepthLower = String(rawDepthMode).toLowerCase();
  const isDeepDiveDeck =
    rawDepthLower.includes("deep") ||
    rawDepthLower.includes("comprehensive") ||
    Number(result.slide_count || slides.length) > 40;
  const depthDesc = isDeepDiveDeck
    ? "Detailed Deep-Dive Teaching Deck (3–8 Slides per Requirement)"
    : "Standard Troop Meeting Deck (1–3 Slides per Requirement)";
  const resultOptionTracks = result.option_tracks || result.research_artifact?.option_tracks || [];
  const activeOptionTrackKey = String(
    result.option_track ||
      result.research_artifact?.selected_option_track ||
      document.getElementById("option-track-select")?.value ||
      "ALL"
  ).toUpperCase();
  if (typeof window.syncActiveBadgeOptionTrackSelector === "function") {
    window.syncActiveBadgeOptionTrackSelector(result.badge_name, activeOptionTrackKey, resultOptionTracks);
  }
  let optionSubtitlePrefix = "";
  if (Array.isArray(resultOptionTracks) && resultOptionTracks.length >= 2) {
    if (activeOptionTrackKey !== "ALL") {
      const matchedTrack = resultOptionTracks.find(
        (t) => String(t.option_key || "").toUpperCase() === activeOptionTrackKey
      );
      if (matchedTrack) {
        optionSubtitlePrefix = `${matchedTrack.option_title || matchedTrack.title} (Option ${matchedTrack.option_key}) • `;
      }
    } else {
      const shortNames = resultOptionTracks.map((t) => t.option_title || t.title);
      optionSubtitlePrefix =
        resultOptionTracks.length <= 2
          ? `All ${resultOptionTracks.length} Options (${shortNames.join(" / ")}) • `
          : `All ${resultOptionTracks.length} Options • `;
    }
  }
  document.getElementById("hero-badge-subtitle").textContent = `${optionSubtitlePrefix}${depthDesc} • ${activeThemeLabel} Theme • ${activeAudience}`;

  const patchImg = document.getElementById("hero-badge-patch-img");
  if (patchImg && result.patch_url) {
    patchImg.src = `${result.patch_url}${result.patch_url.includes("?") ? "&" : "?"}v=20261016c`;
    patchImg.alt = `${result.badge_name} Merit Badge Patch`;
  }

  document.getElementById("kpi-slide-count").textContent = String(result.slide_count || slides.length + 1);
  document.getElementById("kpi-subreq-count").textContent = String(reqs.length);
  const kpiPolishEl = document.getElementById("kpi-polish-tier");
  if (kpiPolishEl) kpiPolishEl.textContent = activeThemeLabel;

  // Download & Resource buttons (respect sticky .PPTX vs Google Slides export preference)
  syncDeckExportSplitButtonUi(state.preferredExportMode || "pptx");
  const pdfWbHref = `/api/v1/studiokit/fillable-workbook.pdf?badge_name=${encodeURIComponent(
    result.badge_name || "First Aid"
  )}&option_track=${encodeURIComponent(result.option_track || "ALL")}`;
  const wbBtn = document.getElementById("btn-download-workbook");
  const wbBtnTop = document.getElementById("btn-download-workbook-top");
  if (wbBtn) wbBtn.href = pdfWbHref;
  if (wbBtnTop) wbBtnTop.href = pdfWbHref;
  const wbPdfBtn1 = document.getElementById("btn-workbook-download-fillable-pdf");
  const wbPdfBtn2 = document.getElementById("btn-studiokit-download-fillable-pdf");
  if (wbPdfBtn1) wbPdfBtn1.href = pdfWbHref;
  if (wbPdfBtn2) wbPdfBtn2.href = pdfWbHref;

  const pamphletUrl = result.pamphlet_pdf_url || result.research_artifact?.pamphlet_pdf_url || "#";
  const drgUrl = result.drg_url || result.research_artifact?.drg_url || "https://www.scouting.org/skills/merit-badges/";
  const topPamphlet = document.getElementById("link-top-pamphlet");
  const topDrg = document.getElementById("link-top-drg");
  if (topPamphlet) topPamphlet.href = pamphletUrl;
  if (topDrg) topDrg.href = drgUrl;

  // 2. Render Clean Generation Summary & Auto-Collapse Trace Details so Slide Outline has full vertical room
  const progressFill = document.getElementById("trace-progress-fill");
  const progressLabel = document.getElementById("trace-progress-label");
  if (progressFill) progressFill.style.width = "100%";
  if (progressLabel) progressLabel.textContent = "Complete";
  const traceList = document.getElementById("agent-trace-list");
  const traceToggleBtn = document.getElementById("btn-toggle-trace-details");
  if (traceList) {
    const drCount = (result.deep_research_enrichment?.grounded_citations || []).length;
    const liveTroop = document.getElementById("input-troop-name")?.value || "Troop 123, My Council";
    const locLabel = resolvedLoc.region_label ? ` • ${resolvedLoc.region_label}` : "";
    traceList.innerHTML = `
      <div class="m3-trace-item">
        <div class="m3-trace-top"><span>1. Official Requirements &amp; Pamphlet</span><span class="m3-trace-meta">Loaded</span></div>
        <div class="m3-trace-desc">Extracted ${reqs.length} official requirements + ${drCount} grounded citations for ${escapeHtml(result.badge_name)} (${escapeHtml(liveTroop)}${escapeHtml(locLabel)}).</div>
      </div>
      <div class="m3-trace-item">
        <div class="m3-trace-top"><span>2. Teaching Slides &amp; Visual Theme</span><span class="m3-trace-meta">${result.slide_count} Slides (${escapeHtml(activeThemeLabel)})</span></div>
        <div class="m3-trace-desc">Applied ${escapeHtml(activeThemeLabel)} theme styling, ${escapeHtml(activeAudience)} coaching, and Hero Graphics &amp; EDGE Skill Maps.</div>
      </div>
      <div class="m3-trace-item">
        <div class="m3-trace-top"><span>3. PowerPoint, Workbook &amp; StudioKit</span><span class="m3-trace-meta">$${(finops.estimated_cost_usd || 0.14).toFixed(2)}</span></div>
        <div class="m3-trace-desc">Ready to preview and download (.pptx slide deck, .pdf fillable workbook, lesson plan &amp; parent letter).</div>
      </div>
    `;
    traceList.classList.add("hidden");
    if (traceToggleBtn) traceToggleBtn.textContent = "Details ▾";
  }

  // 3. Reveal Slide Stage and Render Storyboard Filmstrip, Requirement Quick-Jump Bar & Active Slide
  // Item 3: Creating/loading a new slide deck defaults to its recommended background
  state.coverBackdropMode = "BADGE_RECOMMENDED";
  state.deckStyle = state.deckStyle || getCurrentDeckStyleConfig();
  state.deckStyle.cover_backdrop_id = "AUTO_TEMPLATE";
  const bdSelOnNewDeck = document.getElementById("style-cover-backdrop");
  if (bdSelOnNewDeck) {
    bdSelOnNewDeck.value = "AUTO_TEMPLATE";
  }

  updateConstructionBadgeEmblem(result.badge_name);
  hideConstructionAnimationStage();
  renderFilmstrip(slides);
  renderActiveSlide(-1);

  // 4. Render Official Requirements, Click-to-Jump Cards & Blue Card Tracker
  renderTriageMatrix(result.research_artifact || {}, pamphletUrl, drgUrl);
  renderBlueCardTracker(result);

  // 5. Render Printable Workbook as styled wrapped Markdown and reset segmented button highlight to match
  const wbPreview = document.getElementById("workbook-markdown-preview");
  if (wbPreview) {
    wbPreview.innerHTML = renderMarkdownToStyledHtml(
      result.workbook_markdown || "# Counselor Workbook Generated"
    );
  }
  ["btn-workbook-view-default", "btn-workbook-open-fillable-html", "btn-workbook-open-cpp"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) {
      const isAct = id === "btn-workbook-view-default";
      el.classList.toggle("active", isAct);
      el.setAttribute("aria-selected", isAct ? "true" : "false");
    }
  });

  // 6. Render Counselor StudioKit (Lesson Plan, Parent Letter, Gear Checklist, Citations & FinOps)
  renderStudioKitAndParentLetter(result);
  renderQuartermasterGearChecklist(result);
  renderBuddyStationRotator(result);
  renderPrereqReadinessChecklist(result);
  syncPresenterViewWindow();
  if (typeof window.syncActiveBadgeStarButton === "function") {
    window.syncActiveBadgeStarButton();
  }
  if (typeof window.onWorkbenchDeckHydrated === "function" && !options.fromTourCache) {
    window.onWorkbenchDeckHydrated(result);
  }
  if (typeof syncTemplateSelectorUi === "function") {
    syncTemplateSelectorUi();
  }
  const skipDeckTemplateRpc =
    Boolean(options.fromTourCache) || Boolean(state.activeDemoTour && !state.activeDemoTour.completed);
  if (
    !skipDeckTemplateRpc &&
    state.activeTemplateId &&
    state.activeTemplateId !== "default_workbench" &&
    result.template_id !== state.activeTemplateId &&
    typeof applyTemplateToActiveDeck === "function"
  ) {
    applyTemplateToActiveDeck(state.activeTemplateId, false);
  } else if (typeof window.renderSlideTemplateOverlay === "function") {
    window.renderSlideTemplateOverlay(state.activeSlideIdx === -1, null);
  }
}

function sanitizeMiddletonTypo(str) {
  return String(str || "").replace(/Middelton/gi, "Middleton");
}

function getLiveParentLetterSubject(result, stageId = state.activeLetterStage || "stage_1_welcome_cpp") {
  const badgeName = result?.badge_name || state.currentBadge || "First Aid";
  const activeWs = (state.savedWorkspaces || []).find((w) => w.workspace_id === state.activeWorkspaceId);
  const sessLabel = sanitizeMiddletonTypo(
    document.getElementById("ws-session-label-input")?.value?.trim() || activeWs?.session_label || ""
  );
  const sessionSuffix = sessLabel ? ` (${sessLabel})` : "";
  if (stageId === "stage_2_mid_clinic_alert" || stageId === "stage2") {
    return `${badgeName} Merit Badge${sessionSuffix}: Mid-Session Progress, Homework & Make-Up Update`;
  }
  if (stageId === "stage_3_final_packet" || stageId === "stage3") {
    return `${badgeName} Merit Badge${sessionSuffix}: Final Completion, Blue Card (#34124) Sign-Off & Partial Transfer Packet`;
  }
  return `${badgeName} Merit Badge${sessionSuffix}: Pre-Class Welcome & Prerequisite Guide`;
}

function getLiveParentLetterMarkdown(result, stageId = state.activeLetterStage || "stage_1_welcome_cpp") {
  if (!result) return "# Parent Prerequisite Letter";
  const badgeName = result.badge_name || state.currentBadge || "First Aid";
  const counselorName = sanitizeMiddletonTypo(
    document.getElementById("input-counselor-name")?.value || state.counselorProfile?.counselor_name || "Eric Clayberg"
  );
  const troopName = sanitizeMiddletonTypo(
    document.getElementById("input-troop-name")?.value || state.counselorProfile?.troop_affiliation || "Troop 19, Middleton, MA"
  );
  const locationOrZip = sanitizeMiddletonTypo(
    document.getElementById("input-counselor-location")?.value || state.counselorProfile?.location_or_zip || ""
  );
  const email = document.getElementById("input-counselor-email")?.value || state.counselorProfile?.email_address || "counselor@troop19.org";
  const phone = document.getElementById("input-counselor-phone")?.value || state.counselorProfile?.phone_number || "(000) 555-1234";
  const storedCounselor = sanitizeMiddletonTypo(result.counselor_info?.counselor_name || "Scoutmaster Bob");
  const storedTroop = sanitizeMiddletonTypo(result.counselor_info?.troop_affiliation || "Troop 123, My Council");
  const storedEmail = result.counselor_info?.email_address || "counselor@troop123.org";
  const storedPhone = result.counselor_info?.phone_number || "(000) 555-1234";

  const activeWs = (state.savedWorkspaces || []).find((w) => w.workspace_id === state.activeWorkspaceId);
  const sessLabel = sanitizeMiddletonTypo(
    document.getElementById("ws-session-label-input")?.value?.trim() || activeWs?.session_label || "Multi-Unit Merit Badge Session"
  );
  const classTime =
    document.getElementById("ws-class-time-input")?.value?.trim() ||
    activeWs?.class_start_time ||
    document.getElementById("input-logistics-time")?.value?.trim() ||
    "8:30 AM – 10:00 AM";
  const roomLoc = sanitizeMiddletonTypo(
    document.getElementById("ws-room-location-input")?.value?.trim() ||
      activeWs?.room_location ||
      document.getElementById("input-logistics-room")?.value?.trim() ||
      "Main Classroom / Outdoor Station"
  );
  const sessDates =
    document.getElementById("ws-session-dates-input")?.value?.trim() ||
    activeWs?.session_dates ||
    document.getElementById("input-logistics-sessions")?.value?.trim() ||
    "4x 75-Min Sessions (S1–S4) + Make-Up Block";

  const applySubstitutionsAndCleanHeader = (rawMd, defaultSalutation) => {
    let text = sanitizeMiddletonTypo(rawMd)
      .split(storedCounselor).join(counselorName)
      .split("Scoutmaster Bob").join(counselorName)
      .split(storedTroop).join(troopName)
      .split("Troop 123, My Council").join(troopName)
      .split(storedEmail).join(email)
      .split("counselor@troop123.org").join(email)
      .split(storedPhone).join(phone)
      .split("(000) 555-1234").join(phone);
    // Strip any unit parenthetical from top # Title or Dear ... Salutation so multi-troop classes are never mislabeled
    text = text.replace(/^(#\s+[^\n(]+?)\s*\((?:Troop|Pack|Crew|Unit)[^)\n]*\)\s*$/gim, "$1");
    text = text.replace(/^Dear\s+[^\n]*?\((?:Troop|Pack|Crew|Unit)[^)\n]*\)[^\n]*$/gim, defaultSalutation);
    text = text.replace(/^Dear\s+(?:Troop|Pack|Crew)\s+\d+[^,\n]*,\s*$/gim, defaultSalutation);
    return text;
  };

  const normalizedStage =
    stageId === "stage2" || stageId === "stage_2_mid_clinic_alert"
      ? "stage_2_mid_clinic_alert"
      : stageId === "stage3" || stageId === "stage_3_final_packet"
      ? "stage_3_final_packet"
      : "stage_1_welcome_cpp";

  const salutationMap = {
    stage_1_welcome_cpp: `Dear ${badgeName} Merit Badge Scouts, Parents/Guardians, and Unit Leaders,`,
    stage_2_mid_clinic_alert: `Dear ${badgeName} Merit Badge Scouts, Parents/Guardians, and Unit Advancement Chairs,`,
    stage_3_final_packet: `Dear ${badgeName} Merit Badge Scouts, Parents/Guardians, Scoutmasters, and Advancement Chairs,`,
  };
  const targetSalutation = salutationMap[normalizedStage];

  // Check if backend already provided distinct stages dictionary
  const backendStages = result.prerequisite_parent_letter?.stages || {};
  if (backendStages[normalizedStage] && typeof backendStages[normalizedStage] === "string") {
    return applySubstitutionsAndCleanHeader(backendStages[normalizedStage], targetSalutation);
  }
  const yptPack = state.activeYptPack || {};
  if (normalizedStage === "stage_2_mid_clinic_alert" && yptPack.stage_2_midpoint_homework_markdown) {
    return applySubstitutionsAndCleanHeader(yptPack.stage_2_midpoint_homework_markdown, targetSalutation);
  }
  if (normalizedStage === "stage_3_final_packet" && yptPack.stage_3_post_class_bluecard_markdown) {
    return applySubstitutionsAndCleanHeader(yptPack.stage_3_post_class_bluecard_markdown, targetSalutation);
  }
  if (normalizedStage === "stage_1_welcome_cpp" && result.prerequisite_parent_letter?.letter_markdown) {
    return applySubstitutionsAndCleanHeader(result.prerequisite_parent_letter.letter_markdown, targetSalutation);
  }

  // Synthesize rich, stage-specific multi-troop Markdown letters for Stage 1, Stage 2, and Stage 3
  const reqs = Array.isArray(result.research_artifact?.requirements) ? result.research_artifact.requirements : [];
  const prereqReqs = reqs.filter((r) => r.execution_mode === "PREREQUISITE_CAMPOUT_HOME");
  const stationReqs = reqs.filter((r) => r.execution_mode === "HANDS_ON_SKILL_STATION");
  const inClassReqs = reqs.filter((r) => r.execution_mode !== "PREREQUISITE_CAMPOUT_HOME");
  const roster = typeof loadBadgeBlueCardRoster === "function" ? loadBadgeBlueCardRoster(badgeName) : { scouts: [] };
  const scoutsList = Array.isArray(roster?.scouts) ? roster.scouts : [];
  const totalReqCount = Math.max(1, reqs.length);
  const completedScouts = scoutsList.filter((s) => (s.completedReqs || []).length >= totalReqCount);
  const partialScouts = scoutsList.filter((s) => (s.completedReqs || []).length < totalReqCount);
  const unitFooterLine = locationOrZip && !troopName.toLowerCase().includes(locationOrZip.toLowerCase())
    ? `${troopName} (${locationOrZip})`
    : troopName;

  if (normalizedStage === "stage_2_mid_clinic_alert") {
    const hwLines = (prereqReqs.length > 0 ? prereqReqs : reqs.slice(0, 3))
      .map((r) => `- **Requirement ${r.req_number}:** ${r.req_text}`)
      .join("\n");
    const stationLines = (stationReqs.length > 0 ? stationReqs : inClassReqs.slice(0, 3))
      .map((r) => `- **Requirement ${r.req_number} (Hands-On Station):** ${r.req_text}`)
      .join("\n");
    return [
      `# ${badgeName} Merit Badge — Stage 2: Mid-Session Progress, Homework & Make-Up Update`,
      ``,
      `**Session / Period:** ${sessLabel} • **Time:** ${classTime} • **Room / Venue:** ${roomLoc}`,
      `**Schedule:** ${sessDates}`,
      ``,
      targetSalutation,
      ``,
      `Thank you for our Scouts' enthusiasm and active participation in the first half of our **${badgeName} Merit Badge** sessions! Because this class serves Scouts from multiple units, please review the mid-session progress checkpoints, between-session workbook assignments, and upcoming make-up station schedule below.`,
      ``,
      `### 📋 1. Between-Session Workbook & Home Prerequisite Check-In`,
      `Before our next class meeting, every Scout should verify that their **${badgeName} Fillable Merit Badge Workbook** is up to date and bring written notes, photos, or signed verification for the following requirements:`,
      hwLines || `- Complete all assigned between-session tables in your ${badgeName} Merit Badge Workbook.`,
      ``,
      `### 🛠️ 2. Upcoming Hands-On EDGE Skill Stations & Make-Up Block`,
      `During our next sessions (plus our scheduled **Make-Up Block** for any Scout who missed S1 or S2), we will run practical hands-on demonstrations for:`,
      stationLines || `- Practical hands-on skill demonstrations and individual counselor verification.`,
      ``,
      `### 🛡️ 3. Scouting America Youth Protection (YPT) & Two-Deep Digital Communication`,
      `Per **Scouting America Youth Protection guidelines (18 U.S.C. § 707)**, Scouts must **always copy (CC) a parent, legal guardian, or second registered adult leader** on any email, text, or digital workbook submission sent to the Merit Badge Counselor.`,
      ``,
      `Yours in Scouting,`,
      ``,
      `**${counselorName}**`,
      `Registered Merit Badge Counselor — ${badgeName} Merit Badge`,
      `Counselor Unit Affiliation: ${unitFooterLine}`,
      `Email: ${email} • Phone: ${phone}`,
    ].join("\n");
  }

  if (normalizedStage === "stage_3_final_packet") {
    const prereqNums = prereqReqs.map((r) => `Req ${r.req_number}`).join(", ") || "Home / Campout Prerequisites";
    return [
      `# ${badgeName} Merit Badge — Stage 3: Final Completion, Blue Card (#34124) Sign-Off & Partial Transfer Packet`,
      ``,
      `**Session / Period:** ${sessLabel} • **Venue:** ${roomLoc} • **Schedule Completed:** ${sessDates}`,
      ``,
      targetSalutation,
      ``,
      `Congratulations to all Scouts who participated in our **${badgeName} Merit Badge** class! This final wrap-up packet summarizes **Application for Merit Badge (Blue Card #34124)** completions, **Scoutbook Plus CSV advancement import instructions** for Unit Advancement Chairs, and step-by-step guidance for finishing any remaining **Partial Blue Cards**.`,
      ``,
      `### 🪪 1. Final Class Roster & Blue Card (#34124) Summary`,
      `- **Enrolled Scouts on Roster:** ${scoutsList.length} Scout(s) across participating units`,
      `- **100% Complete Blue Cards Signed Off:** ${completedScouts.length} Scout(s) (${completedScouts.map((s) => `${s.name} [${s.troop || "Unit"}]`).join(", ") || "See attached unit CSV packet"})`,
      `- **Partial Blue Cards Issued for Home/Troop Completion:** ${partialScouts.length} Scout(s) (${partialScouts.map((s) => `${s.name} [${s.troop || "Unit"}]`).join(", ") || "None — all in-class requirements verified"})`,
      ``,
      `### 📥 2. Unit Advancement Chairs: Scoutbook Plus CSV Import & 3-Panel Blue Cards`,
      `1. **Scoutbook Plus Import:** Unit Advancement Chairs can import the attached \`${badgeName.replace(/\s+/g, "_")}_Scoutbook_BlueCard_Export.csv\` directly into **Scoutbook Plus (Internet Advancement 2.0)** to credit all completed requirements.`,
      `2. **3-Panel Blue Card (#34124) Distribution:** Each Scout's signed 3-panel Blue Card PDF includes the **Applicant's Record**, **Counselor's Record**, and **Unit Leader's Record** with individualized requirement initials.`,
      ``,
      `### 🧭 3. How to Finish a Partial ${badgeName} Merit Badge`,
      `Scouts holding a **Partial Blue Card** have completed their in-class discussions and skill stations and only need to finish their remaining home/troop requirements (${prereqNums}):`,
      `- Complete the remaining logs, campout tasks, or time-tracked charts in your **${badgeName} Merit Badge Workbook**.`,
      `- Reply to this thread (**always CC'ing a parent/guardian or second registered adult leader** per Scouting America YPT Two-Deep rules) with photos/scans of your completed workbook pages, or present them to a registered **${badgeName} Merit Badge Counselor** in your home troop for final sign-off.`,
      ``,
      `Thank you for supporting your Scouts on the trail to Eagle!`,
      ``,
      `Yours in Scouting,`,
      ``,
      `**${counselorName}**`,
      `Registered Merit Badge Counselor — ${badgeName} Merit Badge`,
      `Counselor Unit Affiliation: ${unitFooterLine}`,
      `Email: ${email} • Phone: ${phone}`,
    ].join("\n");
  }

  // Default Stage 1: Pre-Class Welcome & Prerequisite Guide
  const prereqBullets =
    prereqReqs.length > 0
      ? prereqReqs.map((r) => `- **Requirement ${r.req_number}:** ${r.req_text}`).join("\n")
      : `- Review the official **${badgeName} Merit Badge Pamphlet** and bring your **${badgeName} Fillable Workbook** to Session 1.`;
  return [
    `# ${badgeName} Merit Badge — Stage 1: Pre-Class Welcome & Prerequisite Guide`,
    ``,
    `**Session / Period:** ${sessLabel} • **Time:** ${classTime} • **Room / Venue:** ${roomLoc}`,
    `**Schedule:** ${sessDates}`,
    ``,
    targetSalutation,
    ``,
    `Welcome to our upcoming **${badgeName} Merit Badge** class! We are excited to welcome Scouts from all participating troops and districts. Please review the pre-class preparation checklist, required gear, and **Scouting America Youth Protection (YPT)** communication guidelines below before Session 1.`,
    ``,
    `### 🏠 1. Pre-Class Prerequisites & At-Home Preparation`,
    `The following requirements involve multi-week tracking, home inspections, or campout preparation and should be started **before Session 1**:`,
    prereqBullets,
    ``,
    `### 🎒 2. What Every Scout Should Bring to Class`,
    `- **${badgeName} Fillable Merit Badge Workbook** (printed or digital tablet copy) & pen/pencil`,
    `- **Signed Blue Card (#34124)** from your Unit Leader (or unit registration confirmation in Scoutbook Plus)`,
    `- **Official ${badgeName} Merit Badge Pamphlet** (physical or digital edition) and personal water bottle`,
    ``,
    `### 🛡️ 3. Mandatory Scouting America Youth Protection (YPT) Two-Deep Rule`,
    `In strict compliance with **Scouting America Youth Protection policies**, there is **no one-on-one digital contact** between youth and adults. Scouts must **always copy (CC) a parent, legal guardian, or second registered adult leader** on every email, text message, or workbook submission.`,
    ``,
    `Yours in Scouting,`,
    ``,
    `**${counselorName}**`,
    `Registered Merit Badge Counselor — ${badgeName} Merit Badge`,
    `Counselor Unit Affiliation: ${unitFooterLine}`,
    `Email: ${email} • Phone: ${phone}`,
  ].join("\n");
}

function renderStudioKitAndParentLetter(result) {
  if (!result) return;
  const finops = result.finops_cost_estimate || {};
  const troopName = sanitizeMiddletonTypo(document.getElementById("input-troop-name")?.value || "Troop 123, My Council");
  syncCompanionBadgePillBar(result);

  const agendaPreview = document.getElementById("studiokit-agenda-preview");
  if (agendaPreview) {
    agendaPreview.innerHTML = renderMarkdownToStyledHtml(
      result.session_agenda?.agenda_markdown || "# Session Lesson Plan"
    );
  }

  // Dynamically update Prerequisite Parent Letter with live Counselor inputs and active stage (Stage 1/2/3)
  const activeStage = state.activeLetterStage || "stage_1_welcome_cpp";
  const letterMd = getLiveParentLetterMarkdown(result, activeStage);
  const letterPreview = document.getElementById("studiokit-letter-preview");
  if (letterPreview) {
    letterPreview.innerHTML = renderMarkdownToStyledHtml(letterMd);
  }
  const yptSubjIn = document.getElementById("ypt-email-subject-input");
  if (yptSubjIn) {
    yptSubjIn.value = getLiveParentLetterSubject(result, activeStage);
  }
  const yptBodyIn = document.getElementById("ypt-email-body-textarea");
  if (yptBodyIn) {
    yptBodyIn.value = letterMd;
  }
  document.querySelectorAll("[data-letter-stage]").forEach((b) => {
    b.classList.toggle("active", b.getAttribute("data-letter-stage") === activeStage);
  });

  const citList = document.getElementById("studiokit-citations-list");
  if (citList) {
    const storedTroop = result.deep_research_enrichment?.troop_affiliation || "Troop 123, My Council";
    const resolvedLoc = result.deep_research_enrichment?.resolved_location || {};
    const citations = result.deep_research_enrichment?.grounded_citations || [];
    if (citations.length === 0) {
      citList.innerHTML = `<div class="m3-req-node-card">Local Regional Grounding was disabled for this run. Enable the checkbox in the left sidebar to resolve local NOAA Weather Forecast Office &amp; regional field study sites for <strong>${escapeHtml(troopName)}</strong>.</div>`;
    } else {
      const senLine =
        resolvedLoc.senator_1 && resolvedLoc.senator_2
          ? `<br/><strong>Current U.S. Senators (${escapeHtml(resolvedLoc.state_code || "MA")}):</strong> ${escapeHtml(resolvedLoc.senator_1)} &amp; ${escapeHtml(resolvedLoc.senator_2)} <span class="m3-chip m3-chip-secondary" style="font-size:0.65rem; padding:1px 6px; margin-left:4px;">🔄 24h Daily + On-Demand Gemini Verified</span>`
          : "";
      const civicLine = resolvedLoc.state_capitol
        ? `<br/><strong>State Capitol &amp; Landmarks:</strong> ${escapeHtml(resolvedLoc.state_capitol)} &bull; ${escapeHtml(resolvedLoc.national_landmarks || "")}`
        : "";
      const locHeader = resolvedLoc.region_label
        ? `<div class="m3-req-node-card" style="background:var(--md-sys-color-sky-surface); border-left:5px solid var(--md-sys-color-primary);">
             <div style="font-weight:800; color:var(--md-sys-color-primary);">📍 Resolved Local Region: ${escapeHtml(resolvedLoc.region_label)} (${escapeHtml(resolvedLoc.nws_office || "NOAA NWS")})</div>
             <div style="font-size:0.80rem; color:var(--md-sys-color-on-surface); margin-top:4px;"><strong>Regional Hazards:</strong> ${escapeHtml(resolvedLoc.terrain_and_hazards || "")}<br/><strong>Field Study Sites:</strong> ${escapeHtml(resolvedLoc.field_site_examples || "")}${civicLine}${senLine}</div>
           </div>`
        : "";
      citList.innerHTML =
        locHeader +
        citations
          .map((c) => {
            const liveFact = String(c.local_grounding_callout || c.supplemental_fact || "")
              .split(storedTroop).join(troopName)
              .split("Troop 123, My Council").join(troopName);
            const catPill = c.grounding_category
              ? `<span class="m3-chip m3-chip-secondary" style="font-size:0.65rem; padding:2px 6px; margin-left:4px;">${escapeHtml(String(c.grounding_category).replace(/_/g, " "))}</span>`
              : "";
            const localBadge = c.requires_local_lookup
              ? `<span class="m3-chip m3-chip-gold" style="font-size:0.65rem; padding:2px 6px; margin-left:4px;">📍 Local Slide Callout</span>`
              : "";
            return `
              <div class="m3-req-node-card">
                <div style="font-weight:700; color:var(--md-sys-color-primary); display:flex; align-items:center; flex-wrap:wrap; gap:4px;">
                  <a href="${escapeHtml(c.source_url)}" target="_blank" rel="noopener noreferrer" style="color:var(--md-sys-color-primary); text-decoration:none;">${escapeHtml(c.source_title)}</a>
                  <span class="m3-chip m3-chip-primary" style="font-size:0.68rem; padding:2px 6px;">${escapeHtml(c.authority_domain || "")} &bull; Req ${escapeHtml(c.req_number || "")}</span>
                  ${catPill}${localBadge}
                </div>
                <div style="font-size:0.80rem; color:var(--md-sys-color-on-surface-variant); margin-top:4px;">${escapeHtml(liveFact)}</div>
              </div>
            `;
          })
          .join("");
    }
  }

  const finopsPreview = document.getElementById("studiokit-finops-preview");
  if (finopsPreview) {
    finopsPreview.innerHTML = renderFinopsTableHtml(finops);
  }
  const adminFinopsPreview = document.getElementById("admin-finops-ledger-preview");
  if (adminFinopsPreview) {
    adminFinopsPreview.innerHTML = renderFinopsTableHtml(finops);
  }
  if (typeof renderWorkflowTraceAndFinopsCard === "function") {
    renderWorkflowTraceAndFinopsCard(result);
  }

  const schemaChip = document.getElementById("feedback-schema-version-chip");
  if (schemaChip) {
    const schemaVer = result.schema_version || "1.2.0";
    schemaChip.textContent = `Schema v${schemaVer} • HITL Flywheel`;
  }
  const fbBanner = document.getElementById("feedback-status-banner");
  if (fbBanner) {
    fbBanner.classList.add("hidden");
    fbBanner.innerHTML = "";
  }
}

function scrollActiveFilmstripThumbIntoView(alignToTop = true) {
  const list = document.getElementById("slide-filmstrip-list");
  if (!list) return;
  const activeThumb = list.querySelector(".m3-slide-thumb.active");
  if (!activeThumb) return;
  const listRect = list.getBoundingClientRect();
  const thumbRect = activeThumb.getBoundingClientRect();
  const offsetInContainer = thumbRect.top - listRect.top;
  const scrollBehavior = state.activeDemoTour ? "auto" : "smooth";
  if (alignToTop) {
    list.scrollTo({
      top: Math.max(0, list.scrollTop + offsetInContainer - 8),
      behavior: scrollBehavior,
    });
  } else if (offsetInContainer < 4 || thumbRect.bottom > listRect.bottom - 4) {
    const targetTop =
      offsetInContainer < 4
        ? Math.max(0, list.scrollTop + offsetInContainer - 8)
        : Math.max(0, list.scrollTop + (thumbRect.bottom - listRect.bottom) + 8);
    list.scrollTo({
      top: targetTop,
      behavior: scrollBehavior,
    });
  }
}

function renderRequirementJumpBar(slides) {
  const bar = document.getElementById("req-quick-jump-bar");
  const menuEl = document.getElementById("req-jump-dropdown-menu");
  if (bar) {
    bar.innerHTML = `<span class="m3-req-jump-label">Jump to:</span>`;
  }

  const activeReq =
    state.activeSlideIdx === -1
      ? "__COVER__"
      : String(slides[state.activeSlideIdx]?.req_number || "");

  const jumpToTarget = (targetSlideIdx) => {
    hideConstructionAnimationStage();
    state.activeSlideIdx = targetSlideIdx;
    renderFilmstrip(slides);
    renderActiveSlide(targetSlideIdx);
    scrollActiveFilmstripThumbIntoView(true);
    menuEl?.classList.add("hidden");
    document.getElementById("btn-stage-req-jump-toggle")?.setAttribute("aria-expanded", "false");
  };

  const addJumpPill = (label, targetSlideIdx, isActive) => {
    if (!bar) return;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = `m3-req-jump-pill${isActive ? " active" : ""}`;
    btn.textContent = label;
    btn.addEventListener("click", () => jumpToTarget(targetSlideIdx));
    bar.appendChild(btn);
  };

  addJumpPill("Cover", -1, activeReq === "__COVER__");

  const seenReqs = new Map();
  const reqCounts = new Map();
  const reqSlideIndices = new Map();
  slides.forEach((s, idx) => {
    const reqKey = String(s.req_number || "").trim();
    if (!reqKey) return;
    reqCounts.set(reqKey, (reqCounts.get(reqKey) || 0) + 1);
    if (!seenReqs.has(reqKey)) {
      seenReqs.set(reqKey, idx);
    }
    if (!reqSlideIndices.has(reqKey)) {
      reqSlideIndices.set(reqKey, []);
    }
    reqSlideIndices.get(reqKey).push(idx);
  });

  seenReqs.forEach((slideIdx, reqKey) => {
    const pillLabel =
      reqKey === "Overview" || reqKey === "Sources" ? reqKey : `Req ${reqKey}`;
    addJumpPill(pillLabel, slideIdx, activeReq === reqKey);
  });

  if (menuEl) {
    const items = [
      {
        label: "Cover Slide",
        sub: "Slide 1",
        targetIdx: -1,
        isActive: activeReq === "__COVER__",
        subChips: [],
      },
    ];
    seenReqs.forEach((slideIdx, reqKey) => {
      const pillLabel =
        reqKey === "Overview" || reqKey === "Sources" ? reqKey : `Req ${reqKey}`;
      const count = reqCounts.get(reqKey) || 1;
      const startSlideNum = slideIdx + 2;
      const sub =
        count > 1
          ? `Slides ${startSlideNum}–${startSlideNum + count - 1}`
          : `Slide ${startSlideNum}`;
      const groupIndices = reqSlideIndices.get(reqKey) || [slideIdx];
      const subChips =
        groupIndices.length > 1
          ? groupIndices.map((sIdx, subPos) => {
              const sl = slides[sIdx] || {};
              const isQuizSl =
                sl.archetype === "SOCRATIC_CHECKPOINT_QUIZ" || /quiz|checkpoint|scenario/i.test(sl.title || "");
              const mSub = String(sl.title || "").match(/\b([0-9]+[a-z])\b/i);
              const chipLbl = isQuizSl
                ? "Quiz"
                : mSub
                ? mSub[1]
                : `${reqKey}${String.fromCharCode(97 + subPos)}`;
              return {
                label: chipLbl,
                slideNum: sIdx + 2,
                targetIdx: sIdx,
                isActive: state.activeSlideIdx === sIdx,
              };
            })
          : [];
      items.push({
        label: pillLabel,
        sub,
        targetIdx: slideIdx,
        isActive: activeReq === reqKey,
        subChips,
      });
    });

    menuEl.innerHTML = `
      <div class="m3-stage-tools-section-kicker" style="padding:4px 10px 6px; border-bottom:1px solid #E2E8F0; margin-bottom:6px;">
        Jump to Section or Requirement (${items.length})
      </div>
      <div class="m3-req-jump-menu-grid">
        ${items
          .map(
            (it) => `
          <div class="m3-req-jump-menu-item-wrap" style="display:flex; flex-direction:column; gap:3px;">
            <button
              type="button"
              class="m3-req-jump-menu-item ${it.isActive ? "active" : ""}"
              data-req-jump-idx="${it.targetIdx}"
              role="menuitem"
            >
              <span class="m3-req-jump-item-title">${escapeHtml(it.label)}${it.isActive ? " ✓" : ""}</span>
              <span class="m3-req-jump-item-sub">${escapeHtml(it.sub)}</span>
            </button>
            ${
              it.subChips && it.subChips.length > 1
                ? `<div class="m3-req-jump-subchips-row" style="display:flex; flex-wrap:wrap; gap:3px; padding:0 4px 3px;">
                    ${it.subChips
                      .map(
                        (sc) =>
                          `<button type="button" class="m3-req-jump-subchip ${sc.isActive ? "active" : ""}" data-req-jump-idx="${sc.targetIdx}" title="Jump to Slide ${sc.slideNum} (${escapeHtml(sc.label)})">${escapeHtml(sc.label)}</button>`
                      )
                      .join("")}
                  </div>`
                : ""
            }
          </div>
        `
          )
          .join("")}
      </div>
    `;
    menuEl.querySelectorAll("[data-req-jump-idx]").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const idx = parseInt(btn.getAttribute("data-req-jump-idx") || "-1", 10);
        jumpToTarget(idx);
      });
    });
  }
}

function renderFilmstrip(slides) {
  const list = document.getElementById("slide-filmstrip-list");
  if (!list) return;
  const savedScrollTop = list.scrollTop;
  list.classList.remove("hidden");
  list.innerHTML = "";
  renderRequirementJumpBar(slides);

  const q = (state.filmstripQuery || "").trim().toLowerCase();
  const quizOnly = Boolean(state.filterQuizSlidesOnly);

  // Sync Tools dropdown Hide/Unhide button text with active slide state
  const activeSlideForTools = state.activeSlideIdx >= 0 ? slides[state.activeSlideIdx] : null;
  const hideSlideMenuBtn = document.getElementById("btn-toggle-hide-slide");
  if (hideSlideMenuBtn) {
    hideSlideMenuBtn.textContent = activeSlideForTools?.hidden ? "👁️ Unhide Slide" : "👁️ Hide Slide";
  }

  // Slide 1: Cover Slide item
  if (!quizOnly && (!q || "slide 1 cover title badge".includes(q) || (state.currentResult?.badge_name || "").toLowerCase().includes(q))) {
    const coverThumb = document.createElement("div");
    const isCoverActive = state.activeSlideIdx === -1;
    coverThumb.className = `m3-slide-thumb ${isCoverActive ? "active" : ""}`;
    const coverImgUrl = state.currentResult?.pamphlet_cover_url || state.currentResult?.badge_emblem_url || "";
    const coverCustomizerHtml = isCoverActive
      ? `
        <div class="m3-thumb-bottom-bar" style="margin-top:5px;">
          <span class="m3-thumb-arch-pill">🪪 Title Slide</span>
          <div class="m3-thumb-customizer-cluster" role="group" aria-label="Slide Deck Customizer Controls">
            <button type="button" class="m3-thumb-micro-pill m3-thumb-micro-pill-add" data-thumb-custom-act="insert" title="Insert a custom local camp or troop slide after this slide (updates .PPTX)" aria-label="Insert custom slide"><span class="m3-thumb-plus-glyph">+</span></button>
          </div>
        </div>
      `
      : "";
    coverThumb.innerHTML = `
      <div class="m3-thumb-top">
        <span>Slide 1 &bull; Cover</span>
        <span class="m3-thumb-archetype">Title &amp; Badge</span>
      </div>
      <div class="m3-thumb-row-flex">
        <div class="m3-thumb-title" style="flex:1; min-width:0;">${escapeHtml(state.currentResult?.badge_name || "")} Merit Badge</div>
        ${coverImgUrl ? `<img class="m3-thumb-mini-img" src="${escapeHtml(coverImgUrl)}" alt="Cover" loading="lazy" />` : ""}
      </div>
      ${coverCustomizerHtml}
    `;
    coverThumb.querySelectorAll("[data-thumb-custom-act]").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const act = btn.getAttribute("data-thumb-custom-act");
        if (act === "insert") {
          document.getElementById("btn-insert-custom-slide")?.click();
        }
      });
    });
    coverThumb.addEventListener("click", () => {
      hideConstructionAnimationStage();
      state.activeSlideIdx = -1;
      renderFilmstrip(slides);
      renderActiveSlide(-1);
    });
    list.appendChild(coverThumb);
  }

  slides.forEach((s, idx) => {
    const arch = String(s.archetype || "");
    const isQuiz = arch === "SOCRATIC_CHECKPOINT_QUIZ" || /quiz|checkpoint|scenario/i.test(s.title || "");
    if (quizOnly && !isQuiz) return;

    const hasReqDef = Boolean(s.verbatim_requirement_text && s.verbatim_requirement_text.trim());
    const hasImg = Boolean(s.diagram_url);
    const hasHero = Boolean(s.ai_hero_image_path);
    const isHidden = Boolean(s.hidden);
    const isCustom = Boolean(s.is_custom_slide);
    const kindLabel =
      s.req_number === "Overview" || s.req_number === "Sources"
        ? s.req_number
        : isCustom
        ? "Custom"
        : isQuiz
        ? "Patrol Quiz"
        : hasReqDef
        ? "Req Intro"
        : hasImg
        ? "Diagram"
        : "Teaching";
    if (q) {
      const haystack = [
        `slide ${idx + 2}`,
        `req ${s.req_number || ""}`,
        kindLabel,
        arch,
        s.title || "",
        (s.bullet_points || []).join(" "),
        s.verbatim_requirement_text || "",
        s.visual_caption || "",
      ]
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) return;
    }

    let archBadgeText = "";
    if (isHidden) archBadgeText = "👁️‍🗨️ Hidden";
    else if (isCustom) archBadgeText = "📍 Custom";
    else if (isQuiz) archBadgeText = "❓ Quiz";
    else if (arch === "WORKED_EXAMPLE_TEMPLATE") archBadgeText = "📋 Worked Example";
    else if (s.safety_warning) archBadgeText = "⚠️ Safety";
    else if (hasImg) archBadgeText = "📐 Diagram";

    const choices = typeof getSlideSpecificImageChoices === "function" ? getSlideSpecificImageChoices(s) : [];
    const activeChoicePos = choices.length >= 2
      ? Math.max(1, choices.findIndex((c) => (c.image_path && c.image_path === s.diagram_path) || (c.image_url && c.image_url === s.diagram_url)) + 1)
      : 1;
    const choicePillHtml = choices.length >= 2
      ? `<span class="m3-thumb-imgcount-pill" title="${choices.length} curated visuals available for this slide">🖼️ ${activeChoicePos}/${choices.length}</span>`
      : "";

    const isActiveSlide = idx === state.activeSlideIdx;
    const thumb = document.createElement("div");
    thumb.className = `m3-slide-thumb ${isActiveSlide ? "active" : ""} ${isHidden ? "hidden-slide" : ""}`;
    const badgeFlags = `${hasHero ? " ✨" : ""}`;
    const deleteCustomBtnHtml = isCustom
      ? `<button
          type="button"
          class="m3-thumb-micro-pill m3-thumb-micro-pill-delete"
          data-thumb-custom-act="delete_custom"
          title="Delete this custom slide from the deck (updates .PPTX)"
          aria-label="Delete custom slide"
          style="color:#DC2626;"
        >🗑️</button>`
      : "";
    const activeCustomizerClusterHtml = isActiveSlide
      ? `
        <div class="m3-thumb-customizer-cluster" role="group" aria-label="Active Slide Customizer Actions">
          <button
            type="button"
            class="m3-thumb-micro-pill m3-thumb-micro-pill-add"
            data-thumb-custom-act="insert"
            title="Insert a custom local camp or troop slide after this slide (updates .PPTX)"
            aria-label="Insert custom slide"
          ><span class="m3-thumb-plus-glyph">+</span></button>
          <button
            type="button"
            class="m3-thumb-micro-pill ${isHidden ? "is-toggled" : ""}"
            data-thumb-custom-act="toggle_hide"
            title="${isHidden ? "Unhide this slide (restore to presentation and .PPTX export)" : "Hide or skip this slide during presentation and .PPTX export"}"
            aria-label="${isHidden ? "Unhide slide" : "Hide slide"}"
          >👁️</button>
          ${deleteCustomBtnHtml}
          <button
            type="button"
            class="m3-thumb-micro-pill"
            data-thumb-custom-act="move_up"
            title="Move active slide earlier in deck (↑)"
            aria-label="Move slide earlier"
            ${idx <= 0 ? "disabled" : ""}
          >↑</button>
          <button
            type="button"
            class="m3-thumb-micro-pill"
            data-thumb-custom-act="move_down"
            title="Move active slide later in deck (↓)"
            aria-label="Move slide later"
            ${idx >= slides.length - 1 ? "disabled" : ""}
          >↓</button>
        </div>
      `
      : "";
    thumb.innerHTML = `
      <div class="m3-thumb-top">
        <span>Slide ${idx + 2} &bull; ${s.req_number === "Overview" || s.req_number === "Sources" ? escapeHtml(s.req_number) : "Req " + escapeHtml(s.req_number || "")}</span>
        <span class="m3-thumb-archetype">${escapeHtml(kindLabel)}${badgeFlags}</span>
      </div>
      <div class="m3-thumb-row-flex">
        <div style="flex:1; min-width:0;">
          <div class="m3-thumb-title">${escapeHtml(s.title || "")}</div>
          ${
            !isActiveSlide
              ? `
                <div class="m3-thumb-badges-row">
                  ${archBadgeText ? `<span class="m3-thumb-arch-pill">${archBadgeText}</span>` : ""}
                  ${choicePillHtml}
                </div>
              `
              : ""
          }
        </div>
        ${hasImg ? `<img class="m3-thumb-mini-img" src="${escapeHtml(s.diagram_url)}" alt="" loading="lazy" />` : ""}
      </div>
      ${
        isActiveSlide
          ? `
            <div class="m3-thumb-bottom-bar">
              <div class="m3-thumb-badges-row" style="margin-top:0;">
                ${archBadgeText ? `<span class="m3-thumb-arch-pill">${archBadgeText}</span>` : ""}
                ${choicePillHtml}
              </div>
              ${activeCustomizerClusterHtml}
            </div>
          `
          : ""
      }
    `;
    thumb.querySelectorAll("[data-thumb-custom-act]").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const act = btn.getAttribute("data-thumb-custom-act");
        if (act === "insert") {
          document.getElementById("btn-insert-custom-slide")?.click();
        } else if (act === "toggle_hide") {
          customizeActiveSlideDeck("toggle_hide");
        } else if (act === "delete_custom") {
          customizeActiveSlideDeck("delete_custom");
        } else if (act === "move_up") {
          customizeActiveSlideDeck("move_up");
        } else if (act === "move_down") {
          customizeActiveSlideDeck("move_down");
        }
      });
    });
    thumb.addEventListener("click", () => {
      hideConstructionAnimationStage();
      state.activeSlideIdx = idx;
      renderFilmstrip(slides);
      renderActiveSlide(idx);
    });
    list.appendChild(thumb);
  });
  list.scrollTop = savedScrollTop;
}

function getHexLuminance(hexColor) {
  const clean = String(hexColor || "").trim().replace(/^#/, "");
  const full = clean.length === 3 ? clean.split("").map((c) => c + c).join("") : clean.padEnd(6, "0").slice(0, 6);
  const r8 = parseInt(full.slice(0, 2), 16);
  const g8 = parseInt(full.slice(2, 4), 16);
  const b8 = parseInt(full.slice(4, 6), 16);
  if (Number.isNaN(r8) || Number.isNaN(g8) || Number.isNaN(b8)) return 0;
  const toLinear = (c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * toLinear(r8) + 0.7152 * toLinear(g8) + 0.0722 * toLinear(b8);
}
window.getHexLuminance = getHexLuminance;

function getContrastPillTextHex(bgHex) {
  return getHexLuminance(bgHex) > 0.18 ? "#0F172A" : "#FFFFFF";
}
window.getContrastPillTextHex = getContrastPillTextHex;

function resolveSlidePaletteTokens(slide, deckTier) {
  const tier = String(slide?.beautification_tier || deckTier || "BEAUTIFIED").toUpperCase();
  if (tier === "STANDARD") {
    return {
      tier: "STANDARD",
      isBeautified: false,
      isStudio: false,
      stageBg: "#FFFFFF",
      textFg: "#0F172A",
      subTextFg: "#334155",
      primaryHex: "#003F87",
      accentHex: "#CBD5E1",
      cardBg: "#F1F5F9",
      badgeBg: "#E2E8F0",
      badgeFg: "#334155",
      stageBorder: "2px solid #CBD5E1",
      headerBg: "transparent",
      footerColor: "#64748B",
    };
  }
  const paletteKey = String(slide?.accent_palette_key || "NAVY_GOLD").toUpperCase();
  const tplProf =
    typeof getActiveTemplateProfile === "function"
      ? getActiveTemplateProfile()
      : state.activeTemplateProfile;
  if (tplProf) {
    state.activeTemplateProfile = tplProf;
  }
  const matchPaletteChecked =
    document.getElementById("template-match-palette-checkbox")?.checked !== false;
  const shouldMatchTemplatePalette =
    Boolean(tplProf && tplProf.template_id !== "default_workbench") &&
    (paletteKey === "MATCH_TEMPLATE" || (matchPaletteChecked && !slide?._customPaletteOverride));
  if (shouldMatchTemplatePalette) {
    if (tier === "STUDIO") {
      return {
        tier: "STUDIO",
        isBeautified: true,
        isStudio: true,
        stageBg: "#0F172A",
        textFg: "#F8FAFC",
        subTextFg: "#E2E8F0",
        primaryHex: "#F4C430",
        secondaryAccentHex: "#38BDF8",
        accentHex: tplProf.accent_hex || "#38BDF8",
        cardBg: "#1E293B",
        badgeBg: "#1E293B",
        badgeFg: tplProf.accent_hex || "#F4C430",
        stageBorder: `3px solid ${tplProf.accent_hex || "#38BDF8"}`,
        headerBg: "linear-gradient(90deg, rgba(30,41,59,0.92) 0%, rgba(15,23,42,0.92) 100%)",
        footerColor: "#94A3B8",
      };
    }
    return {
      tier: "BEAUTIFIED",
      isBeautified: true,
      isStudio: false,
      stageBg: "#FAF8F5",
      textFg: "#0F172A",
      subTextFg: "#334155",
      primaryHex: tplProf.primary_hex || "#5A6F43",
      accentHex: tplProf.accent_hex || "#435835",
      cardBg: tplProf.card_bg_hex || "#F4F7F0",
      badgeBg: "#FEF3C7",
      badgeFg: "#92400E",
      stageBorder: `2.5px solid ${tplProf.accent_hex || "#435835"}`,
      headerBg: "linear-gradient(90deg, rgba(7,86,151,0.07) 0%, rgba(212,175,55,0.12) 100%)",
      footerColor: "#64748B",
    };
  }
  if (tier === "STUDIO") {
    const studioAccents = {
      NAVY_GOLD: { primaryHex: "#F4C430", accentHex: "#38BDF8" },
      OLIVE_FOREST: { primaryHex: "#4ADE80", accentHex: "#A3E635" },
      EAGLE_CRIMSON: { primaryHex: "#F4C430", accentHex: "#FB7185" },
      SLATE_ACTION: { primaryHex: "#F4C430", accentHex: "#38BDF8" },
    };
    const st = studioAccents[paletteKey] || studioAccents.NAVY_GOLD;
    return {
      tier: "STUDIO",
      isBeautified: true,
      isStudio: true,
      stageBg: "#0F172A",
      textFg: "#F8FAFC",
      subTextFg: "#E2E8F0",
      primaryHex: st.primaryHex,
      secondaryAccentHex: "#38BDF8",
      accentHex: st.accentHex,
      cardBg: "#1E293B",
      badgeBg: "#1E293B",
      badgeFg: st.accentHex,
      stageBorder: `3px solid ${st.accentHex}`,
      headerBg: "linear-gradient(90deg, rgba(30,41,59,0.92) 0%, rgba(15,23,42,0.92) 100%)",
      footerColor: "#94A3B8",
    };
  }
  const map = {
    NAVY_GOLD: {
      primaryHex: "#003F87",
      accentHex: "#D4AF37",
      cardBg: "#EFF6FF",
      badgeBg: "#FEF3C7",
      badgeFg: "#92400E",
      headerBg: "linear-gradient(90deg, rgba(0,63,135,0.06) 0%, rgba(212,175,55,0.12) 100%)",
    },
    OLIVE_FOREST: {
      primaryHex: "#2E4600",
      accentHex: "#4B5320",
      cardBg: "#F1F8E9",
      badgeBg: "#DCFCE7",
      badgeFg: "#166534",
      headerBg: "linear-gradient(90deg, rgba(46,70,0,0.06) 0%, rgba(75,83,32,0.12) 100%)",
    },
    EAGLE_CRIMSON: {
      primaryHex: "#8B0000",
      accentHex: "#CE1126",
      cardBg: "#FFF5F5",
      badgeBg: "#FEE2E2",
      badgeFg: "#991B1B",
      headerBg: "linear-gradient(90deg, rgba(139,0,0,0.06) 0%, rgba(206,17,38,0.12) 100%)",
    },
    SLATE_ACTION: {
      primaryHex: "#0F172A",
      accentHex: "#005AE0",
      cardBg: "#F0F9FF",
      badgeBg: "#DBEAFE",
      badgeFg: "#1E40AF",
      headerBg: "linear-gradient(90deg, rgba(15,23,42,0.06) 0%, rgba(0,90,224,0.12) 100%)",
    },
  };
  const chosen = map[paletteKey] || map.NAVY_GOLD;
  return {
    tier: "BEAUTIFIED",
    isBeautified: true,
    isStudio: false,
    stageBg: "#FAF8F5",
    textFg: "#0F172A",
    subTextFg: "#334155",
    primaryHex: chosen.primaryHex,
    accentHex: chosen.accentHex,
    cardBg: chosen.cardBg,
    badgeBg: chosen.badgeBg,
    badgeFg: chosen.badgeFg,
    stageBorder: `2.5px solid ${chosen.accentHex}`,
    headerBg: chosen.headerBg,
    footerColor: "#64748B",
  };
}

const DANGLING_TAIL_WORDS_JS = new Set([
  "and", "or", "with", "to", "for", "in", "on", "of", "by", "the", "a", "an",
  "that", "which", "while", "when", "if", "from", "into", "at", "as", "such",
  "including", "through", "during", "before", "after", "under", "over", "between",
]);

function conciseCardBody(bodyText, maxWords = 26, maxChars = 165) {
  const cleaned = String(bodyText || "").trim();
  if (!cleaned) return "";
  const words = cleaned.split(/\s+/);
  if (words.length <= maxWords && cleaned.length <= maxChars) {
    return cleaned;
  }
  const seps = [
    ". ",
    "; ",
    " — ",
    " – ",
    ", which ",
    ", while ",
    ", ensuring ",
    ", allowing ",
    ", including ",
    ", such as ",
    ", especially ",
    " so that ",
    " in order to ",
  ];
  for (const sep of seps) {
    if (cleaned.includes(sep)) {
      const head = cleaned.split(sep)[0].trim().replace(/[,;:\-]+$/, "");
      const headWords = head.split(/\s+/);
      if (headWords.length >= 6 && headWords.length <= maxWords + 2 && head.length <= maxChars + 15) {
        return /[.!?]$/.test(head) ? head : `${head}.`;
      }
    }
  }
  // Preserve single complete sentences within comfortable card capacity rather than chopping mid-phrase
  if (words.length <= maxWords + 18 && cleaned.length <= maxChars + 115) {
    return /[.!?]$/.test(cleaned) ? cleaned : `${cleaned}.`;
  }
  const capped = words.slice(0, maxWords + 6);
  while (capped.length > 6 && capped.join(" ").length > maxChars + 65) {
    capped.pop();
  }
  while (
    capped.length > 6 &&
    DANGLING_TAIL_WORDS_JS.has(capped[capped.length - 1].toLowerCase().replace(/^[,;:\-.()]+|[,;:\-.()]+$/g, ""))
  ) {
    capped.pop();
  }
  let res = capped.join(" ").replace(/[,;:\-(]+$/, "");
  const openParens = (res.match(/\(/g) || []).length;
  const closeParens = (res.match(/\)/g) || []).length;
  if (openParens > closeParens && res.lastIndexOf("(") > 0) {
    res = res.slice(0, res.lastIndexOf("(")).trim().replace(/[,;:\-]+$/, "");
  }
  if (res && !/[.!?]$/.test(res)) {
    res += ".";
  }
  return res;
}

