  // UI-4 & C4: Workbook search filter & Pocket Cue Cards PDF
  document.getElementById("btn-print-cue-cards")?.addEventListener("click", (ev) => {
    ev.preventDefault();
    const badge = state.currentResult?.badge_name || "First Aid";
    downloadPdfFromUrl(`/api/v1/studiokit/cue-cards.pdf?badge_name=${encodeURIComponent(badge)}`);
  });
  document.getElementById("workbook-search-input")?.addEventListener("input", (ev) => {
    const q = (ev.target.value || "").trim().toLowerCase();
    const previewEl = document.getElementById("workbook-markdown-preview");
    if (!previewEl || !state.currentResult) return;
    const fillableBtn = document.getElementById("btn-workbook-open-fillable-html");
    const liveFillableSections = previewEl.querySelectorAll(".wb-req-section, .wb-card, section[data-req-id]");
    if (fillableBtn?.classList.contains("active") && liveFillableSections.length > 0) {
      liveFillableSections.forEach((sec) => {
        sec.style.display = !q || sec.textContent.toLowerCase().includes(q) ? "" : "none";
      });
      return;
    }
    ["btn-workbook-view-default", "btn-workbook-open-fillable-html", "btn-workbook-open-cpp"].forEach((id) => {
      const btnEl = document.getElementById(id);
      if (btnEl) {
        const isAct = id === "btn-workbook-view-default";
        btnEl.classList.toggle("active", isAct);
        btnEl.setAttribute("aria-selected", isAct ? "true" : "false");
      }
    });
    const rawMd = state.currentResult.workbook_markdown || "";
    if (!q) {
      previewEl.innerHTML = renderMarkdownToStyledHtml(rawMd);
      return;
    }
    const blocks = rawMd.split(/\n(?=##\s)/);
    const filtered = blocks.filter((b, i) => i === 0 || b.toLowerCase().includes(q));
    previewEl.innerHTML = renderMarkdownToStyledHtml(filtered.join("\n\n") || `No workbook sections matching "${q}".`);
  });

