let _demoStepTimer = null;
let _demoCompletionHideTimer = null;
let _demoCountdownRaf = null;
let _demoPaceMode = "normal"; // "normal" (6.5s) | "relaxed" (9.0s) | "manual" (0s)
let _demoHoverPaused = false;
let _demoHoverResumeTimer = null;
let _demoLastPointerPos = null;
let _demoScrollRafPending = false;
let _demoCountdownState = {
  durationMs: 6500,
  elapsedMs: 0,
  lastTickTs: 0,
  onComplete: null,
};

const DEMO_PACE_MODES = [
  { id: "normal", baseMs: 6500, bannerLabel: "⏱️ Pace: Normal (6.5s)", calloutLabel: "⏱️ 6.5s" },
  { id: "relaxed", baseMs: 9000, bannerLabel: "🐢 Pace: Relaxed (9s)", calloutLabel: "🐢 9.0s" },
  { id: "manual", baseMs: 0, bannerLabel: "✋ Pace: Manual", calloutLabel: "✋ Manual" },
];

function getActiveDemoPaceConfig() {
  return DEMO_PACE_MODES.find((m) => m.id === _demoPaceMode) || DEMO_PACE_MODES[0];
}

function computeDemoStepDwellMs(step) {
  const paceCfg = getActiveDemoPaceConfig();
  if (paceCfg.baseMs <= 0) return 0;
  const textLen = String(step?.title || "").length + String(step?.narration || "").length;
  const extraChars = Math.max(0, textLen - 140);
  const extraMs = Math.min(1800, extraChars * 28);
  return paceCfg.baseMs + extraMs;
}

function updateDemoProgressBars(pct) {
  const clamped = Math.max(0, Math.min(100, pct));
  const bannerFill = document.getElementById("demo-banner-progress-fill");
  const calloutFill = document.getElementById("demo-callout-progress-fill");
  if (bannerFill) bannerFill.style.width = `${clamped.toFixed(1)}%`;
  if (calloutFill) calloutFill.style.width = `${clamped.toFixed(1)}%`;
}

function stopDemoCountdownLoop() {
  if (_demoStepTimer) {
    clearTimeout(_demoStepTimer);
    _demoStepTimer = null;
  }
  if (_demoCountdownRaf) {
    cancelAnimationFrame(_demoCountdownRaf);
    _demoCountdownRaf = null;
  }
  _demoCountdownState.onComplete = null;
}

function startDemoCountdownLoop(durationMs, onComplete) {
  stopDemoCountdownLoop();
  if (durationMs <= 0) {
    updateDemoProgressBars(100);
    return;
  }
  _demoCountdownState = {
    durationMs,
    elapsedMs: 0,
    lastTickTs: performance.now(),
    onComplete,
  };
  updateDemoProgressBars(0);

  const tick = (now) => {
    if (!state.activeDemoTour || state.activeDemoTour.completed) {
      updateDemoProgressBars(0);
      return;
    }
    const isPaused = Boolean(state.activeDemoTour.paused) || _demoHoverPaused;
    if (!isPaused) {
      const dt = Math.max(0, now - _demoCountdownState.lastTickTs);
      _demoCountdownState.elapsedMs += dt;
    }
    _demoCountdownState.lastTickTs = now;
    const pct = (_demoCountdownState.elapsedMs / _demoCountdownState.durationMs) * 100;
    updateDemoProgressBars(pct);

    if (_demoCountdownState.elapsedMs >= _demoCountdownState.durationMs) {
      const cb = _demoCountdownState.onComplete;
      stopDemoCountdownLoop();
      if (typeof cb === "function") cb();
      return;
    }
    _demoCountdownRaf = requestAnimationFrame(tick);
  };

  _demoCountdownRaf = requestAnimationFrame(tick);
}

function resolveFirstVisibleTargetElement(targetSelector) {
  if (!targetSelector) return null;
  const selectors = String(targetSelector)
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  for (const sel of selectors) {
    try {
      const candidate = document.querySelector(sel);
      if (candidate) {
        const parentSplitMenu = candidate.closest && candidate.closest(".m3-split-dropdown-menu");
        if (parentSplitMenu && (!parentSplitMenu.classList.contains("open") || parentSplitMenu.classList.contains("hidden"))) {
          document.querySelectorAll(".m3-split-dropdown-menu.open").forEach((m) => {
            if (m !== parentSplitMenu) {
              m.classList.remove("open");
              m.classList.add("hidden");
            }
          });
          parentSplitMenu.classList.add("open");
          parentSplitMenu.classList.remove("hidden");
        }
        const r = candidate.getBoundingClientRect();
        if (r.width > 8 && r.height > 8) {
          return candidate;
        }
      }
    } catch (_err) {}
  }
  return null;
}

function isAnyFullModalOpen() {
  const modalIds = ["docs-viewer-modal", "mcp-hub-modal", "template-studio-modal", "image-studio-modal"];
  return modalIds.some((id) => {
    const m = document.getElementById(id);
    return Boolean(m && (m.classList.contains("open") || !m.classList.contains("hidden")));
  });
}

function syncTourBannerDockingMode(_targetEl = null) {
  const bannerEl = document.getElementById("active-demo-tour-banner");
  if (!bannerEl) return;
  if (state.demoTourCustomPos && typeof state.demoTourCustomPos.left === "number") {
    bannerEl.classList.remove("is-bottom-docked");
    bannerEl.classList.add("is-floating-dragged");
    bannerEl.style.left = `${Math.round(state.demoTourCustomPos.left)}px`;
    bannerEl.style.top = `${Math.round(state.demoTourCustomPos.top)}px`;
    return;
  }
  bannerEl.classList.remove("is-floating-dragged");
  bannerEl.style.left = "";
  bannerEl.style.top = "";

  // Only dock the Guided Tour banner to the bottom when a full-screen modal is open.
  // Keeping it in normal sticky flow on all workbench steps prevents an 88px vertical layout jump between steps.
  const modalOpen = isAnyFullModalOpen();
  bannerEl.classList.toggle("is-bottom-docked", modalOpen);
}

function scrollTargetIntoComfortZone(targetEl) {
  if (!targetEl || typeof targetEl.getBoundingClientRect !== "function") return;
  if (isAnyFullModalOpen()) return;
  if (targetEl.closest && targetEl.closest(".m3-top-app-bar")) {
    if (window.scrollY > 4) {
      window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    }
    return;
  }
  const rect = targetEl.getBoundingClientRect();
  const vh = window.innerHeight || 800;
  const bannerEl = document.getElementById("active-demo-tour-banner");
  const bannerVisible = Boolean(
    bannerEl && !bannerEl.classList.contains("hidden") && !bannerEl.classList.contains("is-bottom-docked")
  );
  const bannerRect = bannerVisible ? bannerEl.getBoundingClientRect() : null;
  const topSafeMargin =
    bannerRect && bannerRect.height > 0 ? Math.max(96, Math.round(bannerRect.bottom + 14)) : 96;
  const bottomSafeMargin = vh - 80;

  if (rect.top < topSafeMargin) {
    const delta = rect.top - topSafeMargin - 16;
    window.scrollTo({ top: Math.max(0, Math.round(window.scrollY + delta)), left: 0, behavior: "auto" });
  } else if (rect.bottom > bottomSafeMargin && rect.height < vh * 0.72) {
    const delta = rect.bottom - bottomSafeMargin + 24;
    const maxAllowedDelta = Math.max(0, rect.top - topSafeMargin - 12);
    const boundedDelta = Math.min(delta, maxAllowedDelta);
    if (boundedDelta > 4) {
      window.scrollTo({
        top: Math.max(0, Math.round(window.scrollY + boundedDelta)),
        left: 0,
        behavior: "auto",
      });
    }
  }
}

function resetTourTransientUiForStep(scenario, stepIdx) {
  const sid = scenario?.id || "";
  const keepImageStudio = sid === "demo-3-guardrail-and-trace" && stepIdx >= 2 && stepIdx <= 5;
  const keepTemplateDropdown = sid === "demo-4-layout-and-templates" && stepIdx === 0;
  const keepTemplateStudio = sid === "demo-4-layout-and-templates" && stepIdx === 6;
  const keepVisualHover = sid === "demo-5-codesign-and-image" && stepIdx >= 0 && stepIdx <= 2;
  const keepPresenterConsole = sid === "demo-6-presenter-and-quiz" && stepIdx === 3;
  const keepPatrolScoreboard = sid === "demo-6-presenter-and-quiz" && (stepIdx === 2 || stepIdx === 3);
  const keepMcpModal = sid === "demo-8-mcp-and-docs-studio" && stepIdx >= 1 && stepIdx <= 6;
  const keepDocsModal = sid === "demo-8-mcp-and-docs-studio" && stepIdx >= 8 && stepIdx <= 10;

  document.getElementById("stage-right-visual")?.classList.toggle("demo-force-hover", keepVisualHover);

  if (!keepTemplateDropdown) {
    document.getElementById("stage-template-dropdown-menu")?.classList.add("hidden");
  }
  document.querySelectorAll(".m3-split-dropdown-menu").forEach((m) => {
    m.classList.remove("open");
    m.classList.add("hidden");
  });
  if (!keepImageStudio) {
    const imgModal = document.getElementById("image-studio-modal");
    if (imgModal && !imgModal.classList.contains("hidden")) {
      document.getElementById("btn-close-image-studio")?.click();
    }
  }
  if (!keepTemplateStudio) {
    const tplModal = document.getElementById("template-studio-modal");
    if (tplModal && !tplModal.classList.contains("hidden")) {
      document.getElementById("btn-close-template-studio")?.click();
    }
  }
  if (!keepMcpModal) {
    const mcpModal = document.getElementById("mcp-hub-modal");
    if (mcpModal && !mcpModal.classList.contains("hidden")) {
      document.getElementById("btn-close-mcp-hub")?.click();
    }
  }
  if (!keepDocsModal) {
    const docsModal = document.getElementById("docs-viewer-modal");
    if (docsModal && !docsModal.classList.contains("hidden")) {
      document.getElementById("btn-close-docs-viewer-modal")?.click();
    }
  }
  if (!keepPresenterConsole && state.presenterConsoleOpen && typeof togglePresenterConsoleMode === "function") {
    togglePresenterConsoleMode(false);
  }
  if (!keepPatrolScoreboard && state.patrolScoreboardVisible) {
    state.patrolScoreboardVisible = false;
    document.getElementById("stage-patrol-scoreboard")?.classList.add("hidden");
    document.getElementById("btn-toggle-patrol-scoreboard")?.classList.remove("active");
  }
}

function closeDemoOpenedModalsAndResetScroll(scrollToTop = true) {
  document.getElementById("stage-right-visual")?.classList.remove("demo-force-hover");
  document.getElementById("stage-template-dropdown-menu")?.classList.add("hidden");
  document.querySelectorAll(".m3-split-dropdown-menu").forEach((m) => {
    m.classList.remove("open");
    m.classList.add("hidden");
  });
  document.getElementById("btn-close-image-studio")?.click();
  document.getElementById("btn-close-template-studio")?.click();
  document.getElementById("btn-close-mcp-hub")?.click();
  document.getElementById("btn-close-docs-viewer-modal")?.click();
  if (state.presenterConsoleOpen && typeof togglePresenterConsoleMode === "function") {
    togglePresenterConsoleMode(false);
  }
  state.patrolScoreboardVisible = false;
  document.getElementById("stage-patrol-scoreboard")?.classList.add("hidden");
  document.getElementById("btn-toggle-patrol-scoreboard")?.classList.remove("active");
  const profileAcc = document.getElementById("counselor-profile-accordion");
  if (profileAcc) profileAcc.open = false;

  if (scrollToTop) {
    try {
      window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    } catch (_err) {
      window.scrollTo(0, 0);
    }
    document.documentElement.scrollTop = 0;
    document.body.scrollTop = 0;
    const sidebarEl = document.getElementById("left-setup-sidebar");
    if (sidebarEl) sidebarEl.scrollTop = 0;
  }
}

function hideDemoSpotlightAndCalloutOverlays(immediate = false) {
  const ringEl = document.getElementById("demo-spotlight-ring");
  const calloutEl = document.getElementById("demo-floating-callout");
  const cursorEl = document.getElementById("demo-virtual-cursor");

  if (immediate) {
    ringEl?.classList.remove("is-fading-out");
    calloutEl?.classList.remove("is-fading-out");
    cursorEl?.classList.remove("is-fading-out");
    ringEl?.classList.add("hidden");
    calloutEl?.classList.add("hidden");
    cursorEl?.classList.add("hidden");
    return;
  }

  ringEl?.classList.add("is-fading-out");
  calloutEl?.classList.add("is-fading-out");
  cursorEl?.classList.add("is-fading-out");
  setTimeout(() => {
    if (!state.activeDemoTour || state.activeDemoTour.completed) {
      ringEl?.classList.add("hidden");
      calloutEl?.classList.add("hidden");
      cursorEl?.classList.add("hidden");
      ringEl?.classList.remove("is-fading-out");
      calloutEl?.classList.remove("is-fading-out");
      cursorEl?.classList.remove("is-fading-out");
    }
  }, 180);
}

function rectsIntersect(a, b, pad = 6) {
  if (!a || !b) return false;
  return !(
    a.right + pad < b.left ||
    a.left - pad > b.right ||
    a.bottom + pad < b.top ||
    a.top - pad > b.bottom
  );
}

function positionDemoSpotlightAndCallout(
  targetSelector,
  stepPillText,
  titleText,
  bodyText,
  placement = "bottom",
  options = {}
) {
  const ringEl = document.getElementById("demo-spotlight-ring");
  const calloutEl = document.getElementById("demo-floating-callout");
  const cursorEl = document.getElementById("demo-virtual-cursor");
  const pillEl = document.getElementById("demo-callout-step-pill");
  const titleEl = document.getElementById("demo-callout-title");
  const bodyEl = document.getElementById("demo-callout-body");

  if (pillEl && stepPillText) pillEl.textContent = stepPillText;
  if (titleEl && titleText) titleEl.textContent = titleText;
  if (bodyEl && bodyText) bodyEl.textContent = bodyText;

  const targetEl = resolveFirstVisibleTargetElement(targetSelector);
  if (!targetEl) {
    hideDemoSpotlightAndCalloutOverlays(true);
    return;
  }

  syncTourBannerDockingMode(targetEl);

  // Keep overlays invisible while measuring dimensions and assigning exact new coordinates
  // so they appear instantaneously in their new positions with zero jump or flash.
  if (ringEl) {
    ringEl.style.visibility = "hidden";
    ringEl.classList.remove("hidden", "is-fading-out");
  }
  if (cursorEl) {
    cursorEl.style.visibility = "hidden";
    cursorEl.classList.remove("hidden", "is-fading-out");
  }
  if (calloutEl && !options.cursorOnly) {
    calloutEl.style.visibility = "hidden";
    calloutEl.classList.remove("hidden", "is-fading-out");
  }

  const rect = targetEl.getBoundingClientRect();
  const pad = 6;
  const top = Math.max(8, rect.top - pad);
  const left = Math.max(8, rect.left - pad);
  const width = Math.min(window.innerWidth - left - 8, rect.width + pad * 2);
  const clampedHeight = Math.min(window.innerHeight - top - 8, rect.height + pad * 2);

  if (ringEl) {
    ringEl.style.top = `${Math.round(top)}px`;
    ringEl.style.left = `${Math.round(left)}px`;
    ringEl.style.width = `${Math.round(width)}px`;
    ringEl.style.height = `${Math.round(clampedHeight)}px`;
  }

  if (cursorEl) {
    const customCursorTarget =
      options.cursorSelector ? resolveFirstVisibleTargetElement(options.cursorSelector) : null;
    const cRect = customCursorTarget ? customCursorTarget.getBoundingClientRect() : rect;
    const cursorX = customCursorTarget
      ? Math.min(window.innerWidth - 36, Math.max(16, cRect.left + Math.min(cRect.width * 0.5, 90)))
      : Math.min(window.innerWidth - 36, Math.max(16, rect.left + Math.min(rect.width * 0.28, 120)));
    const cursorY = customCursorTarget
      ? Math.min(window.innerHeight - 36, Math.max(16, cRect.top + Math.min(cRect.height * 0.5, 48)))
      : Math.min(window.innerHeight - 36, Math.max(16, rect.top + Math.min(rect.height * 0.35, 64)));
    cursorEl.style.transform = `translate3d(${Math.round(cursorX)}px, ${Math.round(cursorY)}px, 0)`;
    if (options.pulseCursor !== false) {
      cursorEl.classList.remove("is-clicking");
      void cursorEl.offsetWidth;
      cursorEl.classList.add("is-clicking");
    }
  }

  if (calloutEl && !options.cursorOnly) {
    const calloutW = Math.max(320, calloutEl.offsetWidth || 386);
    const calloutH = Math.max(132, calloutEl.offsetHeight || 162);
    const gap = 14;
    const bannerEl = document.getElementById("active-demo-tour-banner");
    const bannerVisible = Boolean(bannerEl && !bannerEl.classList.contains("hidden"));
    const bannerRect = bannerVisible ? bannerEl.getBoundingClientRect() : null;

    let minTop = 14;
    let maxTop = Math.max(minTop, window.innerHeight - calloutH - 14);
    if (bannerRect) {
      if (bannerRect.top < window.innerHeight * 0.35) {
        minTop = Math.max(minTop, Math.round(bannerRect.bottom + 10));
      } else if (bannerRect.bottom > window.innerHeight * 0.65) {
        maxTop = Math.min(maxTop, Math.round(bannerRect.top - calloutH - 10));
      }
    }
    maxTop = Math.max(minTop, maxTop);

    const minLeft = 14;
    const maxLeft = Math.max(minLeft, window.innerWidth - calloutW - 14);

    let cTop = rect.bottom + gap;
    let cLeft = rect.left;
    let resolvedSide = placement;

    const spaceRight = window.innerWidth - rect.right;
    const spaceLeft = rect.left;
    const spaceBottom = maxTop + calloutH - rect.bottom;
    const spaceTop = rect.top - minTop;

    if (placement === "right" && spaceRight >= calloutW + 20) {
      cTop = Math.min(maxTop, Math.max(minTop, rect.top));
      cLeft = Math.min(maxLeft, rect.right + gap);
      resolvedSide = "right";
    } else if (placement === "left" && spaceLeft >= calloutW + 20) {
      cTop = Math.min(maxTop, Math.max(minTop, rect.top));
      cLeft = Math.max(minLeft, rect.left - calloutW - gap);
      resolvedSide = "left";
    } else if (placement === "top" && spaceTop >= calloutH + gap) {
      cTop = Math.max(minTop, rect.top - calloutH - gap);
      cLeft = Math.min(maxLeft, Math.max(minLeft, rect.left + 10));
      resolvedSide = "top";
    } else if (spaceBottom >= calloutH + gap) {
      cTop = Math.min(maxTop, Math.max(minTop, rect.bottom + gap));
      cLeft = Math.min(maxLeft, Math.max(minLeft, rect.left));
      resolvedSide = "bottom";
    } else if (spaceTop >= calloutH + gap) {
      cTop = Math.max(minTop, rect.top - calloutH - gap);
      cLeft = Math.min(maxLeft, Math.max(minLeft, rect.left + 10));
      resolvedSide = "top";
    } else if (spaceRight >= calloutW + 20) {
      cTop = Math.min(maxTop, Math.max(minTop, rect.top + 8));
      cLeft = Math.min(maxLeft, rect.right + gap);
      resolvedSide = "right";
    } else if (spaceLeft >= calloutW + 20) {
      cTop = Math.min(maxTop, Math.max(minTop, rect.top + 8));
      cLeft = Math.max(minLeft, rect.left - calloutW - gap);
      resolvedSide = "left";
    } else {
      cTop = maxTop;
      cLeft = maxLeft;
      resolvedSide = "bottom";
    }

    // Final collision check against the Guided Tour banner (including user-dragged floating positions)
    if (bannerRect) {
      const candidateBox = {
        left: cLeft,
        top: cTop,
        right: cLeft + calloutW,
        bottom: cTop + calloutH,
      };
      if (rectsIntersect(candidateBox, bannerRect, 8)) {
        if (bannerRect.top > window.innerHeight * 0.5) {
          cTop = Math.max(14, bannerRect.top - calloutH - 12);
        } else {
          cTop = Math.min(window.innerHeight - calloutH - 14, bannerRect.bottom + 12);
        }
      }
    }

    calloutEl.setAttribute("data-placement", resolvedSide);
    calloutEl.style.top = `${Math.round(cTop)}px`;
    calloutEl.style.left = `${Math.round(cLeft)}px`;
  }

  if (ringEl) ringEl.style.visibility = "visible";
  if (cursorEl) cursorEl.style.visibility = "visible";
  if (calloutEl && !options.cursorOnly) calloutEl.style.visibility = "visible";
}

function syncDemoControlsState() {
  const tour = state.activeDemoTour;
  const scenario = tour ? DEMO_SCENARIOS_CATALOG.find((d) => d.id === tour.scenarioId) : null;
  const totalSteps = scenario?.steps?.length || 1;
  const stepIdx = tour?.stepIdx || 0;
  const isLastStep = stepIdx >= totalSteps - 1;
  const isCompleted = Boolean(tour?.completed);
  const isPaused = Boolean(tour?.paused);
  const paceCfg = getActiveDemoPaceConfig();

  const prevBtn = document.getElementById("btn-demo-step-prev");
  const pauseBtn = document.getElementById("btn-demo-step-pause");
  const nextBtn = document.getElementById("btn-demo-step-next");
  const speedBtn = document.getElementById("btn-demo-speed-toggle");

  const calloutPrevBtn = document.getElementById("btn-callout-prev");
  const calloutPauseBtn = document.getElementById("btn-callout-pause");
  const calloutNextBtn = document.getElementById("btn-callout-next");
  const calloutSpeedBtn = document.getElementById("btn-callout-speed");

  if (prevBtn) prevBtn.disabled = stepIdx === 0 && !isCompleted;
  if (calloutPrevBtn) calloutPrevBtn.disabled = stepIdx === 0;

  const pauseText = isPaused || paceCfg.baseMs <= 0 ? "▶ Resume" : "⏸ Pause";
  if (pauseBtn) {
    pauseBtn.textContent = pauseText;
    pauseBtn.classList.toggle("hidden", isCompleted);
  }
  if (calloutPauseBtn) {
    calloutPauseBtn.textContent = pauseText;
  }

  if (nextBtn) {
    if (isCompleted) {
      nextBtn.textContent = "↺ Replay Tour";
    } else if (isLastStep) {
      nextBtn.textContent = "✓ Finish Tour";
    } else {
      nextBtn.textContent = "⏭ Next Step";
    }
  }
  if (calloutNextBtn) {
    calloutNextBtn.textContent = isLastStep ? "✓ Finish Tour" : "⏭ Next";
  }

  if (speedBtn) speedBtn.textContent = paceCfg.bannerLabel;
  if (calloutSpeedBtn) calloutSpeedBtn.textContent = paceCfg.calloutLabel;
}

function completeInteractiveDemoTour(scenario) {
  stopDemoCountdownLoop();
  if (_demoCompletionHideTimer) {
    clearTimeout(_demoCompletionHideTimer);
    _demoCompletionHideTimer = null;
  }

  if (state.activeDemoTour) {
    state.activeDemoTour.completed = true;
    state.activeDemoTour.paused = true;
    state.activeDemoTour.transitioning = false;
  }

  // 1. Dismiss the spotlight ring, floating callout bubble, and virtual cursor
  hideDemoSpotlightAndCalloutOverlays(true);

  // 2. Close any modal opened during the tour and return the UI to the top
  closeDemoOpenedModalsAndResetScroll(true);

  // 3. Transition the docked banner into a clean completion summary state
  const bannerEl = document.getElementById("active-demo-tour-banner");
  const badgeEl = document.getElementById("demo-tour-badge");
  const titleEl = document.getElementById("demo-tour-title");
  const narrationEl = document.getElementById("demo-tour-narration");
  const dotsEl = document.getElementById("demo-tour-step-dots");

  if (bannerEl && scenario) {
    bannerEl.classList.remove("hidden", "is-bottom-docked");
    bannerEl.classList.add("is-completed");
    if (badgeEl) {
      badgeEl.textContent = `✅ COMPLETED TOUR ${scenario.index} OF ${DEMO_SCENARIOS_CATALOG.length}`;
    }
    if (titleEl) {
      titleEl.textContent = `Completed: ${scenario.shortTitle}`;
    }
    if (narrationEl) {
      narrationEl.textContent =
        "Guided Tour complete: spotlight dismissed and view returned to the top of the Workbench. Click 'Replay Tour', 'Next Tour ▸', or 'Exit'.";
    }
    if (dotsEl) {
      dotsEl.querySelectorAll(".m3-demo-step-dot").forEach((d) => {
        d.classList.remove("active");
        d.classList.add("done");
      });
    }
    updateDemoProgressBars(100);
    syncDemoControlsState();

    _demoCompletionHideTimer = setTimeout(() => {
      if (state.activeDemoTour?.completed) {
        stopInteractiveDemoTour({ scrollToTop: false });
      }
    }, 5200);
  } else {
    stopInteractiveDemoTour({ scrollToTop: false });
  }
}
window.completeInteractiveDemoTour = completeInteractiveDemoTour;

function stopInteractiveDemoTour(options = {}) {
  stopDemoCountdownLoop();
  if (_demoCompletionHideTimer) {
    clearTimeout(_demoCompletionHideTimer);
    _demoCompletionHideTimer = null;
  }
  const shouldScrollTop = options.scrollToTop !== false;
  state.activeDemoTour = null;

  const bannerEl = document.getElementById("active-demo-tour-banner");
  bannerEl?.classList.remove("is-completed", "is-bottom-docked", "is-floating-dragged");
  bannerEl?.classList.add("hidden");

  hideDemoSpotlightAndCalloutOverlays(true);
  closeDemoOpenedModalsAndResetScroll(shouldScrollTop);
}
window.stopInteractiveDemoTour = stopInteractiveDemoTour;

async function runDemoStep(scenario, stepIdx, _options = {}) {
  if (!scenario || !Array.isArray(scenario.steps) || stepIdx < 0 || stepIdx >= scenario.steps.length) {
    return;
  }
  stopDemoCountdownLoop();
  if (_demoCompletionHideTimer) {
    clearTimeout(_demoCompletionHideTimer);
    _demoCompletionHideTimer = null;
  }

  const wasPaused = Boolean(state.activeDemoTour?.paused && !state.activeDemoTour?.completed);
  const transitionRunId = (state.activeDemoTour?.runId || 0) + 1;
  state.activeDemoTour = {
    scenarioId: scenario.id,
    scenarioIndex: scenario.index,
    stepIdx,
    paused: wasPaused || _demoPaceMode === "manual",
    completed: false,
    transitioning: true,
    runId: transitionRunId,
  };

  // Phase 1: Immediately hide the spotlight ring, floating callout, and virtual cursor
  // BEFORE adjusting the workbench view or running step actions so the overlays never jump or chase.
  hideDemoSpotlightAndCalloutOverlays(true);

  // Ensure any modals/dropdowns/presenter-views from other steps are cleanly closed so Prev/Next is 100% idempotent
  resetTourTransientUiForStep(scenario, stepIdx);

  const step = scenario.steps[stepIdx];
  const totalSteps = scenario.steps.length;
  const bannerEl = document.getElementById("active-demo-tour-banner");
  const badgeEl = document.getElementById("demo-tour-badge");
  const titleEl = document.getElementById("demo-tour-title");
  const narrationEl = document.getElementById("demo-tour-narration");
  const dotsEl = document.getElementById("demo-tour-step-dots");

  bannerEl?.classList.remove("hidden", "is-completed");
  if (badgeEl) {
    badgeEl.textContent = `🧭 TOUR ${scenario.index} OF ${DEMO_SCENARIOS_CATALOG.length} • STEP ${stepIdx + 1} OF ${totalSteps}`;
  }
  if (titleEl) {
    titleEl.textContent = `${step.title}`;
  }
  if (narrationEl) {
    narrationEl.textContent = step.narration;
  }

  if (dotsEl) {
    dotsEl.innerHTML = scenario.steps
      .map(
        (s, idx) =>
          `<button type="button" class="m3-demo-step-dot ${idx === stepIdx ? "active" : idx < stepIdx ? "done" : ""}" data-demo-step-jump="${idx}" title="Step ${idx + 1}: ${escapeHtml(s.title)}">${idx + 1}</button>`
      )
      .join("");
    dotsEl.querySelectorAll("[data-demo-step-jump]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const jIdx = parseInt(btn.getAttribute("data-demo-step-jump") || "0", 10);
        runDemoStep(scenario, jIdx, { immediateAction: true });
      });
    });
  }

  syncDemoControlsState();

  // Phase 2: Execute step action and adjust the workbench view while overlays remain hidden
  try {
    if (typeof step.action === "function") {
      await step.action();
    }
  } catch (_err) {}

  if (
    !state.activeDemoTour ||
    state.activeDemoTour.scenarioId !== scenario.id ||
    state.activeDemoTour.stepIdx !== stepIdx ||
    state.activeDemoTour.runId !== transitionRunId
  ) {
    return;
  }

  // Refresh dynamic title/narration in case step.action resolved location
  if (titleEl) titleEl.textContent = `${step.title}`;
  if (narrationEl) narrationEl.textContent = step.narration;

  // Sync banner docking mode (e.g. if a modal opened or closed during step.action) and scroll target into view
  syncTourBannerDockingMode();
  const targetEl = resolveFirstVisibleTargetElement(step.targetSelector);
  if (targetEl && !step.skipComfortScroll) {
    scrollTargetIntoComfortZone(targetEl);
  }

  // Wait one animation frame for DOM layout and synchronous scroll adjustments to settle completely
  await new Promise((resolve) => requestAnimationFrame(resolve));

  if (
    !state.activeDemoTour ||
    state.activeDemoTour.scenarioId !== scenario.id ||
    state.activeDemoTour.stepIdx !== stepIdx ||
    state.activeDemoTour.runId !== transitionRunId
  ) {
    return;
  }

  // Phase 3: Show the overlays instantly in their exact new positions for the start of the step
  state.activeDemoTour.transitioning = false;
  positionDemoSpotlightAndCallout(
    step.targetSelector,
    `STEP ${stepIdx + 1} OF ${totalSteps}`,
    step.title,
    step.narration,
    step.placement || "bottom",
    { pulseCursor: true, cursorSelector: step.cursorSelector }
  );

  // Phase 4: Start smooth countdown progress bar; at completion of the step, hide overlays before advancing
  const dwellMs = computeDemoStepDwellMs(step);
  startDemoCountdownLoop(dwellMs, () => {
    if (!state.activeDemoTour || state.activeDemoTour.scenarioId !== scenario.id) return;
    hideDemoSpotlightAndCalloutOverlays(true);
    if (stepIdx < totalSteps - 1) {
      runDemoStep(scenario, stepIdx + 1);
    } else {
      completeInteractiveDemoTour(scenario);
    }
  });
}

async function startInteractiveDemoTour(demoId = "demo-1-grounded-deck") {
  await resolveAndSyncUserLocationForTours();
  const scenario =
    DEMO_SCENARIOS_CATALOG.find((d) => d.id === demoId) || DEMO_SCENARIOS_CATALOG[0];
  document.getElementById("hero-demo-dropdown-menu")?.classList.add("hidden");
  document.getElementById("btn-hero-demo-menu-toggle")?.setAttribute("aria-expanded", "false");
  if (
    scenario.id !== "demo-1-grounded-deck" &&
    scenario.id !== "demo-2-multi-option" &&
    !(state.currentResult?.storyboard?.slides || []).length
  ) {
    await ensureBadgeLoadedForTour(state.currentBadge || "First Aid");
  }
  state.activeDemoTour = {
    scenarioId: scenario.id,
    scenarioIndex: scenario.index,
    stepIdx: 0,
    paused: _demoPaceMode === "manual",
    completed: false,
  };
  await runDemoStep(scenario, 0, { immediateAction: true });
}
window.startInteractiveDemoTour = startInteractiveDemoTour;

function initDraggableDemoTourBanner() {
  const bannerEl = document.getElementById("active-demo-tour-banner");
  const handleEl = document.getElementById("demo-tour-drag-handle");
  if (!bannerEl || !handleEl) return;

  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let origLeft = 0;
  let origTop = 0;

  handleEl.addEventListener("dblclick", (ev) => {
    ev.stopPropagation();
    state.demoTourCustomPos = null;
    syncTourBannerDockingMode();
    showToast("📌 Guided Tour bar re-docked to automatic position.", "info");
  });

  handleEl.addEventListener("mousedown", (ev) => {
    if (ev.button !== 0) return;
    ev.preventDefault();
    const r = bannerEl.getBoundingClientRect();
    isDragging = true;
    startX = ev.clientX;
    startY = ev.clientY;
    origLeft = r.left;
    origTop = r.top;
    state.demoTourCustomPos = { left: origLeft, top: origTop };
    syncTourBannerDockingMode();
  });

  window.addEventListener("mousemove", (ev) => {
    if (!isDragging) return;
    const dx = ev.clientX - startX;
    const dy = ev.clientY - startY;
    const bw = bannerEl.offsetWidth || 860;
    const bh = bannerEl.offsetHeight || 74;
    const nextLeft = Math.max(8, Math.min(window.innerWidth - bw - 8, origLeft + dx));
    const nextTop = Math.max(8, Math.min(window.innerHeight - bh - 8, origTop + dy));
    state.demoTourCustomPos = { left: nextLeft, top: nextTop };
    syncTourBannerDockingMode();
  });

  window.addEventListener("mouseup", () => {
    isDragging = false;
  });
}

function initInteractiveGuidedDemoWalkthroughs() {
  const demoToggleBtn = document.getElementById("btn-hero-demo-menu-toggle");
  const demoMenu = document.getElementById("hero-demo-dropdown-menu");
  const closeMenuBtn = document.getElementById("btn-close-hero-demo-menu");

  resolveAndSyncUserLocationForTours();
  initDraggableDemoTourBanner();

  const locInput = document.getElementById("input-counselor-location");
  locInput?.addEventListener("change", () => {
    resolveAndSyncUserLocationForTours();
  });

  // Bind the 3 interactive Hero KPI pill buttons (Item 18)
  document.getElementById("btn-hero-kpi-slides")?.addEventListener("click", () => {
    switchMainTab("panel-storyboard");
    const sbLayout = document.getElementById("panel-storyboard");
    sbLayout?.classList.remove("filmstrip-collapsed");
    const filmToggle = document.getElementById("btn-toggle-filmstrip");
    if (filmToggle) filmToggle.textContent = "◀ Outline";
    const filmstripEl = document.getElementById("slide-filmstrip-list");
    filmstripEl?.classList.remove("hidden");
    filmstripEl?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });

  document.getElementById("btn-hero-kpi-reqs")?.addEventListener("click", () => {
    switchMainTab("panel-triage");
    document.getElementById("panel-triage")?.scrollIntoView({ behavior: "smooth", block: "start" });
  });

  document.getElementById("btn-hero-kpi-theme")?.addEventListener("click", () => {
    switchMainTab("panel-storyboard");
    document.getElementById("btn-stage-template-picker")?.click();
  });

  // Bind Patrol Scoreboard ✕ Hide button (Item 11)
  document.getElementById("btn-patrol-scoreboard-hide")?.addEventListener("click", () => {
    state.patrolScoreboardVisible = false;
    document.getElementById("stage-patrol-scoreboard")?.classList.add("hidden");
    document.getElementById("btn-toggle-patrol-scoreboard")?.classList.remove("active");
  });

  demoToggleBtn?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    resolveAndSyncUserLocationForTours();
    const isHidden = demoMenu?.classList.toggle("hidden");
    demoToggleBtn.setAttribute("aria-expanded", !isHidden ? "true" : "false");
  });

  closeMenuBtn?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    demoMenu?.classList.add("hidden");
    demoToggleBtn?.setAttribute("aria-expanded", "false");
  });

  document.addEventListener("click", (ev) => {
    const wrap = document.getElementById("hero-demo-dropdown-wrap");
    if (wrap && !wrap.contains(ev.target)) {
      demoMenu?.classList.add("hidden");
      demoToggleBtn?.setAttribute("aria-expanded", "false");
    }
  });

  document.querySelectorAll("[data-demo-id]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const demoId = btn.getAttribute("data-demo-id") || "demo-1-grounded-deck";
      await startInteractiveDemoTour(demoId);
    });
  });

  const handlePrevStep = () => {
    if (!state.activeDemoTour) return;
    const scenario = DEMO_SCENARIOS_CATALOG.find((d) => d.id === state.activeDemoTour.scenarioId);
    if (!scenario) return;
    if (state.activeDemoTour.completed) {
      runDemoStep(scenario, scenario.steps.length - 1, { immediateAction: true });
    } else if (state.activeDemoTour.stepIdx > 0) {
      runDemoStep(scenario, state.activeDemoTour.stepIdx - 1, { immediateAction: true });
    }
  };

  const handleNextOrFinishStep = () => {
    if (!state.activeDemoTour) return;
    const scenario = DEMO_SCENARIOS_CATALOG.find((d) => d.id === state.activeDemoTour.scenarioId);
    if (!scenario) return;
    if (state.activeDemoTour.completed) {
      startInteractiveDemoTour(scenario.id);
    } else if (state.activeDemoTour.stepIdx < scenario.steps.length - 1) {
      runDemoStep(scenario, state.activeDemoTour.stepIdx + 1, { immediateAction: true });
    } else {
      completeInteractiveDemoTour(scenario);
    }
  };

  const handleTogglePause = () => {
    if (!state.activeDemoTour || state.activeDemoTour.completed) return;
    if (_demoPaceMode === "manual") {
      _demoPaceMode = "normal";
      state.activeDemoTour.paused = false;
      const scenario = DEMO_SCENARIOS_CATALOG.find((d) => d.id === state.activeDemoTour.scenarioId);
      const step = scenario?.steps?.[state.activeDemoTour.stepIdx];
      syncDemoControlsState();
      if (scenario && step) {
        startDemoCountdownLoop(computeDemoStepDwellMs(step), () => {
          if (state.activeDemoTour.stepIdx < scenario.steps.length - 1) {
            runDemoStep(scenario, state.activeDemoTour.stepIdx + 1);
          } else {
            completeInteractiveDemoTour(scenario);
          }
        });
      }
      return;
    }
    state.activeDemoTour.paused = !state.activeDemoTour.paused;
    syncDemoControlsState();
  };

  const handleCyclePaceMode = () => {
    const idx = DEMO_PACE_MODES.findIndex((m) => m.id === _demoPaceMode);
    const nextMode = DEMO_PACE_MODES[(idx + 1) % DEMO_PACE_MODES.length];
    _demoPaceMode = nextMode.id;
    if (state.activeDemoTour && !state.activeDemoTour.completed) {
      state.activeDemoTour.paused = _demoPaceMode === "manual";
      const scenario = DEMO_SCENARIOS_CATALOG.find((d) => d.id === state.activeDemoTour.scenarioId);
      const step = scenario?.steps?.[state.activeDemoTour.stepIdx];
      if (scenario && step) {
        startDemoCountdownLoop(computeDemoStepDwellMs(step), () => {
          if (state.activeDemoTour.stepIdx < scenario.steps.length - 1) {
            runDemoStep(scenario, state.activeDemoTour.stepIdx + 1);
          } else {
            completeInteractiveDemoTour(scenario);
          }
        });
      }
    }
    syncDemoControlsState();
  };

  document.getElementById("btn-demo-step-prev")?.addEventListener("click", handlePrevStep);
  document.getElementById("btn-callout-prev")?.addEventListener("click", handlePrevStep);

  document.getElementById("btn-demo-step-next")?.addEventListener("click", handleNextOrFinishStep);
  document.getElementById("btn-callout-next")?.addEventListener("click", handleNextOrFinishStep);

  document.getElementById("btn-demo-step-pause")?.addEventListener("click", handleTogglePause);
  document.getElementById("btn-callout-pause")?.addEventListener("click", handleTogglePause);

  document.getElementById("btn-demo-speed-toggle")?.addEventListener("click", handleCyclePaceMode);
  document.getElementById("btn-callout-speed")?.addEventListener("click", handleCyclePaceMode);

  document.getElementById("btn-demo-next-scenario")?.addEventListener("click", () => {
    const curIdx = state.activeDemoTour?.scenarioIndex || 1;
    const nextScenario = DEMO_SCENARIOS_CATALOG[curIdx % DEMO_SCENARIOS_CATALOG.length];
    if (nextScenario) startInteractiveDemoTour(nextScenario.id);
  });

  document.getElementById("btn-demo-exit")?.addEventListener("click", () => {
    stopInteractiveDemoTour({ scrollToTop: true });
  });
  document.getElementById("btn-callout-close")?.addEventListener("click", () => {
    stopInteractiveDemoTour({ scrollToTop: true });
  });

  // Intentional-Movement Hover-to-Pause on floating callout bubble and docked tour banner (Item 2):
  // Stationary cursors sitting inside the window do NOT halt the tour; only intentional cursor movement
  // pauses countdown for 1.8s so the user can click buttons comfortably.
  const calloutEl = document.getElementById("demo-floating-callout");
  const bannerEl = document.getElementById("active-demo-tour-banner");
  const handleIntentionalPointerMove = (ev) => {
    const prev = _demoLastPointerPos;
    _demoLastPointerPos = { x: ev.clientX, y: ev.clientY };
    const movedDist = prev
      ? Math.hypot(ev.clientX - prev.x, ev.clientY - prev.y)
      : Math.hypot(ev.movementX || 0, ev.movementY || 0);
    if (movedDist < 3) return;
    _demoHoverPaused = true;
    if (_demoHoverResumeTimer) clearTimeout(_demoHoverResumeTimer);
    _demoHoverResumeTimer = setTimeout(() => {
      _demoHoverPaused = false;
    }, 1800);
  };
  [calloutEl, bannerEl].forEach((el) => {
    el?.addEventListener("mousemove", handleIntentionalPointerMove);
    el?.addEventListener("mouseleave", () => {
      _demoHoverPaused = false;
      _demoLastPointerPos = null;
      if (_demoHoverResumeTimer) {
        clearTimeout(_demoHoverResumeTimer);
        _demoHoverResumeTimer = null;
      }
    });
  });

  // Under-stage Tab 4 action buttons & Image Studio 1-click sample/guardrail pills
  document.getElementById("btn-trace-copy-json")?.addEventListener("click", () => {
    if (!state.currentResult) return;
    const payload = {
      badge_name: state.currentResult.badge_name,
      canonical_pamphlet_hash: state.currentResult.canonical_pamphlet_hash,
      first_status_event_ms: state.currentResult.first_status_event_ms || 6.2,
      true_first_content_token_ms: state.currentResult.true_first_content_token_ms || 612,
      finops_cost_estimate: state.currentResult.finops_cost_estimate,
      resolved_location: state.currentResult.deep_research_enrichment?.resolved_location,
    };
    navigator.clipboard?.writeText(JSON.stringify(payload, null, 2));
    showToast("📋 Copied Multi-Agent Workflow Trace & FinOps JSON to clipboard!", "info");
  });

  document.getElementById("btn-trace-test-guardrail")?.addEventListener("click", () => {
    document.getElementById("btn-open-image-studio")?.click();
    const aiTabBtn = document.querySelector('[data-studio-tab="studio-tab-ai"], [data-studio-tab="ai"]');
    aiTabBtn?.click();
    triggerGuardrailDemoVerification();
  });

  document.getElementById("btn-studio-sample-safe")?.addEventListener("click", () => {
    const promptInput = document.getElementById("studio-ai-prompt-input");
    const bannerGuardrailEl = document.getElementById("studio-guardrail-result-banner");
    bannerGuardrailEl?.classList.add("hidden");
    const badgeName = state.currentResult?.badge_name || "Citizenship in the Nation";
    if (promptInput) {
      promptInput.value = `Clean educational Scouting America handbook diagram for ${badgeName}: two adult Scouts BSA instructors in official tan Field Uniform shirts and olive trousers coaching a patrol at a sunny outdoor camp skill station, zero text printed on image.`;
      promptInput.dispatchEvent(new Event("input"));
    }
    showToast("✨ Loaded safe, YPT-compliant instructional diagram prompt.", "info");
  });

  document.getElementById("btn-studio-sample-guardrail")?.addEventListener("click", () => {
    triggerGuardrailDemoVerification();
  });

  // Real-time Spotlight & Callout Repositioning on Both Scroll and Resize (only when not mid-step transition)
  const repositionActiveDemoOverlay = () => {
    _demoScrollRafPending = false;
    if (!state.activeDemoTour || state.activeDemoTour.completed || state.activeDemoTour.transitioning) return;
    const scenario = DEMO_SCENARIOS_CATALOG.find((d) => d.id === state.activeDemoTour.scenarioId);
    const step = scenario?.steps?.[state.activeDemoTour.stepIdx];
    if (step) {
      positionDemoSpotlightAndCallout(
        step.targetSelector,
        `STEP ${state.activeDemoTour.stepIdx + 1} OF ${scenario.steps.length}`,
        step.title,
        step.narration,
        step.placement || "bottom",
        { pulseCursor: false, cursorSelector: step.cursorSelector }
      );
    }
  };

  window.addEventListener("resize", repositionActiveDemoOverlay);
  window.addEventListener(
    "scroll",
    () => {
      if (!state.activeDemoTour || state.activeDemoTour.completed || state.activeDemoTour.transitioning) return;
      if (!_demoScrollRafPending) {
        _demoScrollRafPending = true;
        requestAnimationFrame(repositionActiveDemoOverlay);
      }
    },
    { passive: true, capture: true }
  );
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => {
    initInteractiveGuidedDemoWalkthroughs();
  });
} else {
  initInteractiveGuidedDemoWalkthroughs();
}



